insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (242, 23, 1, 16, 'سورة المؤمنون ١ – ١٦', '«قد أفلح المؤمنون»: صفات الوارثين للفردوس، و«ثم أنشأناه خلقاً آخر فتبارك الله أحسن الخالقين»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 242) = $j$[{"lbl": "الآيات ١ – ١١", "q": "قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ ﴿١﴾ ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ ﴿٢﴾ وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ ﴿٣﴾ وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ ﴿٤﴾ وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ ﴿٥﴾ إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ ﴿٦﴾ فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡعَادُونَ ﴿٧﴾ وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ ﴿٨﴾ وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ ﴿٩﴾ أُوْلَـٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ ﴿١٠﴾ ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ ﴿١١﴾", "w": [["قد أفلح المؤمنون", "فاز قطعاً بالنجاة من النار ودخول الجنة المؤمنون."], ["في صلاتهم خاشعون", "ساكنون متطامنون لا يتلفّتون بعين ولا قلب وهم بين يدي ربهم."], ["عن اللغو معرضون", "اللغو: كل ما لا رضى فيه لله من قول وعمل، ومعرضون: منصرفون عنه."], ["للزكاة فاعلون", "مؤدّون."], ["لفروجهم حافظون", "صائنون لها عن النظر إليها وعن إتيان الفاحشة."], ["أو ما ملكت أيمانهم", "من الجواري والسراري إن وُجدن."], ["فمن ابتغى وراء ذلك", "طلب ما دون زوجته وجاريته المملوكة شرعياً."], ["فأولئك هم العادون", "الظالمون المعتدون على حدود الشرع."], ["راعون", "حافظون لأماناتهم وعهودهم."], ["الفردوس", "أعلى درجة في الجنة."]], "m": "يخبر تعالى، وهو الصادق الوعد، بفلاح المؤمنين، والفلاح الفوز بالنجاة من النار ودخول الجنة، ووصفهم بصفات من جمعها ثبت له الفلاح وكان من الوارثين للفردوس: الخشوع في الصلاة، بأن يسكن فيها فلا يلتفت برأسه ولا بطرفه ولا بقلبه، مع رقة قلب ودموع عين، وهذه أكمل حالاته، والإعراض عن اللغو من كل قول وعمل لا يرضي الله، وأداء الزكاة، وحفظ الفروج إلا على الأزواج أو ما ملكت الأيمان، فمن طلب غير ذلك فأولئك الظالمون المعتدون، ومراعاة الأمانات والعهود بحفظ ما ائتمنوا عليه من قول أو عمل، ومن ذلك سائر التكاليف الشرعية حتى الغسل من الجنابة، وعلى عقودهم الخاصة والعامة فلا خيانة ولا نكث، والمحافظة على الصلوات الخمس بأدائها في أوقاتها مع شروطها وإتمام ركوعها وسجودها. أولئك هم الوارثون الذين يرثون الفردوس هم فيها خالدون، فمن اتصف بها كمل إيمانه.", "h": ["وجوب الخشوع في الصلاة.", "تحريم نكاح المتعة، لأن المتمتّع بها ليست زوجة، إذ لا ترث ولا تورث بخلاف الزوجة، ونكاح المتعة هو النكاح إلى أجل معيّن.", "تحريم العادة السرية، وهي نكاح اليد، وسحاق المرأة، لأن ذلك ليس بنكاح زوجة.", "وجوب أداء الزكاة، ووجوب حفظ الأمانات، ووجوب الوفاء بالعهود.", "تقرير حكم التوارث بين أهل الجنة وأهل النار."], "k": "«الذين هم في صلاتهم خاشعون»… صفة الفلاح الأولى؛ ما الذي يسرق خشوعي، وكيف أستعيده؟"}, {"lbl": "الآيات ١٢ – ١٦", "q": "وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةٖ مِّن طِينٖ ﴿١٢﴾ ثُمَّ جَعَلۡنَٰهُ نُطۡفَةٗ فِي قَرَارٖ مَّكِينٖ ﴿١٣﴾ ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةٗ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةٗ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمٗا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمٗا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ ﴿١٤﴾ ثُمَّ إِنَّكُم بَعۡدَ ذَٰلِكَ لَمَيِّتُونَ ﴿١٥﴾ ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ تُبۡعَثُونَ ﴿١٦﴾", "w": [["من سلالة", "السلالة: ما يُستلّ من الشيء، والمراد بها ما استُلّ من الطين لخلق آدم."], ["نطفة في قرار مكين", "النطفة: قطرة المني، والقرار المكين: الرحم."], ["علقة", "الدم المتجمّد الذي يعلق بالإصبع لو حاول أحد أن يرفعه."], ["مضغة", "قطعة لحم قدر ما يمضغ الآكل."], ["خلقاً آخر", "غير تلك المضغة، إذ بعد نفخ الروح فيها صارت إنساناً."], ["أحسن الخالقين", "الصانعين، فالله يصنع والناس يصنعون، والله أحسن الصانعين."]], "m": "يخبر تعالى عن خلقه الإنسان آدم وذريته، وفيه تتجلّى قدرته وعلمه الموجبة لعبادته: ولقد خلقنا آدم من خلاصة طين، ونفخ فيه من روحه فكان بشراً سوياً، ثم جعلنا ولده نطفة في رحم مكين، ثم صيّرنا النطفة قطعة دم جامدة، ثم صيّرناها قطعة لحم قدر ما يُمضغ، ثم خلقنا المضغة عظاماً فكسونا العظام لحماً، ثم أنشأناه بنفخ الروح خلقاً آخر غير ما كان، إنساناً بعد أن كان جماداً لا روح فيه، فتبارك الله أحسن الخالقين، أثنى على نفسه بما هو أهله، إذ لا خالق إلا هو، ويُطلق الخلق على الصناعة. ثم إنكم بعد ذلك تعيشون المدة المحدّدة ثم تموتون، ثم إنكم يوم القيامة تُبعثون أحياء للحساب والجزاء لحياة أبدية لا يعقبها موت.", "h": ["بيان مظاهر قدرة الله وعلمه وحكمته.", "بيان خلق الإنسان والأطوار التي يمر بها.", "بيان مآل الإنسان بعد خلقه.", "تقرير عقيدة البعث والجزاء التي أنكرها الملاحدة والمشركون."], "k": "«فتبارك الله أحسن الخالقين»… أنظر إلى يدي وعيني؛ من صنعها؟ فأحمد الصانع."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 242;
