insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (243, 23, 17, 30, 'سورة المؤمنون ١٧ – ٣٠', '«وأنزلنا من السماء ماء بقدر»، وقصة نوح ﵇: «رب انصرني بما كذّبون»، و«وقل رب أنزلني منزلاً مباركاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 243) = $j$[{"lbl": "الآيات ١٧ – ٢٢", "q": "وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ ﴿١٧﴾ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّـٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ ﴿١٨﴾ فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّـٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ ﴿١٩﴾ وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ ﴿٢٠﴾ وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ ﴿٢١﴾ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ ﴿٢٢﴾", "w": [["سبع طرائق", "سبع سماوات، كل سماء يقال لها طريقة لأن بعضها مطروق فوق بعض."], ["ماء بقدر", "بمقدار معيّن لا يزيد ولا ينقص."], ["من طور سيناء", "جبل يقال له جبل طور سيناء."], ["تنبت بالدهن", "تنبت بثمر فيه الدهن، وهو الزيت."], ["وصبغ للآكلين", "يغمس الآكل فيه اللقمة ويأكلها."], ["في الأنعام لعبرة", "الأنعام: الإبل والبقر والغنم، والعبرة لمن تأمّل خلقها ومنافعها."], ["مما في بطونها", "من اللبن."], ["منافع كثيرة", "كالوبر والصوف واللبن والركوب."], ["ومنها تأكلون", "من لحومها."], ["تُحملون", "تركبون الإبل في البر والسفن في البحر."]], "m": "ما زال السياق في ذكر نعمه على الإنسان لعله يذكر فيشكر: ولقد خلقنا فوقكم سبع سماوات طبقاً فوق طبق، وما كنا عن خلقنا غافلين، وبذلك انتظم الكون والحياة، وإلا لخرب كل شيء. وأنزلنا من السماء ماء المطر بقدر الحاجة، فأسكناه في الأرض، وإنا على إذهابه لقادرون، فأنشأنا لكم به بساتين من نخيل وأعناب، وذكرهما لأن العرب يعرفونهما، النخيل بالمدينة والعنب بالطائف، لكم فيها فواكه كثيرة ومنها تأكلون. وشجرة الزيتون تخرج من طور سيناء، بزيتها يُدهن ويُؤتدم فتُصبغ به اللقمة. وإن لكم في الأنعام لعبرة، نسقيكم من ألبان تخرج من بطونها، ولكم فيها منافع كصوفها ووبرها، ومنها تأكلون، وعلى الإبل في البر وعلى السفن في البحر تُحملون، أفلا تشكرون الله فتعبدونه وتوحّدونه؟", "h": ["بيان قدرة الله تعالى وعظمته في خلق السماوات طرائق، وعدم غفلته عن سائر خلقه، فسار كل شيء لما خُلق له فثبت الكون وانتظمت الحياة.", "بيان إفضال الله تعالى في إنزال الماء بقدر وإسكانه في الأرض وعدم إذهابه، مما يوجب الشكر.", "بيان منافع الزيت، حيث هو للدهن والائتدام والاستصباح.", "فضل الله على العباد في خلق الأنعام والسفن للانتفاع بها في جوانب كثيرة، وحمل السلع من إقليم إلى إقليم.", "وجوب شكر الله تعالى على إنعامه، وذلك بالإيمان به وعبادته وتوحيده فيها."], "k": "«وأنزلنا من السماء ماء بقدر فأسكنّاه في الأرض وإنا على ذهاب به لقادرون»… شربة الماء القادمة؛ أشكر عليها بذكر."}, {"lbl": "الآيات ٢٣ – ٣٠", "q": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ ﴿٢٣﴾ فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَـٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ﴿٢٤﴾ إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٞ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ ﴿٢٥﴾ قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ ﴿٢٦﴾ فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ ﴿٢٧﴾ فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٢٨﴾ وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ ﴿٢٩﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ وَإِن كُنَّا لَمُبۡتَلِينَ ﴿٣٠﴾", "w": [["اعبدوا الله", "وحّدوه بالعبادة إذ ليس لكم من إله غيره."], ["أفلا تتقون", "أتعبدون معه غيره فلا تخافون غضبه وعقابه؟"], ["الملأ", "أعيان البلاد وكبراء القوم."], ["ما هذا إلا بشر مثلكم", "ما نوح إلا بشر مثلكم، فكيف تطيعونه؟"], ["أن يتفضّل عليكم", "يسودكم ويصبح آمراً ناهياً بينكم."], ["لأنزل ملائكة", "لو شاء الله إرسال رسول لأنزل ملائكة رسلاً."], ["رجل به جنّة", "مصاب بمسّ من جنون."], ["فتربّصوا به حتى حين", "لا تسمعوا له وانتظروا به هلاكه أو شفاءه."], ["أن اصنع الفلك", "أعلمناه بطريق سريع خفي: اصنع السفينة."], ["بأعيننا ووحينا", "بمرأى منا، وبتعليمنا إياك صنعها."], ["وفار التنور", "تنور الخبّاز فار منه الماء، آية بداية الطوفان."], ["فاسلك فيها", "أدخل في السفينة."], ["وأهلك", "أولادك ونساءك."], ["ولا تخاطبني في الذين ظلموا", "لا تكلّمني في شأن الظالمين فإني حكمت بإغراقهم."], ["وإن كنا لمبتلين", "لمختبرين."]], "m": "هذا بداية قصص بعد قصة خلق آدم: ولقد أرسلنا نوحاً إلى قومه فقال: يا قوم اعبدوا الله وحده، ما لكم من إله غيره، أفلا تخافون غضبه وعقابه؟ فقال أشرافهم الكافرون: ما نوح إلا بشر مثلكم يريد أن يسودكم، ولو شاء الله لأنزل ملائكة تخبرنا، ما سمعنا بهذا في آبائنا الأولين، إن هو إلا رجل به مسّ من جنون، فانتظروا به أجله ولا تتركوا دينكم لأجله. وبعد قرون بلغت ألف سنة إلا خمسين قال: رب انصرني بسبب تكذيبهم إياي. فأوحينا إليه أن اصنع السفينة بمرأى منا وبتعليمنا، فإذا جاء أمرنا بإهلاكهم وفار التنور بالماء علامة، فأدخل فيها من كل زوجين اثنين، وأهلك من زوجة وولد إلا من سبق عليه القول بالهلاك كامرأته، ولا تسألني في الذين ظلموا إنهم مغرقون. فإذا استقررت أنت ومن معك على السفينة فقل: الحمد لله الذي نجّانا من القوم الظالمين، وقل: رب أنزلني منزلاً مباركاً من الأرض وأنت خير المنزلين. إن في ذلك لدلائل على قدرة الله ووجوب توحيده، وإن كنا لمختبرين عبادنا بالخير والشر ليُرى الكافر من المؤمن.", "h": ["إثبات الوحي الإلهي، وتقرير النبوة المحمدية.", "تقرير حادثة الطوفان المعروفة لدى المؤرخين.", "بيان عاقبة الظلم، وأنه هلاك الظالمين.", "سنيّة قول: بسم الله، والحمد لله، «سبحان الذي سخّر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون» عند ركوب الدابة أو السفينة ونحوها كالسيارة والطيارة.", "استحباب الدعاء وسؤال الله تعالى ما العبد في حاجة إليه من خير الدنيا.", "بيان سرّ ذكر قصة نوح، وهو ما فيها من العظات والعبر."], "k": "«رب أنزلني منزلاً مباركاً وأنت خير المنزلين»… بيت أسكنه أو مكان أنتقل إليه؛ أدعو بها قبل أن أدخله."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 243;
insert into public.tdb_cards(topic, i, body) select 243, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٧ – ٢٢", "q": "وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ ﴿١٧﴾ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّـٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ ﴿١٨﴾ فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّـٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ ﴿١٩﴾ وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ ﴿٢٠﴾ وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ ﴿٢١﴾ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ ﴿٢٢﴾", "w": [["سبع طرائق", "سبع سماوات، كل سماء يقال لها طريقة لأن بعضها مطروق فوق بعض."], ["ماء بقدر", "بمقدار معيّن لا يزيد ولا ينقص."], ["من طور سيناء", "جبل يقال له جبل طور سيناء."], ["تنبت بالدهن", "تنبت بثمر فيه الدهن، وهو الزيت."], ["وصبغ للآكلين", "يغمس الآكل فيه اللقمة ويأكلها."], ["في الأنعام لعبرة", "الأنعام: الإبل والبقر والغنم، والعبرة لمن تأمّل خلقها ومنافعها."], ["مما في بطونها", "من اللبن."], ["منافع كثيرة", "كالوبر والصوف واللبن والركوب."], ["ومنها تأكلون", "من لحومها."], ["تُحملون", "تركبون الإبل في البر والسفن في البحر."]], "m": "ما زال السياق في ذكر نعمه على الإنسان لعله يذكر فيشكر: ولقد خلقنا فوقكم سبع سماوات طبقاً فوق طبق، وما كنا عن خلقنا غافلين، وبذلك انتظم الكون والحياة، وإلا لخرب كل شيء. وأنزلنا من السماء ماء المطر بقدر الحاجة، فأسكناه في الأرض، وإنا على إذهابه لقادرون، فأنشأنا لكم به بساتين من نخيل وأعناب، وذكرهما لأن العرب يعرفونهما، النخيل بالمدينة والعنب بالطائف، لكم فيها فواكه كثيرة ومنها تأكلون. وشجرة الزيتون تخرج من طور سيناء، بزيتها يُدهن ويُؤتدم فتُصبغ به اللقمة. وإن لكم في الأنعام لعبرة، نسقيكم من ألبان تخرج من بطونها، ولكم فيها منافع كصوفها ووبرها، ومنها تأكلون، وعلى الإبل في البر وعلى السفن في البحر تُحملون، أفلا تشكرون الله فتعبدونه وتوحّدونه؟", "h": ["بيان قدرة الله تعالى وعظمته في خلق السماوات طرائق، وعدم غفلته عن سائر خلقه، فسار كل شيء لما خُلق له فثبت الكون وانتظمت الحياة.", "بيان إفضال الله تعالى في إنزال الماء بقدر وإسكانه في الأرض وعدم إذهابه، مما يوجب الشكر.", "بيان منافع الزيت، حيث هو للدهن والائتدام والاستصباح.", "فضل الله على العباد في خلق الأنعام والسفن للانتفاع بها في جوانب كثيرة، وحمل السلع من إقليم إلى إقليم.", "وجوب شكر الله تعالى على إنعامه، وذلك بالإيمان به وعبادته وتوحيده فيها."], "k": "«وأنزلنا من السماء ماء بقدر فأسكنّاه في الأرض وإنا على ذهاب به لقادرون»… شربة الماء القادمة؛ أشكر عليها بذكر."}, {"lbl": "الآيات ٢٣ – ٣٠", "q": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ ﴿٢٣﴾ فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَـٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ﴿٢٤﴾ إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٞ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ ﴿٢٥﴾ قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ ﴿٢٦﴾ فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ ﴿٢٧﴾ فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٢٨﴾ وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ ﴿٢٩﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ وَإِن كُنَّا لَمُبۡتَلِينَ ﴿٣٠﴾", "w": [["اعبدوا الله", "وحّدوه بالعبادة إذ ليس لكم من إله غيره."], ["أفلا تتقون", "أتعبدون معه غيره فلا تخافون غضبه وعقابه؟"], ["الملأ", "أعيان البلاد وكبراء القوم."], ["ما هذا إلا بشر مثلكم", "ما نوح إلا بشر مثلكم، فكيف تطيعونه؟"], ["أن يتفضّل عليكم", "يسودكم ويصبح آمراً ناهياً بينكم."], ["لأنزل ملائكة", "لو شاء الله إرسال رسول لأنزل ملائكة رسلاً."], ["رجل به جنّة", "مصاب بمسّ من جنون."], ["فتربّصوا به حتى حين", "لا تسمعوا له وانتظروا به هلاكه أو شفاءه."], ["أن اصنع الفلك", "أعلمناه بطريق سريع خفي: اصنع السفينة."], ["بأعيننا ووحينا", "بمرأى منا، وبتعليمنا إياك صنعها."], ["وفار التنور", "تنور الخبّاز فار منه الماء، آية بداية الطوفان."], ["فاسلك فيها", "أدخل في السفينة."], ["وأهلك", "أولادك ونساءك."], ["ولا تخاطبني في الذين ظلموا", "لا تكلّمني في شأن الظالمين فإني حكمت بإغراقهم."], ["وإن كنا لمبتلين", "لمختبرين."]], "m": "هذا بداية قصص بعد قصة خلق آدم: ولقد أرسلنا نوحاً إلى قومه فقال: يا قوم اعبدوا الله وحده، ما لكم من إله غيره، أفلا تخافون غضبه وعقابه؟ فقال أشرافهم الكافرون: ما نوح إلا بشر مثلكم يريد أن يسودكم، ولو شاء الله لأنزل ملائكة تخبرنا، ما سمعنا بهذا في آبائنا الأولين، إن هو إلا رجل به مسّ من جنون، فانتظروا به أجله ولا تتركوا دينكم لأجله. وبعد قرون بلغت ألف سنة إلا خمسين قال: رب انصرني بسبب تكذيبهم إياي. فأوحينا إليه أن اصنع السفينة بمرأى منا وبتعليمنا، فإذا جاء أمرنا بإهلاكهم وفار التنور بالماء علامة، فأدخل فيها من كل زوجين اثنين، وأهلك من زوجة وولد إلا من سبق عليه القول بالهلاك كامرأته، ولا تسألني في الذين ظلموا إنهم مغرقون. فإذا استقررت أنت ومن معك على السفينة فقل: الحمد لله الذي نجّانا من القوم الظالمين، وقل: رب أنزلني منزلاً مباركاً من الأرض وأنت خير المنزلين. إن في ذلك لدلائل على قدرة الله ووجوب توحيده، وإن كنا لمختبرين عبادنا بالخير والشر ليُرى الكافر من المؤمن.", "h": ["إثبات الوحي الإلهي، وتقرير النبوة المحمدية.", "تقرير حادثة الطوفان المعروفة لدى المؤرخين.", "بيان عاقبة الظلم، وأنه هلاك الظالمين.", "سنيّة قول: بسم الله، والحمد لله، «سبحان الذي سخّر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون» عند ركوب الدابة أو السفينة ونحوها كالسيارة والطيارة.", "استحباب الدعاء وسؤال الله تعالى ما العبد في حاجة إليه من خير الدنيا.", "بيان سرّ ذكر قصة نوح، وهو ما فيها من العظات والعبر."], "k": "«رب أنزلني منزلاً مباركاً وأنت خير المنزلين»… بيت أسكنه أو مكان أنتقل إليه؛ أدعو بها قبل أن أدخله."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (244, 23, 31, 50, 'سورة المؤمنون ٣١ – ٥٠', 'قصة هود ﵇: «هيهات هيهات لما توعدون»، و«ثم أرسلنا رسلنا تترى»، وموسى وهارون، و«وجعلنا ابن مريم وأمه آية»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 244) = $j$[{"lbl": "الآيات ٣١ – ٣٨", "q": "ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ ﴿٣١﴾ فَأَرۡسَلۡنَا فِيهِمۡ رَسُولٗا مِّنۡهُمۡ أَنِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ ﴿٣٢﴾ وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ ﴿٣٣﴾ وَلَئِنۡ أَطَعۡتُم بَشَرٗا مِّثۡلَكُمۡ إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ ﴿٣٤﴾ أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ ﴿٣٥﴾ ۞هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ ﴿٣٦﴾ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ ﴿٣٧﴾ إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ ﴿٣٨﴾", "w": [["قرناً آخرين", "خلقنا من بعد قوم نوح قوماً آخرين هم عاد."], ["رسولاً منهم", "هو هود ﵇."], ["أن اعبدوا الله ما لكم من إله غيره", "قولوا: لا إله إلا الله، واعبدوا الله وحده."], ["وأترفناهم", "أنعمنا عليهم بالمال وسعة العيش."], ["أنكم مخرجون", "أحياء من قبوركم بعد موتكم."], ["هيهات هيهات", "بَعُد بعداً كبيراً وقوع ما يعدكم."], ["إن هي إلا حياتنا الدنيا", "ما هي إلا حياتنا الدنيا وليس وراءها حياة."], ["إن هو إلا رجل افترى", "ما هو إلا رجل كذب على الله."]], "m": "هذه بداية قصة هود بعد قصة نوح: ثم أوجدنا من بعد قوم نوح الهالكين قوماً آخرين هم عاد، فأرسلنا فيهم هوداً منهم يقول: اعبدوا الله ما لكم من إله غيره، فالخالق الرازق الله وحده، أفلا تخافون عقوبته؟ وقال الأشراف من قومه الذين كفروا وكذّبوا بالبعث، وقد وسّعنا عليهم في الدنيا فأسرفوا في الملاذ: ما هذا إلا بشر مثلكم، يأكل مما تأكلون ويشرب مما تشربون، فكيف ترضون بسيادته عليكم؟ ولئن أطعتم بشراً مثلكم إنكم إذاً لخاسرون حياتكم ومكانتكم. أيعدكم أنكم إذا متّم وكنتم تراباً وعظاماً أنكم مخرجون أحياء من قبوركم؟ بَعُد ما يعدكم به بعداً كبيراً، إن هي إلا حياتنا الدنيا، جيل يموت وجيل يحيا، وما نحن بمبعوثين، إن هو إلا رجل اختلق على الله كذباً، وما نحن له بمؤمنين.", "h": ["بيان سنة الله تعالى في إرسال الرسل، وما تبتدئ به دعوتهم، وهو لا إله إلا الله.", "أهل الكفر لا يصدر عنهم إلا ما هو شر وباطل لفساد قلوبهم.", "الترف يسبّب كثيراً من المفاسد والشرور، ولهذا يجب أن يُحذر بالاقتصاد.", "تقرير عقيدة البعث والجزاء وإثباتها، وهي ما ينكره الملاحدة هروباً من الاستقامة.", "بيان شبهة عامة المشركين، وهي: كيف يكون الرسول رجلاً من البشر؟"], "k": "«وأترفناهم في الحياة الدنيا»… الترف الذي يحيط بي، هل يقرّبني من الحق أم يحجبني عنه؟"}, {"lbl": "الآيات ٣٩ – ٤٤", "q": "قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ ﴿٣٩﴾ قَالَ عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ ﴿٤٠﴾ فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءٗۚ فَبُعۡدٗا لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٤١﴾ ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِينَ ﴿٤٢﴾ مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ ﴿٤٣﴾ ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةٗ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضٗا وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدٗا لِّقَوۡمٖ لَّا يُؤۡمِنُونَ ﴿٤٤﴾", "w": [["عما قليل", "عن قليل من الزمن."], ["ليصبحنّ نادمين", "ليصيرنّ نادمين على كفرهم وتكذيبهم."], ["فأخذتهم الصيحة", "صيحة العذاب والهلاك."], ["فجعلناهم غثاءً", "كغثاء السيل، وهو ما يجمعه الوادي من العيدان والنبات اليابس."], ["فبعداً", "هلاكاً لهم."], ["ثم أنشأنا", "أوجدنا من بعدهم أهل قرون آخرين كقوم صالح وإبراهيم."], ["تترى", "يتبع بعضها بعضاً، الواحدة عقب الأخرى."], ["وجعلناهم أحاديث", "أهلكناهم وتركناهم قصصاً تُقصّ وأخباراً تتناقل."]], "m": "قال هود: رب انصرني بسبب تكذيبهم لي وإصرارهم على الكفر بك، فأجابه ربه: عن قليل من الوقت ليصبحنّ نادمين على كفرهم وتكذيبهم، فلم يمض إلا قليل حتى أخذتهم صيحة الهلاك مع ريح صرصر في أيام نحسات، فإذا هم كغثاء السيل لا حياة فيهم، فبعداً للقوم الظالمين بالشرك والتكذيب. ثم أوجدنا بعد عاد أهل قرون آخرين كقوم صالح وإبراهيم ولوط وشعيب، ما تسبق أمة أجلها المحدود لهلاكها وما يستأخرون عنه. ثم أرسلنا رسلنا يتبع بعضهم بعضاً، كلما جاء أمة رسولها كذّبوه، فأتبعنا بعضهم بعضاً في الهلاك، وجعلناهم أحاديث لمن بعدهم يروون أخبارهم، فبعداً لقوم لا يؤمنون، وفيه تهديد قوي لقريش.", "h": ["استجابة الله دعوة المظلومين من عباده، لا سيما إن كانوا عباداً صالحين.", "الآجال للأفراد أو الأمم لا تتقدّم ولا تتأخّر، سنة من سنن الله تعالى في خلقه.", "تقرير حقيقة تاريخية علمية، وهي أن الأمم السابقة كلها هلكت بتكذيبها وكفرها، ولم ينج منها عند نزول العذاب إلا المؤمنون مع رسولهم.", "كرامة هذه الأمة المحمدية أن الله تعالى لا يهلكها هلاكاً عاماً، بل تبقى بقاء الحياة تقوم بها الحجة لله تعالى على الأمم والشعوب المعاصرة لها."], "k": "«فجعلناهم أحاديث»… سيبقى مني حديث يُروى؛ فبأي حديث أحب أن أُذكر؟"}, {"lbl": "الآيات ٤٥ – ٥٠", "q": "ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ﴿٤٥﴾ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ ﴿٤٦﴾ فَقَالُوٓاْ أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَٰبِدُونَ ﴿٤٧﴾ فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ٱلۡمُهۡلَكِينَ ﴿٤٨﴾ وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ لَعَلَّهُمۡ يَهۡتَدُونَ ﴿٤٩﴾ وَجَعَلۡنَا ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةٗ وَءَاوَيۡنَٰهُمَآ إِلَىٰ رَبۡوَةٖ ذَاتِ قَرَارٖ وَمَعِينٖ ﴿٥٠﴾", "w": [["بآياتنا وسلطان مبين", "الآيات التسع، وهي الحجة والسلطان المبين."], ["وكانوا قوماً عالين", "علوا أهل تلك البلاد قهراً واستبداداً."], ["وقومهما لنا عابدون", "مطيعون ذليلون نستخدمهم فيما نشاء."], ["ولقد آتينا موسى الكتاب", "التوراة."], ["وجعلنا ابن مريم وأمه آية", "عيسى ووالدته حجة على وجود الله وقدرته وعلمه."], ["إلى ربوة ذات قرار ومعين", "إلى مكان مرتفع ذي استقرار، فيه ماء جارٍ عذب وفواكه."]], "m": "ما زال السياق في نبذ من قصص الأولين: ثم أرسلنا بعد تلك الأمم موسى وأخاه هارون بالآيات والحجج البيّنة إلى فرعون ملك مصر وملئه، يدعوانهم إلى التوحيد والخروج ببني إسرائيل إلى الأرض المباركة، فاستكبروا عن قبول الحق، وكانوا قاهرين لأهل تلك البلاد مستبدّين، فقالوا متعجّبين: أنؤمن لبشرين مثلنا فنأتمر بأمرهما، وقومهما بنو إسرائيل لنا خاضعون مطيعون؟ فكذّبوهما فكانوا من المهلكين، أغرقهم الله أجمعين. ولقد آتينا موسى التوراة بعد نجاة بني إسرائيل لعلهم يهتدون بنورها. وجعلنا عيسى وأمه مريم آية، إذ خُلق من غير أب، دالة على قدرة الله الموجبة لتوحيده، وأنزلناهما بعد اضطهاد اليهود لهما إلى ربوة عالية صالحة للاستقرار، بها فاكهة وماء عذب جارٍ، إكراماً لهما.", "h": ["تقرير نبوة كل من موسى وأخيه هارون ﵉.", "التنديد بالاستكبار، وأنه علّة مانعة من قبول الحق.", "مظاهر قدرة الله وعلمه ورحمته في إرسال الرسل بالآيات وفي إهلاك المكذّبين.", "آية ولادة عيسى من غير أب مقرّرة قدرة الله تعالى على إحياء الموتى وبعث الناس من قبورهم للحساب والجزاء."], "k": "«فاستكبروا وكانوا قوماً عالين»… أين يتخفّى الكبر في قلبي فيمنعني من قبول نصيحة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 244;
insert into public.tdb_cards(topic, i, body) select 244, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣١ – ٣٨", "q": "ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ ﴿٣١﴾ فَأَرۡسَلۡنَا فِيهِمۡ رَسُولٗا مِّنۡهُمۡ أَنِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ ﴿٣٢﴾ وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ ﴿٣٣﴾ وَلَئِنۡ أَطَعۡتُم بَشَرٗا مِّثۡلَكُمۡ إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ ﴿٣٤﴾ أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ ﴿٣٥﴾ ۞هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ ﴿٣٦﴾ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ ﴿٣٧﴾ إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ ﴿٣٨﴾", "w": [["قرناً آخرين", "خلقنا من بعد قوم نوح قوماً آخرين هم عاد."], ["رسولاً منهم", "هو هود ﵇."], ["أن اعبدوا الله ما لكم من إله غيره", "قولوا: لا إله إلا الله، واعبدوا الله وحده."], ["وأترفناهم", "أنعمنا عليهم بالمال وسعة العيش."], ["أنكم مخرجون", "أحياء من قبوركم بعد موتكم."], ["هيهات هيهات", "بَعُد بعداً كبيراً وقوع ما يعدكم."], ["إن هي إلا حياتنا الدنيا", "ما هي إلا حياتنا الدنيا وليس وراءها حياة."], ["إن هو إلا رجل افترى", "ما هو إلا رجل كذب على الله."]], "m": "هذه بداية قصة هود بعد قصة نوح: ثم أوجدنا من بعد قوم نوح الهالكين قوماً آخرين هم عاد، فأرسلنا فيهم هوداً منهم يقول: اعبدوا الله ما لكم من إله غيره، فالخالق الرازق الله وحده، أفلا تخافون عقوبته؟ وقال الأشراف من قومه الذين كفروا وكذّبوا بالبعث، وقد وسّعنا عليهم في الدنيا فأسرفوا في الملاذ: ما هذا إلا بشر مثلكم، يأكل مما تأكلون ويشرب مما تشربون، فكيف ترضون بسيادته عليكم؟ ولئن أطعتم بشراً مثلكم إنكم إذاً لخاسرون حياتكم ومكانتكم. أيعدكم أنكم إذا متّم وكنتم تراباً وعظاماً أنكم مخرجون أحياء من قبوركم؟ بَعُد ما يعدكم به بعداً كبيراً، إن هي إلا حياتنا الدنيا، جيل يموت وجيل يحيا، وما نحن بمبعوثين، إن هو إلا رجل اختلق على الله كذباً، وما نحن له بمؤمنين.", "h": ["بيان سنة الله تعالى في إرسال الرسل، وما تبتدئ به دعوتهم، وهو لا إله إلا الله.", "أهل الكفر لا يصدر عنهم إلا ما هو شر وباطل لفساد قلوبهم.", "الترف يسبّب كثيراً من المفاسد والشرور، ولهذا يجب أن يُحذر بالاقتصاد.", "تقرير عقيدة البعث والجزاء وإثباتها، وهي ما ينكره الملاحدة هروباً من الاستقامة.", "بيان شبهة عامة المشركين، وهي: كيف يكون الرسول رجلاً من البشر؟"], "k": "«وأترفناهم في الحياة الدنيا»… الترف الذي يحيط بي، هل يقرّبني من الحق أم يحجبني عنه؟"}, {"lbl": "الآيات ٣٩ – ٤٤", "q": "قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ ﴿٣٩﴾ قَالَ عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ ﴿٤٠﴾ فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءٗۚ فَبُعۡدٗا لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٤١﴾ ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِينَ ﴿٤٢﴾ مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ ﴿٤٣﴾ ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةٗ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضٗا وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدٗا لِّقَوۡمٖ لَّا يُؤۡمِنُونَ ﴿٤٤﴾", "w": [["عما قليل", "عن قليل من الزمن."], ["ليصبحنّ نادمين", "ليصيرنّ نادمين على كفرهم وتكذيبهم."], ["فأخذتهم الصيحة", "صيحة العذاب والهلاك."], ["فجعلناهم غثاءً", "كغثاء السيل، وهو ما يجمعه الوادي من العيدان والنبات اليابس."], ["فبعداً", "هلاكاً لهم."], ["ثم أنشأنا", "أوجدنا من بعدهم أهل قرون آخرين كقوم صالح وإبراهيم."], ["تترى", "يتبع بعضها بعضاً، الواحدة عقب الأخرى."], ["وجعلناهم أحاديث", "أهلكناهم وتركناهم قصصاً تُقصّ وأخباراً تتناقل."]], "m": "قال هود: رب انصرني بسبب تكذيبهم لي وإصرارهم على الكفر بك، فأجابه ربه: عن قليل من الوقت ليصبحنّ نادمين على كفرهم وتكذيبهم، فلم يمض إلا قليل حتى أخذتهم صيحة الهلاك مع ريح صرصر في أيام نحسات، فإذا هم كغثاء السيل لا حياة فيهم، فبعداً للقوم الظالمين بالشرك والتكذيب. ثم أوجدنا بعد عاد أهل قرون آخرين كقوم صالح وإبراهيم ولوط وشعيب، ما تسبق أمة أجلها المحدود لهلاكها وما يستأخرون عنه. ثم أرسلنا رسلنا يتبع بعضهم بعضاً، كلما جاء أمة رسولها كذّبوه، فأتبعنا بعضهم بعضاً في الهلاك، وجعلناهم أحاديث لمن بعدهم يروون أخبارهم، فبعداً لقوم لا يؤمنون، وفيه تهديد قوي لقريش.", "h": ["استجابة الله دعوة المظلومين من عباده، لا سيما إن كانوا عباداً صالحين.", "الآجال للأفراد أو الأمم لا تتقدّم ولا تتأخّر، سنة من سنن الله تعالى في خلقه.", "تقرير حقيقة تاريخية علمية، وهي أن الأمم السابقة كلها هلكت بتكذيبها وكفرها، ولم ينج منها عند نزول العذاب إلا المؤمنون مع رسولهم.", "كرامة هذه الأمة المحمدية أن الله تعالى لا يهلكها هلاكاً عاماً، بل تبقى بقاء الحياة تقوم بها الحجة لله تعالى على الأمم والشعوب المعاصرة لها."], "k": "«فجعلناهم أحاديث»… سيبقى مني حديث يُروى؛ فبأي حديث أحب أن أُذكر؟"}, {"lbl": "الآيات ٤٥ – ٥٠", "q": "ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ﴿٤٥﴾ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ ﴿٤٦﴾ فَقَالُوٓاْ أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَٰبِدُونَ ﴿٤٧﴾ فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ٱلۡمُهۡلَكِينَ ﴿٤٨﴾ وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ لَعَلَّهُمۡ يَهۡتَدُونَ ﴿٤٩﴾ وَجَعَلۡنَا ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةٗ وَءَاوَيۡنَٰهُمَآ إِلَىٰ رَبۡوَةٖ ذَاتِ قَرَارٖ وَمَعِينٖ ﴿٥٠﴾", "w": [["بآياتنا وسلطان مبين", "الآيات التسع، وهي الحجة والسلطان المبين."], ["وكانوا قوماً عالين", "علوا أهل تلك البلاد قهراً واستبداداً."], ["وقومهما لنا عابدون", "مطيعون ذليلون نستخدمهم فيما نشاء."], ["ولقد آتينا موسى الكتاب", "التوراة."], ["وجعلنا ابن مريم وأمه آية", "عيسى ووالدته حجة على وجود الله وقدرته وعلمه."], ["إلى ربوة ذات قرار ومعين", "إلى مكان مرتفع ذي استقرار، فيه ماء جارٍ عذب وفواكه."]], "m": "ما زال السياق في نبذ من قصص الأولين: ثم أرسلنا بعد تلك الأمم موسى وأخاه هارون بالآيات والحجج البيّنة إلى فرعون ملك مصر وملئه، يدعوانهم إلى التوحيد والخروج ببني إسرائيل إلى الأرض المباركة، فاستكبروا عن قبول الحق، وكانوا قاهرين لأهل تلك البلاد مستبدّين، فقالوا متعجّبين: أنؤمن لبشرين مثلنا فنأتمر بأمرهما، وقومهما بنو إسرائيل لنا خاضعون مطيعون؟ فكذّبوهما فكانوا من المهلكين، أغرقهم الله أجمعين. ولقد آتينا موسى التوراة بعد نجاة بني إسرائيل لعلهم يهتدون بنورها. وجعلنا عيسى وأمه مريم آية، إذ خُلق من غير أب، دالة على قدرة الله الموجبة لتوحيده، وأنزلناهما بعد اضطهاد اليهود لهما إلى ربوة عالية صالحة للاستقرار، بها فاكهة وماء عذب جارٍ، إكراماً لهما.", "h": ["تقرير نبوة كل من موسى وأخيه هارون ﵉.", "التنديد بالاستكبار، وأنه علّة مانعة من قبول الحق.", "مظاهر قدرة الله وعلمه ورحمته في إرسال الرسل بالآيات وفي إهلاك المكذّبين.", "آية ولادة عيسى من غير أب مقرّرة قدرة الله تعالى على إحياء الموتى وبعث الناس من قبورهم للحساب والجزاء."], "k": "«فاستكبروا وكانوا قوماً عالين»… أين يتخفّى الكبر في قلبي فيمنعني من قبول نصيحة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (245, 23, 51, 70, 'سورة المؤمنون ٥١ – ٧٠', '«يا أيها الرسل كلوا من الطيبات واعملوا صالحاً»، و«والذين يؤتون ما آتوا وقلوبهم وجلة»، و«بل جاءهم بالحق وأكثرهم للحق كارهون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 245) = $j$[{"lbl": "الآيات ٥١ – ٥٦", "q": "يَـٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ ﴿٥١﴾ وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ ﴿٥٢﴾ فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ ﴿٥٣﴾ فَذَرۡهُمۡ فِي غَمۡرَتِهِمۡ حَتَّىٰ حِينٍ ﴿٥٤﴾ أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ ﴿٥٥﴾ نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ ﴿٥٦﴾", "w": [["كلوا من الطيبات", "من الحلال."], ["واعملوا صالحاً", "بأداء الفرائض وكثير من النوافل."], ["وإن هذه أمتكم", "ملّتكم الإسلامية."], ["فاتقون", "بامتثال أمري واجتناب نهيي."], ["فتقطّعوا أمرهم", "اختلفوا في دينهم فأصبحوا طوائف، هذه يهودية وتلك نصرانية."], ["في غمرتهم", "في ضلالتهم."], ["نسارع لهم", "نعجّل."], ["بل لا يشعرون", "أن ذلك استدراج منا لهم."]], "m": "بعد أن آوى الله عيسى ووالدته إلى الربوة خاطب رسله: يا أيها الرسل كلوا من الحلال، فكان عيسى يأكل من غزل أمه، إذ كانت تغزل الصوف بأجرة، واعملوا صالحاً بأداء الفرائض والإكثار من النوافل، إني بما تعملون عليم فأثيبكم. وإن ملّتكم، الإسلام، ملة واحدة فلا ينبغي الاختلاف فيها، وأنا ربكم فاتّقوني بفعل ما أمرت وترك ما نهيت. فتقطّعوا دينهم فرقاً، ذهبت كل فرقة بقطعة منه، فاليهودية فرق، والنصرانية فرق، والإنجيل أصبح أناجيل، كل حزب بما لديهم فرحون لا يرون الحق إلا فيه، فاتركهم في ضلالتهم حتى حين. وهذا الذي نعاه الله على تلك الأمم وقعت فيه أمة الإسلام فاختلفوا مذاهب وطرقاً، فحلّت بهم المحن نتيجة ذلك. أيحسبون أن ما نمدّهم به من مال وبنين مع اختلافهم وانحرافهم مسارعة لهم في الخيرات؟ بل هو استدراج ليهلكوا، ولكنهم لا يشعرون لشدة غفلتهم.", "h": ["وجوب الأكل من الحلال، ووجوب الشكر بالطاعة لله ورسوله.", "الإسلام دين البشرية جمعاء، ولا يحل الاختلاف فيه، بل يجب التمسك به وترك ما سواه.", "حرمة الاختلاف في الدين، وأنه سبب الكوارث والفتن والمحن.", "إذا انحرفت الأمة عن دين الله ثم رُزقت المال وسعة العيش كان ذلك استدراجاً لها، ولم يكن إكراماً من الله دالّاً على رضاه عنها، بل ما هو إلا فتنة."], "k": "«كلوا من الطيبات واعملوا صالحاً»… أمر الله الرسل بالحلال قبل العمل؛ فهل طيّبت مطعمي؟"}, {"lbl": "الآيات ٥٧ – ٦٢", "q": "إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ ﴿٥٧﴾ وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ ﴿٥٨﴾ وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ ﴿٥٩﴾ وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ ﴿٦٠﴾ أُوْلَـٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ ﴿٦١﴾ وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَيۡنَا كِتَٰبٞ يَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ ﴿٦٢﴾", "w": [["مشفقون", "خائفون."], ["لا يشركون", "بعبادته أحداً."], ["يؤتون ما آتوا وقلوبهم وجلة", "يعطون ما أعطوا وهم خائفون ألا يُقبل منهم ذلك."], ["أنهم إلى ربهم راجعون", "لأنهم إلى ربهم راجعون فيحاسبهم ويسألهم."], ["وهم لها سابقون", "بإذن الله وفي علمه."], ["ولا نكلّف نفساً إلا وسعها", "إلا طاقتها وما تقدر عليه."], ["ولدينا كتاب ينطق بالحق", "ما كتبه الكرام الكاتبون، فإنه ناطق بالحق."], ["وهم لا يُظلمون", "بنقص حسنة ولا بزيادة سيئة."]], "m": "لما نعى على الذين فرّقوا دينهم أثنى على عباده المؤمنين من أهل الخشية: إن الذين هم من خشية ربهم مشفقون، خائفون من عذابه ومن الوقوف بين يديه، والذين هم بآيات ربهم يوقنون، والذين هم بربهم لا يشركون في ذاته ولا صفاته ولا عبادته، والذين يؤتون الزكاة وسائر الحقوق وقلوبهم خائفة أن يكونوا قصّروا، وألا يُقبل منهم، لقوة إيمانهم برجوعهم إلى ربهم ومساءلته لهم: لم قدّمت؟ لم أخّرت؟ أولئك يسارعون في الخيرات وهم لها سابقون، سبق لهم ذلك في الأزل فهنيئاً لهم. ولا نكلّف نفساً إلا طاقتها، ففيه قبول عذر من بذل جهده ولم يلحق بغيره. ولدينا كتاب ينطق بالحق لا يُخفي حسنة من حسناتهم، وفيه وعيد لأهل الشرك بأن أعمالهم محصاة، وهم لا يُظلمون.", "h": ["فضيلة الخشية والإيمان والتوحيد والتواضع والمراقبة لله تعالى.", "بشرى الله تعالى لأهل الإيمان والتقوى.", "تقرير قاعدة رفع الحرج في الدين.", "تقرير كتابة أعمال العباد وإحصاء أعمالهم ومجازاتهم العادلة."], "k": "«يؤتون ما آتوا وقلوبهم وجلة»… أعمل الخير ثم أخاف ألا يُقبل؛ فهل هذا حالي أم أنني أدلّ بعملي؟"}, {"lbl": "الآيات ٦٣ – ٧٠", "q": "بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةٖ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلٞ مِّن دُونِ ذَٰلِكَ هُمۡ لَهَا عَٰمِلُونَ ﴿٦٣﴾ حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ ﴿٦٤﴾ لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ ﴿٦٥﴾ قَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ ﴿٦٦﴾ مُسۡتَكۡبِرِينَ بِهِۦ سَٰمِرٗا تَهۡجُرُونَ ﴿٦٧﴾ أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ جَآءَهُم مَّا لَمۡ يَأۡتِ ءَابَآءَهُمُ ٱلۡأَوَّلِينَ ﴿٦٨﴾ أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ ﴿٦٩﴾ أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ ﴿٧٠﴾", "w": [["في غمرة من هذا", "في جهالة من القرآن وعمى."], ["ولهم أعمال من دون ذلك", "من دون أعمال المؤمنين التي هي الخشية والإيمان بالآيات والتوحيد والمراقبة."], ["هم لها عاملون", "سيعملونها لتكون سبب نهايتهم."], ["إذا هم يجأرون", "يصرخون بأعلى أصواتهم مستغيثين مما حلّ بهم من العذاب."], ["تنكصون", "ترجعون على أعقابكم كراهة سماع القرآن."], ["مستكبرين به", "بالحرم، إذ كانوا يقولون: لا يظهر علينا فيه أحد لأنا أهل الحرم."], ["سامراً تهجرون", "تسمرون بالحرم ليلاً هاجرين الحق، أو تقولون الهُجر من القول كالفحش."], ["رسولهم", "محمداً ﷺ."], ["به جنّة", "مجنون."]], "m": "ليس الأمر كما يحسب المشركون، بل قلوبهم في جهالة وعمى من القرآن، ولهم أعمال من الشر دون أعمال المؤمنين هم لها عاملون، حتى إذا أخذنا مترفيهم بالعذاب في بدر بالقتل والأسر إذا هم يصرخون مستغيثين، فيقال لهم: لا تصرخوا اليوم إنكم منا لا تُنصرون. قد كانت آياتي تُتلى عليكم فكنتم على أعقابكم ترجعون هروباً من سماعها، مستكبرين بالحرم زاعمين أنه لا يظهر عليكم فيه أحد، تسمرون بالليل هاجرين سماع الحق، أو تقولون في سمركم الفحش وما لا خير فيه. أفلم يتدبّروا القرآن الذي يسمعونه فيعرفوا أنه حق؟ أم جاءهم ما لم يأت آباءهم الأولين؟ فقد جاءت رسل ونزلت كتب. أم لم يعرفوا رسولهم محمداً فهم له منكرون؟ إنهم يعرفون صدقه وطهارته منذ صباه. أم يقولون به جنون؟ وأين الجنون من رجل ينطق بالحكمة؟ بل جاءهم بالحق وأكثرهم للحق كارهون، وهذا سرّ إعراضهم، لطول ما ألفوا الباطل، وهذه سنة البشر في كل زمان.", "h": ["غمرة الجهل والتعصّب وعمى التقليد هي سبب إعراض الناس عن الحق.", "لا تنفع التوبة عند معاينة العذاب أو نزوله.", "بيان الذنوب التي أُخذ بها مترفو مكة ببدر، وهي هروبهم من سماع القرآن، واستكبارهم بالحرم واعتزازهم به جهلاً، واجتماعهم في الليالي الطوال يسمرون على اللهو وقول الباطل هاجرين سماع القرآن."], "k": "«أفلم يدّبّروا القول»… آية أقرؤها كل يوم ولم أتدبّرها بعد؛ أقف عندها اليوم."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 245;
insert into public.tdb_cards(topic, i, body) select 245, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥١ – ٥٦", "q": "يَـٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ ﴿٥١﴾ وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ ﴿٥٢﴾ فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ ﴿٥٣﴾ فَذَرۡهُمۡ فِي غَمۡرَتِهِمۡ حَتَّىٰ حِينٍ ﴿٥٤﴾ أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ ﴿٥٥﴾ نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ ﴿٥٦﴾", "w": [["كلوا من الطيبات", "من الحلال."], ["واعملوا صالحاً", "بأداء الفرائض وكثير من النوافل."], ["وإن هذه أمتكم", "ملّتكم الإسلامية."], ["فاتقون", "بامتثال أمري واجتناب نهيي."], ["فتقطّعوا أمرهم", "اختلفوا في دينهم فأصبحوا طوائف، هذه يهودية وتلك نصرانية."], ["في غمرتهم", "في ضلالتهم."], ["نسارع لهم", "نعجّل."], ["بل لا يشعرون", "أن ذلك استدراج منا لهم."]], "m": "بعد أن آوى الله عيسى ووالدته إلى الربوة خاطب رسله: يا أيها الرسل كلوا من الحلال، فكان عيسى يأكل من غزل أمه، إذ كانت تغزل الصوف بأجرة، واعملوا صالحاً بأداء الفرائض والإكثار من النوافل، إني بما تعملون عليم فأثيبكم. وإن ملّتكم، الإسلام، ملة واحدة فلا ينبغي الاختلاف فيها، وأنا ربكم فاتّقوني بفعل ما أمرت وترك ما نهيت. فتقطّعوا دينهم فرقاً، ذهبت كل فرقة بقطعة منه، فاليهودية فرق، والنصرانية فرق، والإنجيل أصبح أناجيل، كل حزب بما لديهم فرحون لا يرون الحق إلا فيه، فاتركهم في ضلالتهم حتى حين. وهذا الذي نعاه الله على تلك الأمم وقعت فيه أمة الإسلام فاختلفوا مذاهب وطرقاً، فحلّت بهم المحن نتيجة ذلك. أيحسبون أن ما نمدّهم به من مال وبنين مع اختلافهم وانحرافهم مسارعة لهم في الخيرات؟ بل هو استدراج ليهلكوا، ولكنهم لا يشعرون لشدة غفلتهم.", "h": ["وجوب الأكل من الحلال، ووجوب الشكر بالطاعة لله ورسوله.", "الإسلام دين البشرية جمعاء، ولا يحل الاختلاف فيه، بل يجب التمسك به وترك ما سواه.", "حرمة الاختلاف في الدين، وأنه سبب الكوارث والفتن والمحن.", "إذا انحرفت الأمة عن دين الله ثم رُزقت المال وسعة العيش كان ذلك استدراجاً لها، ولم يكن إكراماً من الله دالّاً على رضاه عنها، بل ما هو إلا فتنة."], "k": "«كلوا من الطيبات واعملوا صالحاً»… أمر الله الرسل بالحلال قبل العمل؛ فهل طيّبت مطعمي؟"}, {"lbl": "الآيات ٥٧ – ٦٢", "q": "إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ ﴿٥٧﴾ وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ ﴿٥٨﴾ وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ ﴿٥٩﴾ وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ ﴿٦٠﴾ أُوْلَـٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ ﴿٦١﴾ وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَيۡنَا كِتَٰبٞ يَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ ﴿٦٢﴾", "w": [["مشفقون", "خائفون."], ["لا يشركون", "بعبادته أحداً."], ["يؤتون ما آتوا وقلوبهم وجلة", "يعطون ما أعطوا وهم خائفون ألا يُقبل منهم ذلك."], ["أنهم إلى ربهم راجعون", "لأنهم إلى ربهم راجعون فيحاسبهم ويسألهم."], ["وهم لها سابقون", "بإذن الله وفي علمه."], ["ولا نكلّف نفساً إلا وسعها", "إلا طاقتها وما تقدر عليه."], ["ولدينا كتاب ينطق بالحق", "ما كتبه الكرام الكاتبون، فإنه ناطق بالحق."], ["وهم لا يُظلمون", "بنقص حسنة ولا بزيادة سيئة."]], "m": "لما نعى على الذين فرّقوا دينهم أثنى على عباده المؤمنين من أهل الخشية: إن الذين هم من خشية ربهم مشفقون، خائفون من عذابه ومن الوقوف بين يديه، والذين هم بآيات ربهم يوقنون، والذين هم بربهم لا يشركون في ذاته ولا صفاته ولا عبادته، والذين يؤتون الزكاة وسائر الحقوق وقلوبهم خائفة أن يكونوا قصّروا، وألا يُقبل منهم، لقوة إيمانهم برجوعهم إلى ربهم ومساءلته لهم: لم قدّمت؟ لم أخّرت؟ أولئك يسارعون في الخيرات وهم لها سابقون، سبق لهم ذلك في الأزل فهنيئاً لهم. ولا نكلّف نفساً إلا طاقتها، ففيه قبول عذر من بذل جهده ولم يلحق بغيره. ولدينا كتاب ينطق بالحق لا يُخفي حسنة من حسناتهم، وفيه وعيد لأهل الشرك بأن أعمالهم محصاة، وهم لا يُظلمون.", "h": ["فضيلة الخشية والإيمان والتوحيد والتواضع والمراقبة لله تعالى.", "بشرى الله تعالى لأهل الإيمان والتقوى.", "تقرير قاعدة رفع الحرج في الدين.", "تقرير كتابة أعمال العباد وإحصاء أعمالهم ومجازاتهم العادلة."], "k": "«يؤتون ما آتوا وقلوبهم وجلة»… أعمل الخير ثم أخاف ألا يُقبل؛ فهل هذا حالي أم أنني أدلّ بعملي؟"}, {"lbl": "الآيات ٦٣ – ٧٠", "q": "بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةٖ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلٞ مِّن دُونِ ذَٰلِكَ هُمۡ لَهَا عَٰمِلُونَ ﴿٦٣﴾ حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ ﴿٦٤﴾ لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ ﴿٦٥﴾ قَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ ﴿٦٦﴾ مُسۡتَكۡبِرِينَ بِهِۦ سَٰمِرٗا تَهۡجُرُونَ ﴿٦٧﴾ أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ جَآءَهُم مَّا لَمۡ يَأۡتِ ءَابَآءَهُمُ ٱلۡأَوَّلِينَ ﴿٦٨﴾ أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ ﴿٦٩﴾ أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ ﴿٧٠﴾", "w": [["في غمرة من هذا", "في جهالة من القرآن وعمى."], ["ولهم أعمال من دون ذلك", "من دون أعمال المؤمنين التي هي الخشية والإيمان بالآيات والتوحيد والمراقبة."], ["هم لها عاملون", "سيعملونها لتكون سبب نهايتهم."], ["إذا هم يجأرون", "يصرخون بأعلى أصواتهم مستغيثين مما حلّ بهم من العذاب."], ["تنكصون", "ترجعون على أعقابكم كراهة سماع القرآن."], ["مستكبرين به", "بالحرم، إذ كانوا يقولون: لا يظهر علينا فيه أحد لأنا أهل الحرم."], ["سامراً تهجرون", "تسمرون بالحرم ليلاً هاجرين الحق، أو تقولون الهُجر من القول كالفحش."], ["رسولهم", "محمداً ﷺ."], ["به جنّة", "مجنون."]], "m": "ليس الأمر كما يحسب المشركون، بل قلوبهم في جهالة وعمى من القرآن، ولهم أعمال من الشر دون أعمال المؤمنين هم لها عاملون، حتى إذا أخذنا مترفيهم بالعذاب في بدر بالقتل والأسر إذا هم يصرخون مستغيثين، فيقال لهم: لا تصرخوا اليوم إنكم منا لا تُنصرون. قد كانت آياتي تُتلى عليكم فكنتم على أعقابكم ترجعون هروباً من سماعها، مستكبرين بالحرم زاعمين أنه لا يظهر عليكم فيه أحد، تسمرون بالليل هاجرين سماع الحق، أو تقولون في سمركم الفحش وما لا خير فيه. أفلم يتدبّروا القرآن الذي يسمعونه فيعرفوا أنه حق؟ أم جاءهم ما لم يأت آباءهم الأولين؟ فقد جاءت رسل ونزلت كتب. أم لم يعرفوا رسولهم محمداً فهم له منكرون؟ إنهم يعرفون صدقه وطهارته منذ صباه. أم يقولون به جنون؟ وأين الجنون من رجل ينطق بالحكمة؟ بل جاءهم بالحق وأكثرهم للحق كارهون، وهذا سرّ إعراضهم، لطول ما ألفوا الباطل، وهذه سنة البشر في كل زمان.", "h": ["غمرة الجهل والتعصّب وعمى التقليد هي سبب إعراض الناس عن الحق.", "لا تنفع التوبة عند معاينة العذاب أو نزوله.", "بيان الذنوب التي أُخذ بها مترفو مكة ببدر، وهي هروبهم من سماع القرآن، واستكبارهم بالحرم واعتزازهم به جهلاً، واجتماعهم في الليالي الطوال يسمرون على اللهو وقول الباطل هاجرين سماع القرآن."], "k": "«أفلم يدّبّروا القول»… آية أقرؤها كل يوم ولم أتدبّرها بعد؛ أقف عندها اليوم."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (246, 23, 71, 92, 'سورة المؤمنون ٧١ – ٩٢', '«ولو اتبع الحق أهواءهم لفسدت السماوات والأرض»، و«قل لمن الأرض ومن فيها… قل من بيده ملكوت كل شيء»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 246) = $j$[{"lbl": "الآيات ٧١ – ٧٧", "q": "وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ ﴿٧١﴾ أَمۡ تَسۡـَٔلُهُمۡ خَرۡجٗا فَخَرَاجُ رَبِّكَ خَيۡرٞۖ وَهُوَ خَيۡرُ ٱلرَّـٰزِقِينَ ﴿٧٢﴾ وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٧٣﴾ وَإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ ﴿٧٤﴾ ۞وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرّٖ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ﴿٧٥﴾ وَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ ﴿٧٦﴾ حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابٗا ذَا عَذَابٖ شَدِيدٍ إِذَا هُمۡ فِيهِ مُبۡلِسُونَ ﴿٧٧﴾", "w": [["ولو اتبع الحق أهواءهم", "ما يهوونه ويشتهونه."], ["أتيناهم بذكرهم", "بالقرآن العظيم الذي فيه ذكرهم، به يذكرون ويُذكرون."], ["أم تسألهم خرجاً", "مالاً مقابل إبلاغك لهم دعوة ربهم."], ["فخراج ربك خير", "ما يرزقكه الله خير، وهو خير الرازقين."], ["إلى صراط مستقيم", "إلى الإسلام."], ["عن الصراط لناكبون", "عن الإسلام متنكّبون، جاعلوه على منكب أي جانب."], ["للجّوا في طغيانهم يعمهون", "لتمادوا في طغيانهم مصرّين عليه."], ["فما استكانوا", "ما ذلّوا ولا خضعوا."], ["إذا هم فيه مبلسون", "آيسون قانطون."]], "m": "ولو اتبع الحق النازل من عند الله أهواء المشركين فوافقهم عليه لفسد الكون كله علويّه وسفليّه، لأنهم أهل باطل لا يرون إلا الباطل. بل أتيناهم بالقرآن الذي به يذكرون وهو سبب شرفهم، فهم عن ذكرهم معرضون لفساد قلوبهم. أم تسألهم أجراً على التبليغ؟ فثواب ربك خير، وهو خير الرازقين، وحاشاه ﷺ. وإنك لتدعوهم إلى الإسلام طريق السعادة، وإن الذين لا يؤمنون بالآخرة عن الصراط لمبتعدون، فالقلب الذي لا يعمره الإيمان بلقاء الله ضد كل خير. ولو رحمناهم فكشفنا ما بهم من قحط وجوع لتمادوا في طغيانهم حيارى. ولقد أخذناهم بسنوات الجدب بدعوة الرسول ﷺ، وبالقتل في بدر، فما ذلّوا لربهم وما تضرّعوا، لظلمة نفوسهم، حتى إذا فتحنا عليهم باب عذاب شديد إذا هم فيه آيسون من كل خير.", "h": ["خطر اتباع الهوى وما يفضي إليه من الهلاك والخسران.", "الصراط المستقيم الموصل إلى السعادة والكمال هو الإسلام لا غير.", "التكذيب بيوم القيامة وما يتم فيه من حساب وجزاء هو الباعث على كل شر.", "من آثار ظلمة النفس نتيجة الكفر: اليأس والقنوط والتمادي في الشر والفساد."], "k": "«فما استكانوا لربهم وما يتضرّعون»… حين تصيبني شدة، هل أتضرّع أم أتصلّب؟"}, {"lbl": "الآيات ٧٨ – ٨٣", "q": "وَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ ﴿٧٨﴾ وَهُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ ﴿٧٩﴾ وَهُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ وَلَهُ ٱخۡتِلَٰفُ ٱلَّيۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ ﴿٨٠﴾ بَلۡ قَالُواْ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ ﴿٨١﴾ قَالُوٓاْ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ ﴿٨٢﴾ لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٨٣﴾", "w": [["أنشأ لكم السمع", "خلق وأوجد لكم الأسماع والأبصار."], ["والأفئدة", "جمع فؤاد، وهو القلب."], ["قليلاً ما تشكرون", "ما تشكرون إلا قليلاً."], ["ذرأكم", "خلقكم."], ["وإليه تحشرون", "تجمعون إليه بعد إحيائكم وخروجكم من قبوركم."], ["وله اختلاف الليل والنهار", "إليه إيجاد الليل والنهار، وظلمة الليل وضياء النهار."], ["أفلا تعقلون", "فتعرفوا أن الله هو المعبود الحق، إذ هو الرب الحق."], ["إلا أساطير الأولين", "ما تقولون من البعث إلا حكايات الأولين، جمع أسطورة."]], "m": "ما زال السياق في دعوة المنكرين للبعث بعرض الأدلة العقلية: وهو الذي خلق لكم الأسماع والأبصار والقلوب، قادر على إحيائكم بعد موتكم، قليلاً ما تشكرونه على ذلك بالإيمان والطاعة. وهو الذي خلقكم في الأرض وإليه تُجمعون، فالقادر على خلقكم فيها قادر على إعادتكم. وهو الذي يحيي النطفة بنفخ الروح فتكون بشراً، ويميتكم بعد انقضاء آجالكم، وله اختلاف الليل والنهار وتعاقبهما، أفلا تعقلون أن من هذه قدرته قادر على بعثكم؟ بل بدل أن يؤمنوا قالوا مثل ما قال الأولون: أئذا متنا وكنا تراباً وعظاماً أئنا لمبعوثون؟ لقد وُعدنا نحن وآباؤنا هذا من قبل فلم يحصل، إن هذا إلا حكايات سطّرها الأولون في كتبهم لا حقيقة لها.", "h": ["وجوب الشكر لله تعالى بطاعته على نعمه، ومن بينها نعمة السمع والبصر والقلب.", "تقرير عقيدة البعث والجزاء بما تضمّنت الآيات من الأدلة العديدة على ذلك.", "سوء التقليد وآثاره في السلوك الإنساني، بحيث ينكر المقلّد عقله."], "k": "«وهو الذي أنشأ لكم السمع والأبصار والأفئدة قليلاً ما تشكرون»… فيم أستعمل سمعي وبصري اليوم؟"}, {"lbl": "الآيات ٨٤ – ٩٢", "q": "قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٨٤﴾ سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ ﴿٨٥﴾ قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴿٨٦﴾ سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ ﴿٨٧﴾ قُلۡ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٨٨﴾ سَيَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ ﴿٨٩﴾ بَلۡ أَتَيۡنَٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَٰذِبُونَ ﴿٩٠﴾ مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٖ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ ﴿٩١﴾ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٩٢﴾", "w": [["قل أفلا تذكّرون", "فتعلمون أن من له الأرض ومن فيها قادر على البعث، وأنه لا إله إلا هو."], ["قل أفلا تتقون", "كيف لا تتقونه بالإيمان به وتوحيده وتصديقه في البعث؟"], ["من بيده ملكوت كل شيء", "ملك كل شيء، يتصرّف فيه كيف يشاء."], ["وهو يجير ولا يُجار عليه", "يحفظ ويحمي من يشاء، ولا يُحمى عليه من أراده بسوء."], ["فأنّى تُسحرون", "كيف تُخدعون وتُصرفون عن الحق؟"], ["بل أتيناهم بالحق", "بما هو الحق والصدق في التوحيد والنبوة والبعث."], ["ولعلا بعضهم على بعض", "قهراً وسلطاناً."], ["عما يصفون", "من الكذب كزعمهم أن لله ولداً وشريكاً وأنه غير قادر على البعث."]], "m": "ما زال السياق في دعوة المشركين: قل لهم: لمن الأرض ومن فيها من المخلوقات إن كنتم تعلمون؟ سيقولون: لله، فقل: أفلا تذكّرون فتعلموا أن من له ذلك لا يصلح أن يكون له شريك؟ قل: من رب السماوات السبع ورب العرش العظيم؟ سيقولون: لله، قل: أفلا تتقون عقابه فلا تنكرون عليه البعث ولا تجعلون له أنداداً؟ قل: من بيده ملك كل شيء وخزائنه، وهو يحمي من يشاء فلا يستطيع أحد أن يمسّه بسوء، ولا يستطيع أحد أن يحمي أحداً أراده هو بسوء، إن كنتم تعلمون؟ سيقولون: لله، قل: فكيف تُخدعون فتُصرفون عن الحق فتعبدون غير الخالق وتنكرون عليه إحياء الموتى وهو الذي أحياهم أولاً؟ بل أتيناهم بالحق وإنهم لكاذبون. ما اتخذ الله من ولد، وما كان معه من إله، والدليل العقلي: لو كان معه إله آخر لذهب كل إله بما خلق، ولعلا بعضهم على بعض غلبة وقهراً، سبحان الله عما يصفون، عالم ما غاب وما حضر، فلو كان معه آلهة لأخبر عنهم، فتعالى عما يشركون.", "h": ["مشروعية توبيخ المتغافل المتجاهل، وتأنيب المتعامي عن الحق وهو قادر على رؤيته.", "تقرير ربوبية الله تعالى وألوهيته.", "تنزيه الله تعالى عن الصاحبة والولد وإبطال ترّهات المفترين.", "الاستدلال العقلي ومشروعيته والعمل به لإحقاق الحق وإبطال الباطل."], "k": "«وهو يجير ولا يُجار عليه»… من أخاف منه؟ ومن أرجو حمايته غير الله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 246;
insert into public.tdb_cards(topic, i, body) select 246, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧١ – ٧٧", "q": "وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ ﴿٧١﴾ أَمۡ تَسۡـَٔلُهُمۡ خَرۡجٗا فَخَرَاجُ رَبِّكَ خَيۡرٞۖ وَهُوَ خَيۡرُ ٱلرَّـٰزِقِينَ ﴿٧٢﴾ وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٧٣﴾ وَإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ ﴿٧٤﴾ ۞وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرّٖ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ﴿٧٥﴾ وَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ ﴿٧٦﴾ حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابٗا ذَا عَذَابٖ شَدِيدٍ إِذَا هُمۡ فِيهِ مُبۡلِسُونَ ﴿٧٧﴾", "w": [["ولو اتبع الحق أهواءهم", "ما يهوونه ويشتهونه."], ["أتيناهم بذكرهم", "بالقرآن العظيم الذي فيه ذكرهم، به يذكرون ويُذكرون."], ["أم تسألهم خرجاً", "مالاً مقابل إبلاغك لهم دعوة ربهم."], ["فخراج ربك خير", "ما يرزقكه الله خير، وهو خير الرازقين."], ["إلى صراط مستقيم", "إلى الإسلام."], ["عن الصراط لناكبون", "عن الإسلام متنكّبون، جاعلوه على منكب أي جانب."], ["للجّوا في طغيانهم يعمهون", "لتمادوا في طغيانهم مصرّين عليه."], ["فما استكانوا", "ما ذلّوا ولا خضعوا."], ["إذا هم فيه مبلسون", "آيسون قانطون."]], "m": "ولو اتبع الحق النازل من عند الله أهواء المشركين فوافقهم عليه لفسد الكون كله علويّه وسفليّه، لأنهم أهل باطل لا يرون إلا الباطل. بل أتيناهم بالقرآن الذي به يذكرون وهو سبب شرفهم، فهم عن ذكرهم معرضون لفساد قلوبهم. أم تسألهم أجراً على التبليغ؟ فثواب ربك خير، وهو خير الرازقين، وحاشاه ﷺ. وإنك لتدعوهم إلى الإسلام طريق السعادة، وإن الذين لا يؤمنون بالآخرة عن الصراط لمبتعدون، فالقلب الذي لا يعمره الإيمان بلقاء الله ضد كل خير. ولو رحمناهم فكشفنا ما بهم من قحط وجوع لتمادوا في طغيانهم حيارى. ولقد أخذناهم بسنوات الجدب بدعوة الرسول ﷺ، وبالقتل في بدر، فما ذلّوا لربهم وما تضرّعوا، لظلمة نفوسهم، حتى إذا فتحنا عليهم باب عذاب شديد إذا هم فيه آيسون من كل خير.", "h": ["خطر اتباع الهوى وما يفضي إليه من الهلاك والخسران.", "الصراط المستقيم الموصل إلى السعادة والكمال هو الإسلام لا غير.", "التكذيب بيوم القيامة وما يتم فيه من حساب وجزاء هو الباعث على كل شر.", "من آثار ظلمة النفس نتيجة الكفر: اليأس والقنوط والتمادي في الشر والفساد."], "k": "«فما استكانوا لربهم وما يتضرّعون»… حين تصيبني شدة، هل أتضرّع أم أتصلّب؟"}, {"lbl": "الآيات ٧٨ – ٨٣", "q": "وَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ ﴿٧٨﴾ وَهُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ ﴿٧٩﴾ وَهُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ وَلَهُ ٱخۡتِلَٰفُ ٱلَّيۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ ﴿٨٠﴾ بَلۡ قَالُواْ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ ﴿٨١﴾ قَالُوٓاْ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ ﴿٨٢﴾ لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٨٣﴾", "w": [["أنشأ لكم السمع", "خلق وأوجد لكم الأسماع والأبصار."], ["والأفئدة", "جمع فؤاد، وهو القلب."], ["قليلاً ما تشكرون", "ما تشكرون إلا قليلاً."], ["ذرأكم", "خلقكم."], ["وإليه تحشرون", "تجمعون إليه بعد إحيائكم وخروجكم من قبوركم."], ["وله اختلاف الليل والنهار", "إليه إيجاد الليل والنهار، وظلمة الليل وضياء النهار."], ["أفلا تعقلون", "فتعرفوا أن الله هو المعبود الحق، إذ هو الرب الحق."], ["إلا أساطير الأولين", "ما تقولون من البعث إلا حكايات الأولين، جمع أسطورة."]], "m": "ما زال السياق في دعوة المنكرين للبعث بعرض الأدلة العقلية: وهو الذي خلق لكم الأسماع والأبصار والقلوب، قادر على إحيائكم بعد موتكم، قليلاً ما تشكرونه على ذلك بالإيمان والطاعة. وهو الذي خلقكم في الأرض وإليه تُجمعون، فالقادر على خلقكم فيها قادر على إعادتكم. وهو الذي يحيي النطفة بنفخ الروح فتكون بشراً، ويميتكم بعد انقضاء آجالكم، وله اختلاف الليل والنهار وتعاقبهما، أفلا تعقلون أن من هذه قدرته قادر على بعثكم؟ بل بدل أن يؤمنوا قالوا مثل ما قال الأولون: أئذا متنا وكنا تراباً وعظاماً أئنا لمبعوثون؟ لقد وُعدنا نحن وآباؤنا هذا من قبل فلم يحصل، إن هذا إلا حكايات سطّرها الأولون في كتبهم لا حقيقة لها.", "h": ["وجوب الشكر لله تعالى بطاعته على نعمه، ومن بينها نعمة السمع والبصر والقلب.", "تقرير عقيدة البعث والجزاء بما تضمّنت الآيات من الأدلة العديدة على ذلك.", "سوء التقليد وآثاره في السلوك الإنساني، بحيث ينكر المقلّد عقله."], "k": "«وهو الذي أنشأ لكم السمع والأبصار والأفئدة قليلاً ما تشكرون»… فيم أستعمل سمعي وبصري اليوم؟"}, {"lbl": "الآيات ٨٤ – ٩٢", "q": "قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٨٤﴾ سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ ﴿٨٥﴾ قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴿٨٦﴾ سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ ﴿٨٧﴾ قُلۡ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٨٨﴾ سَيَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ ﴿٨٩﴾ بَلۡ أَتَيۡنَٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَٰذِبُونَ ﴿٩٠﴾ مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٖ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ ﴿٩١﴾ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٩٢﴾", "w": [["قل أفلا تذكّرون", "فتعلمون أن من له الأرض ومن فيها قادر على البعث، وأنه لا إله إلا هو."], ["قل أفلا تتقون", "كيف لا تتقونه بالإيمان به وتوحيده وتصديقه في البعث؟"], ["من بيده ملكوت كل شيء", "ملك كل شيء، يتصرّف فيه كيف يشاء."], ["وهو يجير ولا يُجار عليه", "يحفظ ويحمي من يشاء، ولا يُحمى عليه من أراده بسوء."], ["فأنّى تُسحرون", "كيف تُخدعون وتُصرفون عن الحق؟"], ["بل أتيناهم بالحق", "بما هو الحق والصدق في التوحيد والنبوة والبعث."], ["ولعلا بعضهم على بعض", "قهراً وسلطاناً."], ["عما يصفون", "من الكذب كزعمهم أن لله ولداً وشريكاً وأنه غير قادر على البعث."]], "m": "ما زال السياق في دعوة المشركين: قل لهم: لمن الأرض ومن فيها من المخلوقات إن كنتم تعلمون؟ سيقولون: لله، فقل: أفلا تذكّرون فتعلموا أن من له ذلك لا يصلح أن يكون له شريك؟ قل: من رب السماوات السبع ورب العرش العظيم؟ سيقولون: لله، قل: أفلا تتقون عقابه فلا تنكرون عليه البعث ولا تجعلون له أنداداً؟ قل: من بيده ملك كل شيء وخزائنه، وهو يحمي من يشاء فلا يستطيع أحد أن يمسّه بسوء، ولا يستطيع أحد أن يحمي أحداً أراده هو بسوء، إن كنتم تعلمون؟ سيقولون: لله، قل: فكيف تُخدعون فتُصرفون عن الحق فتعبدون غير الخالق وتنكرون عليه إحياء الموتى وهو الذي أحياهم أولاً؟ بل أتيناهم بالحق وإنهم لكاذبون. ما اتخذ الله من ولد، وما كان معه من إله، والدليل العقلي: لو كان معه إله آخر لذهب كل إله بما خلق، ولعلا بعضهم على بعض غلبة وقهراً، سبحان الله عما يصفون، عالم ما غاب وما حضر، فلو كان معه آلهة لأخبر عنهم، فتعالى عما يشركون.", "h": ["مشروعية توبيخ المتغافل المتجاهل، وتأنيب المتعامي عن الحق وهو قادر على رؤيته.", "تقرير ربوبية الله تعالى وألوهيته.", "تنزيه الله تعالى عن الصاحبة والولد وإبطال ترّهات المفترين.", "الاستدلال العقلي ومشروعيته والعمل به لإحقاق الحق وإبطال الباطل."], "k": "«وهو يجير ولا يُجار عليه»… من أخاف منه؟ ومن أرجو حمايته غير الله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (247, 23, 93, 118, 'سورة المؤمنون ٩٣ – ١١٨', '«ادفع بالتي هي أحسن»، و«رب ارجعون لعلي أعمل صالحاً»، و«فمن ثقلت موازينه»، و«أفحسبتم أنما خلقناكم عبثاً»، و«وقل رب اغفر وارحم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 247) = $j$[{"lbl": "الآيات ٩٣ – ١٠٠", "q": "قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ ﴿٩٣﴾ رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٩٤﴾ وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ ﴿٩٥﴾ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ ﴿٩٦﴾ وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ ﴿٩٧﴾ وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ ﴿٩٨﴾ حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ ﴿٩٩﴾ لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ كَلَّآۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿١٠٠﴾", "w": [["إما تريني ما يوعدون", "إن تُريني من العذاب."], ["ادفع بالتي هي أحسن", "ادفع بالخصلة التي هي أحسن، كالصفح والإعراض عنهم."], ["من همزات الشياطين", "من وساوسهم التي تخطر بالقلب فتكاد تفسده."], ["أن يحضرون", "في أموري حتى لا يفسدوها عليّ."], ["جاء أحدهم الموت", "رأى علاماته ورأى ملك الموت."], ["كلا", "لا رجوع أبداً."], ["برزخ", "حاجز يمنع من العودة إلى الحياة الدنيا."]], "m": "تهديد للمشركين الذين لم ينتفعوا بما تقدّم: أمر الله رسوله أن يدعوه: رب إن تُريني ما يوعدون من العذاب فلا تجعلني في القوم الظالمين، بل أخرجني منهم حتى لا أهلك معهم، وإنا على أن نريك ما نعدهم لقادرون. وقبل الأمر بقتالهم أمره: ادفع ما يقولونه من الكفر بالخصلة التي هي أحسن، كالصفح والإعراض، نحن أعلم بما يصفون. ولما علّمه الاحتراز من المشركين علّمه التحصّن من الشياطين: وقل رب أعوذ بك من وساوس الشياطين حتى لا يفتنوني عن ديني، وأعوذ بك رب أن يحضروا أمري فيفسدوه عليّ. حتى إذا حضر أحد المشركين الموت ورأى ملك الموت وأعوانه قال: رب ارجعون لعلي أعمل صالحاً فيما تركت من الواجبات، كلا، لا رجوع، إنها كلمة هو قائلها لا فائدة منها، ومن ورائهم حاجز مانع من العودة إلى يوم يُبعثون، وهي حياة حساب وجزاء لا عمل.", "h": ["مشروعية الدعاء والترغيب فيه، وأنه لذو جدوى للمؤمن.", "استحباب دفع السيئ من القول أو الفعل بالصفح والإعراض عن صاحبه.", "مشروعية الاستعاذة بالله تعالى من وساوس الشياطين ومن حضورهم أمر العبد حتى لا يفسدوه عليه بالخواطر السيئة.", "موعظة المؤمن بحال من يتمنى العمل الصالح عند الموت فلا يُمكَّن منه، فيموت بندمه وحسرته، ويلقى جزاء تفريطه حرماناً وخسراناً."], "k": "«رب ارجعون لعلي أعمل صالحاً فيما تركت»… العمل الذي سيُتمنّى عند الموت؛ أعمله الآن."}, {"lbl": "الآيات ١٠١ – ١٠٧", "q": "فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ ﴿١٠١﴾ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿١٠٢﴾ وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ خَٰلِدُونَ ﴿١٠٣﴾ تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ ﴿١٠٤﴾ أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ ﴿١٠٥﴾ قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ ﴿١٠٦﴾ رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ ﴿١٠٧﴾", "w": [["في الصور", "في القرن، نفخة القيام من القبور للحساب."], ["المفلحون", "الفائزون بالنجاة من النار ودخول الجنة."], ["تلفح وجوههم النار", "تحرقها."], ["وهم فيها كالحون", "الكالح: من أحرقت النار جلدة وجهه وشفتيه فظهرت أسنانه."], ["ألم تكن آياتي تتلى عليكم", "يوبّخون ويذكّرون بالماضي ليحصل لهم الندم."], ["غلبت علينا شقوتنا", "الشقاوة الأزلية التي كُتبت في كتاب المقادير."], ["أخرجنا منها فإن عدنا", "من النار، فإن عدنا إلى الشرك والمعاصي."]], "m": "لا يستقيم إنسان على مناهج الحق إلا إذا آمن إيماناً راسخاً بالله والوحي والبعث الذي هو دور الحصاد: فإذا نُفخ في الصور نفخة البعث فلا أنساب بينهم يومئذ تراعى، ولا يتساءلون، فكل همّه نفسه، وسألت عائشة: هل تذكرون أهليكم يوم القيامة؟ فقال: «أما عند ثلاثة فلا: إذا تطايرت الصحف، وإذا وُضع الميزان، وإذا نُصب الصراط». فمن رجحت حسناته فأولئك هم المفلحون، ومن خفّت فأولئك الذين خسروا أنفسهم في جهنم خالدون، تحرق وجوههم النار فتتقلّص شفاههم وتظهر أسنانهم. ويقال لهم توبيخاً: ألم تكن آياتي تُتلى عليكم فكنتم بها تكذّبون بأقوالكم أو أعمالكم؟ قالوا معتذرين بالقدر: ربنا غلبت علينا شقوتنا، وكنا قوماً ضالّين، ربنا أخرجنا منها فإن عدنا إلى الشرك فإنا ظالمون.", "h": ["تقرير عقيدة البعث والجزاء من خلال عرض أحداثها.", "تقرير أن وزن الأعمال يوم القيامة حق، وإنكاره بدعة مكفّرة.", "تقرير أن إسرافيل ينفخ في الصور، وإنكار ذلك وتأويله بدعة من البدع المنكرة.", "الاعتذار بالقدر لا ينفع صاحبه، إذ القدر مستور فلا يُنظر إليه، والعبد مأمور فليأتمر بأمر الله ورسوله ولينته بنهيهما ما دام قادراً على ذلك، فإن عجز فهو معذور."], "k": "«فمن ثقلت موازينه فأولئك هم المفلحون»… ما الذي أضعه في كفة حسناتي اليوم؟"}, {"lbl": "الآيات ١٠٨ – ١١١", "q": "قَالَ ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ ﴿١٠٨﴾ إِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّـٰحِمِينَ ﴿١٠٩﴾ فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ ﴿١١٠﴾ إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ ﴿١١١﴾", "w": [["اخسئوا", "ابعدوا في النار أذلّاء مخزيين."], ["فريق من عبادي", "هم المؤمنون المتقون."], ["فاتخذتموهم سخرياً", "جعلتموهم محطّ سخريتكم واستهزائكم."], ["بما صبروا", "على الإيمان والتقوى."], ["هم الفائزون", "الناجون من النار المنعّمون في الجنة."]], "m": "هذا جواب سؤالهم: «ربنا أخرجنا منها»، قال: اخسئوا فيها ولا تكلّمون، ابعدوا أذلّاء. وعلّل حكمه: إنه كان فريق من عبادي، المؤمنون المتقون، يقولون: ربنا آمنّا فاغفر لنا وارحمنا وأنت خير الراحمين، يتوسّلون إلينا بإيمانهم وصالح أعمالهم، فاتخذتموهم سخرية تضحكون من عبادتهم وضراعتهم حتى أنستكم ذكري، وكنتم منهم تضحكون. إني جزيتهم اليوم بصبرهم على طاعتي مع ما لاقوا منكم من اضطهاد وسخرية أنهم هم الفائزون برضواني في جناتي.", "h": ["بيان مدى حسرة أهل النار لما يُجابون بكلمة: «اخسئوا فيها ولا تكلّمون».", "فضيلة التضرّع إلى الله تعالى ودعائه، والتوسّل إليه بالإيمان وصالح الأعمال.", "حرمة السخرية بالمسلم والاستهزاء به والضحك منه.", "فضيلة الصبر، ولذا ورد أن منزلة الصبر من الإيمان كمنزلة الرأس من الجسد."], "k": "«ربنا آمنّا فاغفر لنا وارحمنا وأنت خير الراحمين»… دعاء الفائزين؛ أجعله من وردي."}, {"lbl": "الآيات ١١٢ – ١١٨", "q": "قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ ﴿١١٢﴾ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ ﴿١١٣﴾ قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ ﴿١١٤﴾ أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ ﴿١١٥﴾ فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ ﴿١١٦﴾ وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ ﴿١١٧﴾ وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّـٰحِمِينَ ﴿١١٨﴾", "w": [["كم لبثتم في الأرض", "كم سنة لبثتموها في الأرض أحياء وأمواتاً في قبوركم؟"], ["فاسأل العادّين", "يريدون الملائكة التي كانت تعدّ، أو من يعدّ، أما نحن فلم نعرف."], ["خلقناكم عبثاً", "لا لحكمة، بل لمجرد العيش واللعب؟ كلا."], ["فتعالى الله الملك الحق", "تنزّه الله عن العبث."], ["لا برهان له به", "لا حجة على صحة عبادة غير الله، إذ الخلق كله مربوب لله."], ["فإنما حسابه عند ربه", "مجازاته عند ربه، هو الذي يجازيه بشركه."]], "m": "ما زال السياق مع أهل النار المنكرين للبعث: قال: كم لبثتم في الأرض عدد سنين، أحياء وأمواتاً في قبوركم؟ قالوا: لبثنا يوماً أو بعض يوم، فاسأل العادّين من الملائكة، وهذا الاضطراب عائد إلى نكرانهم للبعث وأهوال الموقف. قال: إن لبثتم إلا قليلاً لو أنكم كنتم تعلمون. أفظننتم أنما خلقناكم عبثاً للأكل والشرب لا للعبادة، وأنكم إلينا لا ترجعون للحساب؟ فتعالى الله الملك الحق عن العبث، لا إله إلا هو رب العرش الكريم. ومن يعبد مع الله إلهاً آخر بالدعاء أو الخوف أو الرجاء أو النذر والذبح، لا حجة له على ذلك، فإنما حسابه عند ربه، إنه لا يفلح الكافرون. وقل: رب اغفر لي وارحمني، واغفر لسائر المؤمنين وارحمهم، وأنت خير الراحمين.", "h": ["عظم هول يوم القيامة وشدة الفزع فيه، فليُتّق ذلك بالإيمان وصالح الأعمال.", "تنزّه الله تعالى عن العبث واللهو واللعب.", "تقرير عقيدة البعث والجزاء.", "كفر وشرك من يدعو مع الله إلهاً آخر.", "الحكم بخسران الكافرين وعدم فلاحهم.", "استحباب الدعاء بالمغفرة والرحمة للمؤمنين والمؤمنات."], "k": "«أفحسبتم أنما خلقناكم عبثاً»… لماذا خُلقت؟ وهل يشهد يومي بالجواب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 247;
insert into public.tdb_cards(topic, i, body) select 247, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٣ – ١٠٠", "q": "قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ ﴿٩٣﴾ رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٩٤﴾ وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ ﴿٩٥﴾ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ ﴿٩٦﴾ وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ ﴿٩٧﴾ وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ ﴿٩٨﴾ حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ ﴿٩٩﴾ لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ كَلَّآۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿١٠٠﴾", "w": [["إما تريني ما يوعدون", "إن تُريني من العذاب."], ["ادفع بالتي هي أحسن", "ادفع بالخصلة التي هي أحسن، كالصفح والإعراض عنهم."], ["من همزات الشياطين", "من وساوسهم التي تخطر بالقلب فتكاد تفسده."], ["أن يحضرون", "في أموري حتى لا يفسدوها عليّ."], ["جاء أحدهم الموت", "رأى علاماته ورأى ملك الموت."], ["كلا", "لا رجوع أبداً."], ["برزخ", "حاجز يمنع من العودة إلى الحياة الدنيا."]], "m": "تهديد للمشركين الذين لم ينتفعوا بما تقدّم: أمر الله رسوله أن يدعوه: رب إن تُريني ما يوعدون من العذاب فلا تجعلني في القوم الظالمين، بل أخرجني منهم حتى لا أهلك معهم، وإنا على أن نريك ما نعدهم لقادرون. وقبل الأمر بقتالهم أمره: ادفع ما يقولونه من الكفر بالخصلة التي هي أحسن، كالصفح والإعراض، نحن أعلم بما يصفون. ولما علّمه الاحتراز من المشركين علّمه التحصّن من الشياطين: وقل رب أعوذ بك من وساوس الشياطين حتى لا يفتنوني عن ديني، وأعوذ بك رب أن يحضروا أمري فيفسدوه عليّ. حتى إذا حضر أحد المشركين الموت ورأى ملك الموت وأعوانه قال: رب ارجعون لعلي أعمل صالحاً فيما تركت من الواجبات، كلا، لا رجوع، إنها كلمة هو قائلها لا فائدة منها، ومن ورائهم حاجز مانع من العودة إلى يوم يُبعثون، وهي حياة حساب وجزاء لا عمل.", "h": ["مشروعية الدعاء والترغيب فيه، وأنه لذو جدوى للمؤمن.", "استحباب دفع السيئ من القول أو الفعل بالصفح والإعراض عن صاحبه.", "مشروعية الاستعاذة بالله تعالى من وساوس الشياطين ومن حضورهم أمر العبد حتى لا يفسدوه عليه بالخواطر السيئة.", "موعظة المؤمن بحال من يتمنى العمل الصالح عند الموت فلا يُمكَّن منه، فيموت بندمه وحسرته، ويلقى جزاء تفريطه حرماناً وخسراناً."], "k": "«رب ارجعون لعلي أعمل صالحاً فيما تركت»… العمل الذي سيُتمنّى عند الموت؛ أعمله الآن."}, {"lbl": "الآيات ١٠١ – ١٠٧", "q": "فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ ﴿١٠١﴾ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿١٠٢﴾ وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ خَٰلِدُونَ ﴿١٠٣﴾ تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ ﴿١٠٤﴾ أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ ﴿١٠٥﴾ قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ ﴿١٠٦﴾ رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ ﴿١٠٧﴾", "w": [["في الصور", "في القرن، نفخة القيام من القبور للحساب."], ["المفلحون", "الفائزون بالنجاة من النار ودخول الجنة."], ["تلفح وجوههم النار", "تحرقها."], ["وهم فيها كالحون", "الكالح: من أحرقت النار جلدة وجهه وشفتيه فظهرت أسنانه."], ["ألم تكن آياتي تتلى عليكم", "يوبّخون ويذكّرون بالماضي ليحصل لهم الندم."], ["غلبت علينا شقوتنا", "الشقاوة الأزلية التي كُتبت في كتاب المقادير."], ["أخرجنا منها فإن عدنا", "من النار، فإن عدنا إلى الشرك والمعاصي."]], "m": "لا يستقيم إنسان على مناهج الحق إلا إذا آمن إيماناً راسخاً بالله والوحي والبعث الذي هو دور الحصاد: فإذا نُفخ في الصور نفخة البعث فلا أنساب بينهم يومئذ تراعى، ولا يتساءلون، فكل همّه نفسه، وسألت عائشة: هل تذكرون أهليكم يوم القيامة؟ فقال: «أما عند ثلاثة فلا: إذا تطايرت الصحف، وإذا وُضع الميزان، وإذا نُصب الصراط». فمن رجحت حسناته فأولئك هم المفلحون، ومن خفّت فأولئك الذين خسروا أنفسهم في جهنم خالدون، تحرق وجوههم النار فتتقلّص شفاههم وتظهر أسنانهم. ويقال لهم توبيخاً: ألم تكن آياتي تُتلى عليكم فكنتم بها تكذّبون بأقوالكم أو أعمالكم؟ قالوا معتذرين بالقدر: ربنا غلبت علينا شقوتنا، وكنا قوماً ضالّين، ربنا أخرجنا منها فإن عدنا إلى الشرك فإنا ظالمون.", "h": ["تقرير عقيدة البعث والجزاء من خلال عرض أحداثها.", "تقرير أن وزن الأعمال يوم القيامة حق، وإنكاره بدعة مكفّرة.", "تقرير أن إسرافيل ينفخ في الصور، وإنكار ذلك وتأويله بدعة من البدع المنكرة.", "الاعتذار بالقدر لا ينفع صاحبه، إذ القدر مستور فلا يُنظر إليه، والعبد مأمور فليأتمر بأمر الله ورسوله ولينته بنهيهما ما دام قادراً على ذلك، فإن عجز فهو معذور."], "k": "«فمن ثقلت موازينه فأولئك هم المفلحون»… ما الذي أضعه في كفة حسناتي اليوم؟"}, {"lbl": "الآيات ١٠٨ – ١١١", "q": "قَالَ ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ ﴿١٠٨﴾ إِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّـٰحِمِينَ ﴿١٠٩﴾ فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ ﴿١١٠﴾ إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ ﴿١١١﴾", "w": [["اخسئوا", "ابعدوا في النار أذلّاء مخزيين."], ["فريق من عبادي", "هم المؤمنون المتقون."], ["فاتخذتموهم سخرياً", "جعلتموهم محطّ سخريتكم واستهزائكم."], ["بما صبروا", "على الإيمان والتقوى."], ["هم الفائزون", "الناجون من النار المنعّمون في الجنة."]], "m": "هذا جواب سؤالهم: «ربنا أخرجنا منها»، قال: اخسئوا فيها ولا تكلّمون، ابعدوا أذلّاء. وعلّل حكمه: إنه كان فريق من عبادي، المؤمنون المتقون، يقولون: ربنا آمنّا فاغفر لنا وارحمنا وأنت خير الراحمين، يتوسّلون إلينا بإيمانهم وصالح أعمالهم، فاتخذتموهم سخرية تضحكون من عبادتهم وضراعتهم حتى أنستكم ذكري، وكنتم منهم تضحكون. إني جزيتهم اليوم بصبرهم على طاعتي مع ما لاقوا منكم من اضطهاد وسخرية أنهم هم الفائزون برضواني في جناتي.", "h": ["بيان مدى حسرة أهل النار لما يُجابون بكلمة: «اخسئوا فيها ولا تكلّمون».", "فضيلة التضرّع إلى الله تعالى ودعائه، والتوسّل إليه بالإيمان وصالح الأعمال.", "حرمة السخرية بالمسلم والاستهزاء به والضحك منه.", "فضيلة الصبر، ولذا ورد أن منزلة الصبر من الإيمان كمنزلة الرأس من الجسد."], "k": "«ربنا آمنّا فاغفر لنا وارحمنا وأنت خير الراحمين»… دعاء الفائزين؛ أجعله من وردي."}, {"lbl": "الآيات ١١٢ – ١١٨", "q": "قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ ﴿١١٢﴾ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ ﴿١١٣﴾ قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ ﴿١١٤﴾ أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ ﴿١١٥﴾ فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ ﴿١١٦﴾ وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ ﴿١١٧﴾ وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّـٰحِمِينَ ﴿١١٨﴾", "w": [["كم لبثتم في الأرض", "كم سنة لبثتموها في الأرض أحياء وأمواتاً في قبوركم؟"], ["فاسأل العادّين", "يريدون الملائكة التي كانت تعدّ، أو من يعدّ، أما نحن فلم نعرف."], ["خلقناكم عبثاً", "لا لحكمة، بل لمجرد العيش واللعب؟ كلا."], ["فتعالى الله الملك الحق", "تنزّه الله عن العبث."], ["لا برهان له به", "لا حجة على صحة عبادة غير الله، إذ الخلق كله مربوب لله."], ["فإنما حسابه عند ربه", "مجازاته عند ربه، هو الذي يجازيه بشركه."]], "m": "ما زال السياق مع أهل النار المنكرين للبعث: قال: كم لبثتم في الأرض عدد سنين، أحياء وأمواتاً في قبوركم؟ قالوا: لبثنا يوماً أو بعض يوم، فاسأل العادّين من الملائكة، وهذا الاضطراب عائد إلى نكرانهم للبعث وأهوال الموقف. قال: إن لبثتم إلا قليلاً لو أنكم كنتم تعلمون. أفظننتم أنما خلقناكم عبثاً للأكل والشرب لا للعبادة، وأنكم إلينا لا ترجعون للحساب؟ فتعالى الله الملك الحق عن العبث، لا إله إلا هو رب العرش الكريم. ومن يعبد مع الله إلهاً آخر بالدعاء أو الخوف أو الرجاء أو النذر والذبح، لا حجة له على ذلك، فإنما حسابه عند ربه، إنه لا يفلح الكافرون. وقل: رب اغفر لي وارحمني، واغفر لسائر المؤمنين وارحمهم، وأنت خير الراحمين.", "h": ["عظم هول يوم القيامة وشدة الفزع فيه، فليُتّق ذلك بالإيمان وصالح الأعمال.", "تنزّه الله تعالى عن العبث واللهو واللعب.", "تقرير عقيدة البعث والجزاء.", "كفر وشرك من يدعو مع الله إلهاً آخر.", "الحكم بخسران الكافرين وعدم فلاحهم.", "استحباب الدعاء بالمغفرة والرحمة للمؤمنين والمؤمنات."], "k": "«أفحسبتم أنما خلقناكم عبثاً»… لماذا خُلقت؟ وهل يشهد يومي بالجواب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (248, 24, 1, 10, 'سورة النور ١ – ١٠', '«سورة أنزلناها وفرضناها»: حدّ الزنا، وحدّ القذف، واللعان بين الزوجين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 248) = $j$[{"lbl": "الآيات ١ – ٣", "q": "سُورَةٌ أَنزَلۡنَٰهَا وَفَرَضۡنَٰهَا وَأَنزَلۡنَا فِيهَآ ءَايَٰتِۭ بَيِّنَٰتٖ لَّعَلَّكُمۡ تَذَكَّرُونَ ﴿١﴾ ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ ﴿٢﴾ ٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةٗ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكٞۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ ﴿٣﴾", "w": [["سورة أنزلناها", "هذه سورة أنزلناها."], ["وفرضناها", "فرضنا ما فيها من أحكام."], ["آيات بيّنات", "حججاً واضحات تهدي إلى الحق."], ["لعلكم تذكّرون", "تتّعظون فتعملون بما في السورة من أحكام."], ["الزانية", "من أفضت إلى رجل بغير نكاح شرعي وهي غير محصنة."], ["مائة جلدة", "ضربة على جلد ظهره."], ["رأفة", "شفقة ورحمة."], ["وليشهد عذابهما", "إقامة الحد عليهما."], ["طائفة", "عدد لا يقل عن ثلاثة من المسلمين، والأربعة أولى."], ["الزاني لا ينكح إلا زانية", "لا يقع وطء إلا على مثله."]], "m": "هذه سورة من كتاب الله أنزلناها على رسولنا ﷺ، وفرضنا ما اشتملت عليه من أحكام على أمة الإسلام، وأنزلنا فيها آيات بيّنات لعلكم تتّعظون فتعملون بما حوته من أوامر ونواهٍ وآداب. الزانية والزاني إذا كانا بكرين حرّين غير محصنين فاجلدوا كل واحد منهما مائة جلدة بعصا لا تشين جارحة ولا تكسر عضواً، جلداً غير مبرّح، وزادت السنة تغريب سنة، ولا تأخذكم بهما شفقة فتعطّلوا حدّ الله وتحرموهما من التطهير، لأن الحدود كفارة لأصحابها، إن كنتم تؤمنون بالله واليوم الآخر، وليشهد إقامة الحد عليهما ثلاثة فأكثر من المؤمنين. الزاني لا يطأ إلا زانية مثله أو مشركة لا دين لها، والزانية لا يطؤها إلا زانٍ أو مشرك، وحرّم الله الزنا على المؤمنين، ولازم هذا ألا تُزوّج عفيفة من زانٍ إلا بعد توبته.", "h": ["بيان حكم الزانية والزاني البكرين الحرّين، وهو جلد مائة وتغريب عام، وأما الثيّبان فالرجم إن كانا حرّين، أو جلد خمسين جلدة لكل واحد منهما إن كانا غير حرّين.", "وجوب إقامة هذا الحد أمام طائفة من المؤمنين.", "لا يحل تزويج الزاني إلا بعد توبته، ولا الزانية إلا بعد توبتها."], "k": "«سورة أنزلناها وفرضناها»… سورة الآداب والعفاف؛ أي حكم منها أحتاج أن أعيشه؟"}, {"lbl": "الآيتان ٤ – ٥", "q": "وَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗاۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿٤﴾ إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٥﴾", "w": [["يرمون", "يقذفون."], ["المحصنات", "العفيفات، والرجال هنا كالنساء."], ["فاجلدوهم", "حداً عليهم واجباً."], ["ولا تقبلوا لهم شهادة أبداً", "لسقوط عدالتهم بالقذف للمؤمنين والمؤمنات."], ["إلا الذين تابوا", "فإنهم بعد توبتهم يعود إليهم اعتبارهم وتصح شهادتهم."]], "m": "بعد بيان حكم الزناة بيّن حكم القذف: والذين يرمون المؤمنين والمؤمنات بالفاحشة، بأن يقول: فلان زانٍ أو لائط، عليه أن يحضر أربعة شهداء يشهدون أمام الحاكم على صحة ما رمى به أخاه، فإن لم يأت بهم أقيم عليه الحد: ثمانون جلدة على ظهره، ولا تُقبل له شهادة، وأولئك هم الفاسقون عن طاعة الله ورسوله، إلا الذين تابوا من بعد ذلك وأصلحوا بأن كذّبوا أنفسهم، فإن الله غفور لهم بعد التوبة، رحيم بهم لا يعذّبهم بهذا الذنب العظيم.", "h": ["بيان حد القذف، وهو جلد ثمانين جلدة لمن قذف مؤمناً أو مؤمنة بالفاحشة، وكان المقذوف بالغاً عاقلاً مسلماً عفيفاً، أي لم يُعرف بالفاحشة قبل رميه بها.", "سقوط عدالة القاذف إلا أن يتوب، فإنه تعود إليه عدالته.", "قبول توبة التائب إن كانت توبته صادقة نصوحاً."], "k": "«والذين يرمون المحصنات»… كلمة أقولها في عرض أحد؛ هل أملك عليها أربعة شهداء؟"}, {"lbl": "الآيات ٦ – ١٠", "q": "وَٱلَّذِينَ يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ فَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ ﴿٦﴾ وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ ﴿٧﴾ وَيَدۡرَؤُاْ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ ﴿٨﴾ وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ ٱلصَّـٰدِقِينَ ﴿٩﴾ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ ﴿١٠﴾", "w": [["يرمون أزواجهم", "يقذفونهن بالزنا، كأن يقول: زنت، أو الحمل الذي في بطنها ليس مني."], ["إنه لمن الصادقين", "فيما رماها به من الزنا."], ["والخامسة", "الشهادة الخامسة."], ["ويدرأ عنها العذاب", "يدفع عنها الحد."], ["أن تشهد أربع شهادات", "شهادتها أربع شهادات."], ["والخامسة", "قولها: غضب الله عليها إن كان من الصادقين."], ["ولولا فضل الله عليكم", "لعاجلكم بالعقوبة ولفضح أحد الكاذبين."]], "m": "بعد حكم القذف العام ذكر حكم قذف الرجل زوجته: والذين يرمون أزواجهم بالفاحشة ولم يكن لهم شهداء إلا أنفسهم، فالذي يقوم مقام الأربعة أن يشهد أربع شهادات بالله: لقد رأيتها تزني، أو: هذا الحمل ليس مني، إنه لمن الصادقين، ويقول في الخامسة: لعنة الله عليه إن كان من الكاذبين. وهنا يُعرض على الزوجة أن تقرّ فيقام عليها الحد، أو تشهد أربع شهادات بالله إنه لمن الكاذبين، والخامسة تدعو على نفسها: أن غضب الله عليها إن كان من الصادقين، وبذلك يُدفع عنها الحد ويُفرّق بينهما فلا يجتمعان أبداً. ولولا فضل الله عليكم ورحمته لعاجلكم بالعقوبة وفضح أحد الكاذبين، ولكن الله تواب حكيم، ستر عليكم ليتوب من يتوب، ورحمكم بهذا التشريع العادل.", "h": ["بيان حكم قذف الرجل امرأته ولم يكن له أربعة شهود، وهو اللعان.", "بيان كيفية اللعان، وأنه موجب لإقامة الحد إن لم تردّ الزوجة الدعوى بأربع شهادات والدعاء عليها في الخامسة.", "في مشروعية اللعان مظهر من مظاهر حسن التشريع الإسلامي وكماله، وأن مثله لن يكون إلا بوحي إلهي."], "k": "«ولولا فضل الله عليكم ورحمته»… كم ستر الله عليّ؛ فهل أستر على غيري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 248;
insert into public.tdb_cards(topic, i, body) select 248, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "سُورَةٌ أَنزَلۡنَٰهَا وَفَرَضۡنَٰهَا وَأَنزَلۡنَا فِيهَآ ءَايَٰتِۭ بَيِّنَٰتٖ لَّعَلَّكُمۡ تَذَكَّرُونَ ﴿١﴾ ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ ﴿٢﴾ ٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةٗ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكٞۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ ﴿٣﴾", "w": [["سورة أنزلناها", "هذه سورة أنزلناها."], ["وفرضناها", "فرضنا ما فيها من أحكام."], ["آيات بيّنات", "حججاً واضحات تهدي إلى الحق."], ["لعلكم تذكّرون", "تتّعظون فتعملون بما في السورة من أحكام."], ["الزانية", "من أفضت إلى رجل بغير نكاح شرعي وهي غير محصنة."], ["مائة جلدة", "ضربة على جلد ظهره."], ["رأفة", "شفقة ورحمة."], ["وليشهد عذابهما", "إقامة الحد عليهما."], ["طائفة", "عدد لا يقل عن ثلاثة من المسلمين، والأربعة أولى."], ["الزاني لا ينكح إلا زانية", "لا يقع وطء إلا على مثله."]], "m": "هذه سورة من كتاب الله أنزلناها على رسولنا ﷺ، وفرضنا ما اشتملت عليه من أحكام على أمة الإسلام، وأنزلنا فيها آيات بيّنات لعلكم تتّعظون فتعملون بما حوته من أوامر ونواهٍ وآداب. الزانية والزاني إذا كانا بكرين حرّين غير محصنين فاجلدوا كل واحد منهما مائة جلدة بعصا لا تشين جارحة ولا تكسر عضواً، جلداً غير مبرّح، وزادت السنة تغريب سنة، ولا تأخذكم بهما شفقة فتعطّلوا حدّ الله وتحرموهما من التطهير، لأن الحدود كفارة لأصحابها، إن كنتم تؤمنون بالله واليوم الآخر، وليشهد إقامة الحد عليهما ثلاثة فأكثر من المؤمنين. الزاني لا يطأ إلا زانية مثله أو مشركة لا دين لها، والزانية لا يطؤها إلا زانٍ أو مشرك، وحرّم الله الزنا على المؤمنين، ولازم هذا ألا تُزوّج عفيفة من زانٍ إلا بعد توبته.", "h": ["بيان حكم الزانية والزاني البكرين الحرّين، وهو جلد مائة وتغريب عام، وأما الثيّبان فالرجم إن كانا حرّين، أو جلد خمسين جلدة لكل واحد منهما إن كانا غير حرّين.", "وجوب إقامة هذا الحد أمام طائفة من المؤمنين.", "لا يحل تزويج الزاني إلا بعد توبته، ولا الزانية إلا بعد توبتها."], "k": "«سورة أنزلناها وفرضناها»… سورة الآداب والعفاف؛ أي حكم منها أحتاج أن أعيشه؟"}, {"lbl": "الآيتان ٤ – ٥", "q": "وَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗاۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿٤﴾ إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٥﴾", "w": [["يرمون", "يقذفون."], ["المحصنات", "العفيفات، والرجال هنا كالنساء."], ["فاجلدوهم", "حداً عليهم واجباً."], ["ولا تقبلوا لهم شهادة أبداً", "لسقوط عدالتهم بالقذف للمؤمنين والمؤمنات."], ["إلا الذين تابوا", "فإنهم بعد توبتهم يعود إليهم اعتبارهم وتصح شهادتهم."]], "m": "بعد بيان حكم الزناة بيّن حكم القذف: والذين يرمون المؤمنين والمؤمنات بالفاحشة، بأن يقول: فلان زانٍ أو لائط، عليه أن يحضر أربعة شهداء يشهدون أمام الحاكم على صحة ما رمى به أخاه، فإن لم يأت بهم أقيم عليه الحد: ثمانون جلدة على ظهره، ولا تُقبل له شهادة، وأولئك هم الفاسقون عن طاعة الله ورسوله، إلا الذين تابوا من بعد ذلك وأصلحوا بأن كذّبوا أنفسهم، فإن الله غفور لهم بعد التوبة، رحيم بهم لا يعذّبهم بهذا الذنب العظيم.", "h": ["بيان حد القذف، وهو جلد ثمانين جلدة لمن قذف مؤمناً أو مؤمنة بالفاحشة، وكان المقذوف بالغاً عاقلاً مسلماً عفيفاً، أي لم يُعرف بالفاحشة قبل رميه بها.", "سقوط عدالة القاذف إلا أن يتوب، فإنه تعود إليه عدالته.", "قبول توبة التائب إن كانت توبته صادقة نصوحاً."], "k": "«والذين يرمون المحصنات»… كلمة أقولها في عرض أحد؛ هل أملك عليها أربعة شهداء؟"}, {"lbl": "الآيات ٦ – ١٠", "q": "وَٱلَّذِينَ يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ فَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ ﴿٦﴾ وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ ﴿٧﴾ وَيَدۡرَؤُاْ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ ﴿٨﴾ وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ ٱلصَّـٰدِقِينَ ﴿٩﴾ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ ﴿١٠﴾", "w": [["يرمون أزواجهم", "يقذفونهن بالزنا، كأن يقول: زنت، أو الحمل الذي في بطنها ليس مني."], ["إنه لمن الصادقين", "فيما رماها به من الزنا."], ["والخامسة", "الشهادة الخامسة."], ["ويدرأ عنها العذاب", "يدفع عنها الحد."], ["أن تشهد أربع شهادات", "شهادتها أربع شهادات."], ["والخامسة", "قولها: غضب الله عليها إن كان من الصادقين."], ["ولولا فضل الله عليكم", "لعاجلكم بالعقوبة ولفضح أحد الكاذبين."]], "m": "بعد حكم القذف العام ذكر حكم قذف الرجل زوجته: والذين يرمون أزواجهم بالفاحشة ولم يكن لهم شهداء إلا أنفسهم، فالذي يقوم مقام الأربعة أن يشهد أربع شهادات بالله: لقد رأيتها تزني، أو: هذا الحمل ليس مني، إنه لمن الصادقين، ويقول في الخامسة: لعنة الله عليه إن كان من الكاذبين. وهنا يُعرض على الزوجة أن تقرّ فيقام عليها الحد، أو تشهد أربع شهادات بالله إنه لمن الكاذبين، والخامسة تدعو على نفسها: أن غضب الله عليها إن كان من الصادقين، وبذلك يُدفع عنها الحد ويُفرّق بينهما فلا يجتمعان أبداً. ولولا فضل الله عليكم ورحمته لعاجلكم بالعقوبة وفضح أحد الكاذبين، ولكن الله تواب حكيم، ستر عليكم ليتوب من يتوب، ورحمكم بهذا التشريع العادل.", "h": ["بيان حكم قذف الرجل امرأته ولم يكن له أربعة شهود، وهو اللعان.", "بيان كيفية اللعان، وأنه موجب لإقامة الحد إن لم تردّ الزوجة الدعوى بأربع شهادات والدعاء عليها في الخامسة.", "في مشروعية اللعان مظهر من مظاهر حسن التشريع الإسلامي وكماله، وأن مثله لن يكون إلا بوحي إلهي."], "k": "«ولولا فضل الله عليكم ورحمته»… كم ستر الله عليّ؛ فهل أستر على غيري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (249, 24, 11, 26, 'سورة النور ١١ – ٢٦', 'حادثة الإفك: «لولا إذ سمعتموه ظن المؤمنون والمؤمنات بأنفسهم خيراً»، و«ألا تحبون أن يغفر الله لكم»، و«أولئك مبرّءون مما يقولون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 249) = $j$[{"lbl": "الآيات ١١ – ١٨", "q": "إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ خَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ ﴿١١﴾ لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرٗا وَقَالُواْ هَٰذَآ إِفۡكٞ مُّبِينٞ ﴿١٢﴾ لَّوۡلَا جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَـٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ ﴿١٣﴾ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ ﴿١٤﴾ إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ ﴿١٥﴾ وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ ﴿١٦﴾ يَعِظُكُمُ ٱللَّهُ أَن تَعُودُواْ لِمِثۡلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤۡمِنِينَ ﴿١٧﴾ وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ﴿١٨﴾", "w": [["بالإفك عصبة", "الإفك: الكذب المقلوب، وهو أسوأ الكذب، والعصبة: الجماعة."], ["شراً لكم بل هو خير لكم", "الشر ما غلب ضرره على نفعه، والخير ما غلب نفعه على ضرره."], ["والذي تولّى كبره", "معظمه، وهو ابن أُبيّ كبير المنافقين."], ["لولا", "أداة تحضيض بمعنى هلّا."], ["فيما أفضتم فيه", "فيما تحدّثتم فيه بتوسّع وعدم تحفّظ."], ["إذ تلقّونه", "يتلقّاه بعضكم من بعض."], ["وتحسبونه هيّناً", "من صغائر الذنوب، وهو عند الله من كبائرها، لأنه عرض مؤمنة هي زوج رسول الله ﷺ."], ["سبحانك", "كلمة تقال عند التعجّب، والمراد تنزيه الله عما لا يليق به."], ["بهتان عظيم", "البهتان: الكذب الذي يحيّر من قيل فيه."], ["يعظكم الله", "ينهاكم نهياً مقروناً بالوعيد حتى لا تعودوا لمثله أبداً."]], "m": "بعد حكم القذف العام والخاص ذكر حادثة الإفك: بعد فرض الحجاب خرج رسول الله ﷺ إلى غزوة بني المصطلق، فلما عاد وقارب المدينة نزل ليلاً ثم ارتحل، فوضعوا هودج عائشة على البعير ظانّين أنها فيه، وكانت قد عادت تلتمس عقداً لها سقط، فوجدت الجيش قد رحل فجلست في مكانها لعلهم يرجعون، حتى جاء صفوان بن المعطّل، وكان في الساقة وراء الجيش، فاسترجع، فتجلببت وغطّت وجهها، فأناخ راحلته فركبتها وقادها حتى انتهى إلى المعسكر. فقال ابن أُبيّ: والله ما نجت منه ولا نجا منها، وروّج للفتنة، فردّدها حسان بن ثابت ومسطح بن أثاثة وحمنة بنت جحش، واضطربت لها نفس رسول الله ﷺ، فأنزل الله براءة عائشة وصفوان. إن الذين جاءوا بهذا الكذب المقلوب جماعة منكم، لا تحسبوه شراً لكم، بل هو خير لكم لعاقبته الحسنة وعظم الأجر، لكل امرئ منهم ما اكتسب من الإثم، والذي تولّى معظمه منهم له عذاب عظيم. هلّا إذ سمعتموه ظننتم بأنفسكم خيراً، إذ المؤمنون كنفس واحدة، وقلتم: هذا إفك مبين؟ هلّا جاءوا عليه بأربعة شهداء؟ فإذ لم يأتوا فهم عند الله الكاذبون. ولولا فضل الله عليكم ورحمته لمسّكم فيما خضتم فيه عذاب عظيم، إذ يتلقّاه بعضكم من بعض بألسنتكم، وتقولون ما ليس لكم به علم، وتحسبونه هيّناً وهو عند الله عظيم، يمسّ عرض رسول الله وآل بيته. وهلّا قلتم إذ سمعتموه: ما يكون لنا أن نتكلّم بهذا، سبحانك هذا بهتان عظيم؟ يعظكم الله أن تعودوا لمثله أبداً إن كنتم مؤمنين.", "h": ["قضاء الله تعالى للمؤمن كله خير له.", "بشاعة الإفك وعظيم جرمه.", "العقوبة على قدر الجرم كبراً وصغراً، قلة وكثرة.", "واجب المؤمن ألا يصدّق من يرمي مؤمناً بفاحشة، وأن يقول له: هل تستطيع أن تأتي بأربعة شهداء على قولك؟ فإن قال: لا، قال له: إذاً أنت عند الله من الكاذبين.", "حرمة القول بدون علم والخوض في ذلك."], "k": "«إذ تلقّونه بألسنتكم… وتحسبونه هيّناً وهو عند الله عظيم»… خبر أسمعه عن أحد؛ هل أوقفه عندي أم أمرّره؟"}, {"lbl": "الآيات ١٩ – ٢٢", "q": "إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿١٩﴾ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٞ رَّحِيمٞ ﴿٢٠﴾ ۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ﴿٢١﴾ وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ ﴿٢٢﴾", "w": [["أن تشيع الفاحشة", "تعمّ المجتمع وتنتشر فيه، والفاحشة: الزنا."], ["ولولا فضل الله عليكم ورحمته", "جوابه محذوف تقديره: لعاجلكم بالعقوبة."], ["خطوات الشيطان", "نزغاته ووساوسه."], ["ما زكى منكم من أحد أبداً", "ما طهر ظاهره وباطنه."], ["ولا يأتل أولو الفضل منكم", "ولا يحلف صاحب الفضل منكم، وهو أبو بكر الصديق."], ["والسعة", "سعة الرزق والفضل والإحسان إلى الغير."]], "m": "ما زال السياق في عتاب المؤمنين الذين خاضوا في الإفك: إن الذين يحبّون أن تنتشر الفاحشة في المؤمنين لهم عذاب أليم في الدنيا بحد القذف وإسقاط العدالة، وفي الآخرة إن لم يتوبوا، والله يعلم ما يترتّب على ذلك من الآثار السيئة وأنتم لا تعلمون. ولولا فضل الله عليكم ورحمته لعاجلكم بالعقوبة. يا أيها الذين آمنوا لا تتبعوا خطوات الشيطان فيما يزيّن من قبيح المعاصي، فإن من يتبعه لا يلبث أن يصبح شيطاناً يأمر بالفحشاء والمنكر، فقاوموا نزغاته بالاستعاذة بالله. ولولا فضل الله عليكم ورحمته بحفظكم ما طهر منكم من أحد أبداً لضعفكم، فعلى الذين نجوا مما وقع فيه أهل الإفك أن يستغفروا لإخوانهم ويقلّلوا من لومهم ويتواضعوا، ولكن الله يزكّي من يشاء، فليُطلب منه. ولا يحلف أهل الفضل والسعة ألا يعطوا أولي القربى والمساكين والمهاجرين، نزلت في أبي بكر لما حلف أن يمنع مسطح بن أثاثة، وهو ابن خالته الفقير المهاجر، ما كان يعطيه بعدما وقع في الإفك، وليعفوا وليصفحوا عما قالوا، ألا تحبّون أن يغفر الله لكم؟ فقال أبو بكر: بلى والله إني لأحب أن يغفر الله لي، فعفا وكفّر عن يمينه وردّ النفقة، والله غفور رحيم.", "h": ["لقبح فاحشة الزنا وضع الله تعالى لمقاومتها أموراً، منها: الحد الشرعي، ومنع تزويج الزاني من عفيفة إلا بعد التوبة، وحدّ القذف، واللعان، وحرمة ظن السوء بالمؤمنين، وحرمة حب إشاعة الفاحشة، ووجوب الاستئذان، وغضّ البصر، واحتجاب المؤمنة عن الأجانب، ووجوب تزويج العزّاب، وهذه كلها أسباب واقية من أخطر فاحشة.", "حرمة اتباع الشيطان فيما يزيّنه من الباطل والسوء والفحشاء والمنكر.", "متابعة الشيطان والجري وراءه في كل ما يدعو إليه يؤدّي بالعبد أن يصبح شيطاناً يأمر بالفحشاء والمنكر.", "على من حفظهم الله من الوقوع في السوء أن يتطامنوا ولا يشعروا بالكبر، فإن عصمتهم من الله لا من أنفسهم.", "من حلف على شيء ورأى غيره خيراً منه كفّر عن يمينه وأتى الذي هو خير.", "وجوب العفو والصفح على ذوي المروءات، وإقالة عثرتهم إن هم تابوا وأصلحوا."], "k": "«ألا تحبون أن يغفر الله لكم»… من أحتاج أن أعفو عنه الليلة؟"}, {"lbl": "الآيات ٢٣ – ٢٦", "q": "إِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمٞ ﴿٢٣﴾ يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا كَانُواْ يَعۡمَلُونَ ﴿٢٤﴾ يَوۡمَئِذٖ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلۡحَقَّ وَيَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِينُ ﴿٢٥﴾ ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَـٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٢٦﴾", "w": [["يرمون المحصنات", "العفيفات بالزنا."], ["الغافلات", "عن الفواحش، بحيث لم يقع في قلوبهن فعلها."], ["المؤمنات", "بالله ورسوله ووعد الله ووعيده."], ["بما كانوا يعملون", "من قول أو عمل."], ["يوفّيهم الله دينهم الحق", "يجازيهم جزاءهم الواجب عليهم."], ["الخبيثات للخبيثين", "الخبيثات من النساء والكلمات للخبيثين من الرجال."], ["والطيبات للطيبين", "الطيبات من النساء والكلمات للطيبين من الرجال."], ["أولئك مبرّءون", "صفوان بن المعطّل وعائشة، مبرّءون مما قاله أهل الإفك."]], "m": "إن الذين يرمون المؤمنات العفيفات الغافلات عن الفواحش لسلامة صدورهن، وهي وإن تناولت ابتداءً ابن أُبيّ فهي عامة في كل قاذف، لُعنوا في الدنيا والآخرة، أي أُبعدوا من الرحمة، ولهم عذاب عظيم، في الدنيا بإقامة الحد، وفي الآخرة بالنار، يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون، يومئذ يوفّيهم الله جزاءهم الواجب، ويعلمون أن الله هو الحق المبين. الخبيثات من النساء والكلمات للخبيثين من الرجال كابن أُبيّ، والخبيثون للخبيثات، والطيبات للطيبين كالنبي ﷺ وعائشة، والطيبون للطيبات، أولئك، صفوان وعائشة، مبرّءون مما يقول أهل الإفك، لهم مغفرة لذنوبهم التي لا يخلو منها مؤمن، ورزق كريم في الجنة، وبهذا تمت براءة أم المؤمنين.", "h": ["عظم ذنب قذف المحصنات الغافلات المؤمنات، وقد عدّه رسول الله ﷺ في السبع الموبقات.", "تقرير الحساب وما يتم فيه من استنطاق واستجواب.", "استحقاق الخبث أهله، فالخبيث هو الذي يناسبه القول الخبيث والفعل الخبيث.", "استحقاق الطيب أهله، فالطيب هو الذي يناسبه القول الطيب والفعل الطيب.", "براءة أم المؤمنين وصفوان مما رماهما به أهل الإفك.", "بشارة أم المؤمنين وصفوان بالجنة بعد مغفرة ذنوبهما."], "k": "«يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم»… لساني ويداي ستشهد؛ فبماذا تشهد اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 249;
insert into public.tdb_cards(topic, i, body) select 249, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١ – ١٨", "q": "إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ خَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ ﴿١١﴾ لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرٗا وَقَالُواْ هَٰذَآ إِفۡكٞ مُّبِينٞ ﴿١٢﴾ لَّوۡلَا جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَـٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ ﴿١٣﴾ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ ﴿١٤﴾ إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ ﴿١٥﴾ وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ ﴿١٦﴾ يَعِظُكُمُ ٱللَّهُ أَن تَعُودُواْ لِمِثۡلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤۡمِنِينَ ﴿١٧﴾ وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ﴿١٨﴾", "w": [["بالإفك عصبة", "الإفك: الكذب المقلوب، وهو أسوأ الكذب، والعصبة: الجماعة."], ["شراً لكم بل هو خير لكم", "الشر ما غلب ضرره على نفعه، والخير ما غلب نفعه على ضرره."], ["والذي تولّى كبره", "معظمه، وهو ابن أُبيّ كبير المنافقين."], ["لولا", "أداة تحضيض بمعنى هلّا."], ["فيما أفضتم فيه", "فيما تحدّثتم فيه بتوسّع وعدم تحفّظ."], ["إذ تلقّونه", "يتلقّاه بعضكم من بعض."], ["وتحسبونه هيّناً", "من صغائر الذنوب، وهو عند الله من كبائرها، لأنه عرض مؤمنة هي زوج رسول الله ﷺ."], ["سبحانك", "كلمة تقال عند التعجّب، والمراد تنزيه الله عما لا يليق به."], ["بهتان عظيم", "البهتان: الكذب الذي يحيّر من قيل فيه."], ["يعظكم الله", "ينهاكم نهياً مقروناً بالوعيد حتى لا تعودوا لمثله أبداً."]], "m": "بعد حكم القذف العام والخاص ذكر حادثة الإفك: بعد فرض الحجاب خرج رسول الله ﷺ إلى غزوة بني المصطلق، فلما عاد وقارب المدينة نزل ليلاً ثم ارتحل، فوضعوا هودج عائشة على البعير ظانّين أنها فيه، وكانت قد عادت تلتمس عقداً لها سقط، فوجدت الجيش قد رحل فجلست في مكانها لعلهم يرجعون، حتى جاء صفوان بن المعطّل، وكان في الساقة وراء الجيش، فاسترجع، فتجلببت وغطّت وجهها، فأناخ راحلته فركبتها وقادها حتى انتهى إلى المعسكر. فقال ابن أُبيّ: والله ما نجت منه ولا نجا منها، وروّج للفتنة، فردّدها حسان بن ثابت ومسطح بن أثاثة وحمنة بنت جحش، واضطربت لها نفس رسول الله ﷺ، فأنزل الله براءة عائشة وصفوان. إن الذين جاءوا بهذا الكذب المقلوب جماعة منكم، لا تحسبوه شراً لكم، بل هو خير لكم لعاقبته الحسنة وعظم الأجر، لكل امرئ منهم ما اكتسب من الإثم، والذي تولّى معظمه منهم له عذاب عظيم. هلّا إذ سمعتموه ظننتم بأنفسكم خيراً، إذ المؤمنون كنفس واحدة، وقلتم: هذا إفك مبين؟ هلّا جاءوا عليه بأربعة شهداء؟ فإذ لم يأتوا فهم عند الله الكاذبون. ولولا فضل الله عليكم ورحمته لمسّكم فيما خضتم فيه عذاب عظيم، إذ يتلقّاه بعضكم من بعض بألسنتكم، وتقولون ما ليس لكم به علم، وتحسبونه هيّناً وهو عند الله عظيم، يمسّ عرض رسول الله وآل بيته. وهلّا قلتم إذ سمعتموه: ما يكون لنا أن نتكلّم بهذا، سبحانك هذا بهتان عظيم؟ يعظكم الله أن تعودوا لمثله أبداً إن كنتم مؤمنين.", "h": ["قضاء الله تعالى للمؤمن كله خير له.", "بشاعة الإفك وعظيم جرمه.", "العقوبة على قدر الجرم كبراً وصغراً، قلة وكثرة.", "واجب المؤمن ألا يصدّق من يرمي مؤمناً بفاحشة، وأن يقول له: هل تستطيع أن تأتي بأربعة شهداء على قولك؟ فإن قال: لا، قال له: إذاً أنت عند الله من الكاذبين.", "حرمة القول بدون علم والخوض في ذلك."], "k": "«إذ تلقّونه بألسنتكم… وتحسبونه هيّناً وهو عند الله عظيم»… خبر أسمعه عن أحد؛ هل أوقفه عندي أم أمرّره؟"}, {"lbl": "الآيات ١٩ – ٢٢", "q": "إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿١٩﴾ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٞ رَّحِيمٞ ﴿٢٠﴾ ۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ﴿٢١﴾ وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ ﴿٢٢﴾", "w": [["أن تشيع الفاحشة", "تعمّ المجتمع وتنتشر فيه، والفاحشة: الزنا."], ["ولولا فضل الله عليكم ورحمته", "جوابه محذوف تقديره: لعاجلكم بالعقوبة."], ["خطوات الشيطان", "نزغاته ووساوسه."], ["ما زكى منكم من أحد أبداً", "ما طهر ظاهره وباطنه."], ["ولا يأتل أولو الفضل منكم", "ولا يحلف صاحب الفضل منكم، وهو أبو بكر الصديق."], ["والسعة", "سعة الرزق والفضل والإحسان إلى الغير."]], "m": "ما زال السياق في عتاب المؤمنين الذين خاضوا في الإفك: إن الذين يحبّون أن تنتشر الفاحشة في المؤمنين لهم عذاب أليم في الدنيا بحد القذف وإسقاط العدالة، وفي الآخرة إن لم يتوبوا، والله يعلم ما يترتّب على ذلك من الآثار السيئة وأنتم لا تعلمون. ولولا فضل الله عليكم ورحمته لعاجلكم بالعقوبة. يا أيها الذين آمنوا لا تتبعوا خطوات الشيطان فيما يزيّن من قبيح المعاصي، فإن من يتبعه لا يلبث أن يصبح شيطاناً يأمر بالفحشاء والمنكر، فقاوموا نزغاته بالاستعاذة بالله. ولولا فضل الله عليكم ورحمته بحفظكم ما طهر منكم من أحد أبداً لضعفكم، فعلى الذين نجوا مما وقع فيه أهل الإفك أن يستغفروا لإخوانهم ويقلّلوا من لومهم ويتواضعوا، ولكن الله يزكّي من يشاء، فليُطلب منه. ولا يحلف أهل الفضل والسعة ألا يعطوا أولي القربى والمساكين والمهاجرين، نزلت في أبي بكر لما حلف أن يمنع مسطح بن أثاثة، وهو ابن خالته الفقير المهاجر، ما كان يعطيه بعدما وقع في الإفك، وليعفوا وليصفحوا عما قالوا، ألا تحبّون أن يغفر الله لكم؟ فقال أبو بكر: بلى والله إني لأحب أن يغفر الله لي، فعفا وكفّر عن يمينه وردّ النفقة، والله غفور رحيم.", "h": ["لقبح فاحشة الزنا وضع الله تعالى لمقاومتها أموراً، منها: الحد الشرعي، ومنع تزويج الزاني من عفيفة إلا بعد التوبة، وحدّ القذف، واللعان، وحرمة ظن السوء بالمؤمنين، وحرمة حب إشاعة الفاحشة، ووجوب الاستئذان، وغضّ البصر، واحتجاب المؤمنة عن الأجانب، ووجوب تزويج العزّاب، وهذه كلها أسباب واقية من أخطر فاحشة.", "حرمة اتباع الشيطان فيما يزيّنه من الباطل والسوء والفحشاء والمنكر.", "متابعة الشيطان والجري وراءه في كل ما يدعو إليه يؤدّي بالعبد أن يصبح شيطاناً يأمر بالفحشاء والمنكر.", "على من حفظهم الله من الوقوع في السوء أن يتطامنوا ولا يشعروا بالكبر، فإن عصمتهم من الله لا من أنفسهم.", "من حلف على شيء ورأى غيره خيراً منه كفّر عن يمينه وأتى الذي هو خير.", "وجوب العفو والصفح على ذوي المروءات، وإقالة عثرتهم إن هم تابوا وأصلحوا."], "k": "«ألا تحبون أن يغفر الله لكم»… من أحتاج أن أعفو عنه الليلة؟"}, {"lbl": "الآيات ٢٣ – ٢٦", "q": "إِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمٞ ﴿٢٣﴾ يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا كَانُواْ يَعۡمَلُونَ ﴿٢٤﴾ يَوۡمَئِذٖ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلۡحَقَّ وَيَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِينُ ﴿٢٥﴾ ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَـٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٢٦﴾", "w": [["يرمون المحصنات", "العفيفات بالزنا."], ["الغافلات", "عن الفواحش، بحيث لم يقع في قلوبهن فعلها."], ["المؤمنات", "بالله ورسوله ووعد الله ووعيده."], ["بما كانوا يعملون", "من قول أو عمل."], ["يوفّيهم الله دينهم الحق", "يجازيهم جزاءهم الواجب عليهم."], ["الخبيثات للخبيثين", "الخبيثات من النساء والكلمات للخبيثين من الرجال."], ["والطيبات للطيبين", "الطيبات من النساء والكلمات للطيبين من الرجال."], ["أولئك مبرّءون", "صفوان بن المعطّل وعائشة، مبرّءون مما قاله أهل الإفك."]], "m": "إن الذين يرمون المؤمنات العفيفات الغافلات عن الفواحش لسلامة صدورهن، وهي وإن تناولت ابتداءً ابن أُبيّ فهي عامة في كل قاذف، لُعنوا في الدنيا والآخرة، أي أُبعدوا من الرحمة، ولهم عذاب عظيم، في الدنيا بإقامة الحد، وفي الآخرة بالنار، يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون، يومئذ يوفّيهم الله جزاءهم الواجب، ويعلمون أن الله هو الحق المبين. الخبيثات من النساء والكلمات للخبيثين من الرجال كابن أُبيّ، والخبيثون للخبيثات، والطيبات للطيبين كالنبي ﷺ وعائشة، والطيبون للطيبات، أولئك، صفوان وعائشة، مبرّءون مما يقول أهل الإفك، لهم مغفرة لذنوبهم التي لا يخلو منها مؤمن، ورزق كريم في الجنة، وبهذا تمت براءة أم المؤمنين.", "h": ["عظم ذنب قذف المحصنات الغافلات المؤمنات، وقد عدّه رسول الله ﷺ في السبع الموبقات.", "تقرير الحساب وما يتم فيه من استنطاق واستجواب.", "استحقاق الخبث أهله، فالخبيث هو الذي يناسبه القول الخبيث والفعل الخبيث.", "استحقاق الطيب أهله، فالطيب هو الذي يناسبه القول الطيب والفعل الطيب.", "براءة أم المؤمنين وصفوان مما رماهما به أهل الإفك.", "بشارة أم المؤمنين وصفوان بالجنة بعد مغفرة ذنوبهما."], "k": "«يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم»… لساني ويداي ستشهد؛ فبماذا تشهد اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (250, 24, 27, 31, 'سورة النور ٢٧ – ٣١', '«لا تدخلوا بيوتاً غير بيوتكم حتى تستأنسوا»، و«قل للمؤمنين يغضّوا من أبصارهم… وقل للمؤمنات»، و«وتوبوا إلى الله جميعاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 250) = $j$[{"lbl": "الآيات ٢٧ – ٢٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿٢٧﴾ فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدٗا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ ﴿٢٨﴾ لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَدۡخُلُواْ بُيُوتًا غَيۡرَ مَسۡكُونَةٖ فِيهَا مَتَٰعٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ ﴿٢٩﴾", "w": [["آمنوا", "صدّقوا الله ورسوله فيما أخبرا به من الغيب والشرع."], ["تستأنسوا", "تستأذنوا، إذ الاستئذان من عمل الإنسان، والدخول بدونه من عمل الحيوان الوحشي."], ["وتسلّموا على أهلها", "تقولوا: السلام عليكم، أأدخل؟ ثلاثاً."], ["تذكّرون", "تذكرون أنكم مؤمنون، وأن الله أمركم بالاستئذان."], ["أزكى لكم", "أطهر وأبعد عن الريبة والإثم."], ["ليس عليكم جناح", "إثم ولا حرج."], ["فيها متاع لكم", "ما تتمتّعون به كالنزول بها أو شراء حاجة منها."], ["ما تبدون", "ما تظهرونه."], ["وما تكتمون", "ما تخفونه، فراقبوه ولا تضمروا ما لا يرضى."]], "m": "لخطر الرمي بالفاحشة وفعلها ناسب ذكر وسيلة من وسائل الوقاية منها، ففرض الاستئذان: يا من آمنتم لا تدخلوا بيوتاً غير بيوتكم حتى تسلّموا على أهلها: السلام عليكم، وتستأذنوا: أأدخل؟ ثلاث مرات، فإن أُذن لكم دخلتم، وعبّر عن الاستئذان بالاستئناس لأنه وارد في لغة العرب، ولأن الاستئذان من خصائص الإنسان، والدخول بلا إذن من خصائص الحيوان المتوحّش. ذلكم خير لكم لما فيه من الوقاية من الإثم، لعلكم تذكرون فيزداد إيمانكم. فإن لم تجدوا فيها أحداً يأذن لكم فلا تدخلوها، وإن قيل لكم: ارجعوا، لأمر اقتضاه، فارجعوا راضين غير ساخطين، هو أطهر لنفوسكم، والله بما تعملون عليم. ليس عليكم إثم أن تدخلوا بيوتاً غير مسكونة، ليس فيها نساء، كالدكاكين والفنادق، لقضاء حاجاتكم بلا استئذان لأنها مفتوحة للعموم، أما السلام فسنّة، والله يعلم ما تظهرون وما تخفون، فراقبوه.", "h": ["مشروعية الاستئذان ووجوبه على كل من أراد أن يدخل بيتاً مسكوناً غير بيته.", "الرخصة في عدم الاستئذان في دخول البيوت والمحلات غير المسكونة.", "من آداب الاستئذان أن يقف بجانب الباب فلا يعترضه، وأن يرفع صوته بقدر الحاجة، وأن يقرع الباب قرعاً خفيفاً، وأن يقول: السلام عليكم، أأدخل؟ ثلاث مرات.", "في كل طاعة خير وبركة وإن كانت كلمة طيبة."], "k": "«وإن قيل لكم ارجعوا فارجعوا هو أزكى لكم»… هل أقبل الردّ بنفس راضية لا ساخطة؟"}, {"lbl": "الآيتان ٣٠ – ٣١", "q": "قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ ﴿٣٠﴾ وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّـٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٣١﴾", "w": [["يغضّوا من أبصارهم", "يخفضوا من أبصارهم حتى لا ينظروا إلى نساء لا يحل لهم النظر إليهن."], ["ويحفظوا فروجهم", "يصونوها من النظر إليها ومن إتيان الفاحشة."], ["أزكى لهم", "أكثر تزكية لنفوسهم من فعل المندوبات والمستحبات."], ["ولا يبدين زينتهن", "مواضع الزينة كالساقين والكفّين والذراعين والرأس والأذنين والعنق والصدر."], ["إلا ما ظهر منها", "بالضرورة دون اختيار، كالكفين لتناول شيء، والعين للنظر، والثياب الظاهرة كالخمار والعباءة."], ["بخمرهن على جيوبهن", "لتضرب المرأة المسلمة بخمارها على فتحات الثياب في الصدر وغيره حتى لا يبدو شيء."], ["إلا لبعولتهن", "البعل: الزوج، والجمع بعول."], ["أو نسائهن", "المسلمات."], ["أو ما ملكت أيمانهن", "العبيد والجواري."], ["أو التابعين غير أولي الإربة", "التابعين لأهل البيت ممن لا حاجة لهم إلى النساء."], ["أو الطفل", "الأطفال الصغار قبل التمييز والبلوغ."], ["لم يظهروا على عورات النساء", "لم يبلغوا سناً تدعوهم إلى الاطلاع على عورات النساء."], ["ليُعلم ما يخفين من زينتهن", "الخلاخل في الرجلين."], ["تفلحون", "تفوزون بالنجاة من العار والنار، وبالظفر بالطهر والشرف."]], "m": "لقبح الزنا وضع الشارع أسباباً واقية منه، ومنها غض البصر للرجال والنساء: قل للمؤمنين يخفضوا أجفانهم حتى لا ينظروا إلى الأجنبيات، ويحفظوا فروجهم فلا يكشفوها إلا للزوج، ذلك أطهر لنفوسهم من نوافل العبادات، إن الله خبير بما يصنعون، يعلم خائنة الأعين. وقل للمؤمنات: شأنهن شأن الرجال في غض البصر وحفظ الفرج، ولا يظهرن زينتهن إلا ما لا يمكن ستره، كالكفّين عند تناول شيء، والعينين ينظرن بهما، والثياب الظاهرة كالخمار والعباءة. وليضربن بخمرهن على فتحات صدورهن، إذ كانت المرأة تضع خمارها على رأسها مسبلاً على كتفيها، فأُمرت أن تستر العنق والصدر ستراً كاملاً. ولا يبدين زينتهن إلا لمحارمهن: الزوج، والأب والجد، وأب الزوج، والابن، وابن الزوج، والإخوة وأبنائهم، وأبناء الأخوات، والنساء المسلمات، والمملوك، والتابع ممن لا حاجة له في النساء لكبر أو مرض، والطفل الذي لم يميّز. ولا يضربن بأرجلهن الأرض ليُعلم ما يخفين من الخلاخل. وتوبوا إلى الله جميعاً أيها المؤمنون من كل ما يغضبه، لعلكم تفوزون بالنجاة من المرهوب والظفر بالمحبوب.", "h": ["وجوب غض البصر وحفظ الفرج.", "وجوب ستر المرأة زينتها ومواضع ذلك، ما عدا ما يتعذّر ستره للضرورة.", "بيان المحارم الذين للمرأة المؤمنة أن تبدي زينتها عندهم بلا حرج.", "الرخصة في إظهار الزينة للهرم المخرّف من الرجال والمعتوه والطفل الصغير.", "حرمة ضرب ذات الخلاخل الأرض برجلها حتى لا يُعلم ما تخفي من زينتها.", "وجوب التوبة من كل ذنب، وعلى الفور، للحصول على الفلاح العاجل والآجل."], "k": "«وتوبوا إلى الله جميعاً أيها المؤمنون»… نظرة لم أغضّها؛ أتوب منها الآن وأستعين على ما بعدها."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 250;
insert into public.tdb_cards(topic, i, body) select 250, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٧ – ٢٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿٢٧﴾ فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدٗا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ ﴿٢٨﴾ لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَدۡخُلُواْ بُيُوتًا غَيۡرَ مَسۡكُونَةٖ فِيهَا مَتَٰعٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ ﴿٢٩﴾", "w": [["آمنوا", "صدّقوا الله ورسوله فيما أخبرا به من الغيب والشرع."], ["تستأنسوا", "تستأذنوا، إذ الاستئذان من عمل الإنسان، والدخول بدونه من عمل الحيوان الوحشي."], ["وتسلّموا على أهلها", "تقولوا: السلام عليكم، أأدخل؟ ثلاثاً."], ["تذكّرون", "تذكرون أنكم مؤمنون، وأن الله أمركم بالاستئذان."], ["أزكى لكم", "أطهر وأبعد عن الريبة والإثم."], ["ليس عليكم جناح", "إثم ولا حرج."], ["فيها متاع لكم", "ما تتمتّعون به كالنزول بها أو شراء حاجة منها."], ["ما تبدون", "ما تظهرونه."], ["وما تكتمون", "ما تخفونه، فراقبوه ولا تضمروا ما لا يرضى."]], "m": "لخطر الرمي بالفاحشة وفعلها ناسب ذكر وسيلة من وسائل الوقاية منها، ففرض الاستئذان: يا من آمنتم لا تدخلوا بيوتاً غير بيوتكم حتى تسلّموا على أهلها: السلام عليكم، وتستأذنوا: أأدخل؟ ثلاث مرات، فإن أُذن لكم دخلتم، وعبّر عن الاستئذان بالاستئناس لأنه وارد في لغة العرب، ولأن الاستئذان من خصائص الإنسان، والدخول بلا إذن من خصائص الحيوان المتوحّش. ذلكم خير لكم لما فيه من الوقاية من الإثم، لعلكم تذكرون فيزداد إيمانكم. فإن لم تجدوا فيها أحداً يأذن لكم فلا تدخلوها، وإن قيل لكم: ارجعوا، لأمر اقتضاه، فارجعوا راضين غير ساخطين، هو أطهر لنفوسكم، والله بما تعملون عليم. ليس عليكم إثم أن تدخلوا بيوتاً غير مسكونة، ليس فيها نساء، كالدكاكين والفنادق، لقضاء حاجاتكم بلا استئذان لأنها مفتوحة للعموم، أما السلام فسنّة، والله يعلم ما تظهرون وما تخفون، فراقبوه.", "h": ["مشروعية الاستئذان ووجوبه على كل من أراد أن يدخل بيتاً مسكوناً غير بيته.", "الرخصة في عدم الاستئذان في دخول البيوت والمحلات غير المسكونة.", "من آداب الاستئذان أن يقف بجانب الباب فلا يعترضه، وأن يرفع صوته بقدر الحاجة، وأن يقرع الباب قرعاً خفيفاً، وأن يقول: السلام عليكم، أأدخل؟ ثلاث مرات.", "في كل طاعة خير وبركة وإن كانت كلمة طيبة."], "k": "«وإن قيل لكم ارجعوا فارجعوا هو أزكى لكم»… هل أقبل الردّ بنفس راضية لا ساخطة؟"}, {"lbl": "الآيتان ٣٠ – ٣١", "q": "قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ ﴿٣٠﴾ وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّـٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٣١﴾", "w": [["يغضّوا من أبصارهم", "يخفضوا من أبصارهم حتى لا ينظروا إلى نساء لا يحل لهم النظر إليهن."], ["ويحفظوا فروجهم", "يصونوها من النظر إليها ومن إتيان الفاحشة."], ["أزكى لهم", "أكثر تزكية لنفوسهم من فعل المندوبات والمستحبات."], ["ولا يبدين زينتهن", "مواضع الزينة كالساقين والكفّين والذراعين والرأس والأذنين والعنق والصدر."], ["إلا ما ظهر منها", "بالضرورة دون اختيار، كالكفين لتناول شيء، والعين للنظر، والثياب الظاهرة كالخمار والعباءة."], ["بخمرهن على جيوبهن", "لتضرب المرأة المسلمة بخمارها على فتحات الثياب في الصدر وغيره حتى لا يبدو شيء."], ["إلا لبعولتهن", "البعل: الزوج، والجمع بعول."], ["أو نسائهن", "المسلمات."], ["أو ما ملكت أيمانهن", "العبيد والجواري."], ["أو التابعين غير أولي الإربة", "التابعين لأهل البيت ممن لا حاجة لهم إلى النساء."], ["أو الطفل", "الأطفال الصغار قبل التمييز والبلوغ."], ["لم يظهروا على عورات النساء", "لم يبلغوا سناً تدعوهم إلى الاطلاع على عورات النساء."], ["ليُعلم ما يخفين من زينتهن", "الخلاخل في الرجلين."], ["تفلحون", "تفوزون بالنجاة من العار والنار، وبالظفر بالطهر والشرف."]], "m": "لقبح الزنا وضع الشارع أسباباً واقية منه، ومنها غض البصر للرجال والنساء: قل للمؤمنين يخفضوا أجفانهم حتى لا ينظروا إلى الأجنبيات، ويحفظوا فروجهم فلا يكشفوها إلا للزوج، ذلك أطهر لنفوسهم من نوافل العبادات، إن الله خبير بما يصنعون، يعلم خائنة الأعين. وقل للمؤمنات: شأنهن شأن الرجال في غض البصر وحفظ الفرج، ولا يظهرن زينتهن إلا ما لا يمكن ستره، كالكفّين عند تناول شيء، والعينين ينظرن بهما، والثياب الظاهرة كالخمار والعباءة. وليضربن بخمرهن على فتحات صدورهن، إذ كانت المرأة تضع خمارها على رأسها مسبلاً على كتفيها، فأُمرت أن تستر العنق والصدر ستراً كاملاً. ولا يبدين زينتهن إلا لمحارمهن: الزوج، والأب والجد، وأب الزوج، والابن، وابن الزوج، والإخوة وأبنائهم، وأبناء الأخوات، والنساء المسلمات، والمملوك، والتابع ممن لا حاجة له في النساء لكبر أو مرض، والطفل الذي لم يميّز. ولا يضربن بأرجلهن الأرض ليُعلم ما يخفين من الخلاخل. وتوبوا إلى الله جميعاً أيها المؤمنون من كل ما يغضبه، لعلكم تفوزون بالنجاة من المرهوب والظفر بالمحبوب.", "h": ["وجوب غض البصر وحفظ الفرج.", "وجوب ستر المرأة زينتها ومواضع ذلك، ما عدا ما يتعذّر ستره للضرورة.", "بيان المحارم الذين للمرأة المؤمنة أن تبدي زينتها عندهم بلا حرج.", "الرخصة في إظهار الزينة للهرم المخرّف من الرجال والمعتوه والطفل الصغير.", "حرمة ضرب ذات الخلاخل الأرض برجلها حتى لا يُعلم ما تخفي من زينتها.", "وجوب التوبة من كل ذنب، وعلى الفور، للحصول على الفلاح العاجل والآجل."], "k": "«وتوبوا إلى الله جميعاً أيها المؤمنون»… نظرة لم أغضّها؛ أتوب منها الآن وأستعين على ما بعدها."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (251, 24, 32, 38, 'سورة النور ٣٢ – ٣٨', '«وأنكحوا الأيامى منكم»، و«وليستعفف الذين لا يجدون نكاحاً»، و«الله نور السماوات والأرض»، و«رجال لا تلهيهم تجارة ولا بيع عن ذكر الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 251) = $j$[{"lbl": "الآيات ٣٢ – ٣٤", "q": "وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّـٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ﴿٣٢﴾ وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِيهِمۡ خَيۡرٗاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنٗا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورٞ رَّحِيمٞ ﴿٣٣﴾ وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ ءَايَٰتٖ مُّبَيِّنَٰتٖ وَمَثَلٗا مِّنَ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۡ وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ ﴿٣٤﴾", "w": [["وأنكحوا الأيامى منكم", "زوّجوا من لا زوجة له من رجالكم، ومن لا زوج لها من نسائكم."], ["والصالحين من عبادكم وإمائكم", "زوّجوا القادرين والقادرات على أعباء الزواج من عبيدكم وإمائكم."], ["إن يكونوا فقراء يغنهم الله من فضله", "إن يكن الأيامى فقراء فلا يمنعكم ذلك من تزويجهم، فإن الله يغنيهم."], ["إن الله واسع عليم", "واسع الفضل، عليم بحاجة العبد فيسدّها تكرّماً."], ["وليستعفف", "وليطلب عفّة نفسه بالصبر والصيام."], ["يبتغون الكتاب", "يطلبون المكاتبة من المماليك."], ["إن علمتم فيهم خيراً", "قدرة على السداد والاستقلال عنكم."], ["وآتوهم من مال الله", "أعينوهم بنجم من نجوم المكاتبة من الزكاة وغيرها."], ["على البغاء إن أردن تحصّناً", "على الزنا، إن أردن تعفّفاً وتحفّظاً من الفاحشة."], ["عرض الحياة الدنيا", "المال."], ["مبيّنات", "للأحكام، موضّحة لما يُطلب منكم فعله وتركه."], ["ومثلاً من الذين خلوا من قبلكم", "قصصاً من أخبار الأولين كقصة يوسف ومريم، وهما شبيهتان بحادثة الإفك."], ["وموعظة", "ما يتّعظ به العبد فيسلك سبيل النجاة."]], "m": "ما زال السياق في الأسباب الواقية من الفاحشة: أمر الله جماعة المسلمين أن يزوّجوا الأيامى من رجالهم ونسائهم بالمساعدة والإعانة، حتى لا يبقى في البلد عزب إلا نادراً، والبكر والثيب في ذلك سواء، وأن يزوّجوا القادرين على مؤونة الزواج من مماليكهم، ولا يمنعكم فقرهم، فقد تكفّل الله بغناهم بعد زواجهم، والله واسع الفضل عليم بحاجة المحتاجين. وأمر من لا يجد نكاحاً، لانعدام الزوج أو مؤونة الزواج من مهر ووليمة، أن يعفّ نفسه بالصبر والصيام والصلاة حتى لا يتطلّع إلى الحرام، حتى يغنيه الله من فضله. والمسألة الثالثة: إذا طلب العبد من مالكه أن يكاتبه، وكان قادراً على السداد مستطيعاً أن يستقل بنفسه، فعليه أن يكاتبه ويعينه بإسقاط نجم من نجوم الكتابة. والرابعة: كان لابن أُبيّ جاريتان أسلمتا فأمرهما بالزنا ليكسب بهما، فشكتا إلى رسول الله ﷺ، فنزل: ولا تكرهوا فتياتكم على البغاء إن أردن تعفّفاً لأجل مال قليل يزول بسرعة، ومن يكرههن فإن الله من بعد إكراههن غفور لهن رحيم بهن، إذ المكره لا إثم عليه. ولقد أنزلنا إليكم آيات مبيّنات للشرائع والأحكام، وقصصاً من أخبار الأولين، وموعظة ينتفع بها المتقون.", "h": ["انتداب المسلمين، حاكمين ومحكومين، للمساعدة على تزويج الأيامى من المسلمين.", "وجوب الاستعفاف على من لم يجد نكاحاً، والصبر حتى ييسّر الله أمره.", "عِدة الله للفقير إذا تزوّج بالغنى.", "تعيّن مكاتبة العبد إذا توفّرت فيه شروط المكاتبة.", "حرمة الزنا بالإكراه أو بالاختيار، ومنع ذلك بإقامة الحدود.", "صيغة الكتابة أن يقول السيد للعبد: قد كاتبتك على مال منجّم، أي مقسّط على أقساط تُدفع في آجالها، فإذا وفّيتها فأنت حر.", "بيان فضل سورة النور لما احتوته من أحكام في غاية الأهمية."], "k": "«إن يكونوا فقراء يغنهم الله من فضله»… هل أعين شاباً على الحلال، أم أعسّر عليه طريقه؟"}, {"lbl": "الآيات ٣٥ – ٣٨", "q": "۞ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةٖ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبٞ دُرِّيّٞ يُوقَدُ مِن شَجَرَةٖ مُّبَٰرَكَةٖ زَيۡتُونَةٖ لَّا شَرۡقِيَّةٖ وَلَا غَرۡبِيَّةٖ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارٞۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٣٥﴾ فِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ ﴿٣٦﴾ رِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ ﴿٣٧﴾ لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ ﴿٣٨﴾", "w": [["الله نور السماوات", "منوّرهما، فلولاه لما كان نور في السماوات ولا في الأرض."], ["مثل نوره", "في قلب عبده المؤمن."], ["كمشكاة", "كوّة."], ["كوكب درّي", "مضيء إضاءة الدرّ الوهّاج."], ["نور على نور", "نور النار على نور الزيت."], ["يهدي الله لنوره", "للإيمان به والعمل بطاعته من يشاء، لعلمه برغبته وصدق نيته."], ["ويضرب الله الأمثال", "يجعلها للناس من أجل أن يفهموا عنه ويعقلوا ما يدعوهم إليه."], ["في بيوت أذن الله أن تُرفع", "هي المساجد، ورفعها إعلاء شأنها من بناء وطهارة."], ["يوماً تتقلّب فيه القلوب والأبصار", "يوم القيامة."], ["يرزق من يشاء بغير حساب", "بلا عدّ ولا كيل ولا وزن."]], "m": "يخبر تعالى أنه لولاه لما كان في الكون نور ولا هداية، فهو منوّر السماوات والأرض، فكتابه نور ورسوله نور يُهتدى بهما في ظلمات الحياة، فكل نور حسّي أو معنوي الله خالقه وواهبه وهادٍ إليه. مثل نوره في قلب عبده المؤمن كمشكاة، كوّة في جدار، فيها مصباح، المصباح في زجاجة من بلّور، الزجاجة في صفائها كأنها كوكب مضيء كالدرّة، يوقد زيته من شجرة مباركة، زيتونة لا شرقية ولا غربية، بل في وسط البستان تصيبها الشمس كل النهار، فزيتها في غاية الجودة يكاد يشتعل لصفائه ولو لم تمسسه نار، نور النار على نور الزيت. يهدي الله لنوره، الإيمان والإسلام والإحسان، من يشاء ممن علم أنهم يرغبون في الهداية ويطلبونها، ويضرب الأمثال للناس، والله بكل شيء عليم. هذا المصباح في بيوت أمر الله أن تُرفع حساً ومعنى، وهي المساجد، تُطهّر من النجاسات واللغو وكلام الدنيا، ويُذكر فيها اسمه بالأذان والإقامة والصلاة والتسبيح وقراءة القرآن، يسبّح له فيها بالصباح والمساء رجال لا تلهيهم تجارة ولا بيع عن ذكر الله، فقلوبهم ذاكرة غير غافلة، وعن إقام الصلاة وإيتاء الزكاة، يخافون يوم القيامة الذي تتقلّب فيه القلوب والأبصار من شدة الفزع، ليجزيهم الله أحسن ما عملوا، ويزيدهم من فضله، والله يرزق من يشاء بغير حساب.", "h": ["كل خير وكل نور وكل هداية مصدرها الله تعالى، فهو الذي يُطلب منه ذلك.", "استحسان ضرب الأمثال لتقريب المعاني إلى الأذهان والفهوم.", "الإشارة إلى أن ملة الإسلام لا يهودية ولا نصرانية.", "وجوب تعظيم بيوت الله تعالى، المساجد، بتطهيرها ورفع بنيانها وإخلائها إلا من ذكر الله والصلاة وطلب العلم فيها.", "ثناء الله تعالى على من لا تلهيهم تجارة ولا بيع عن ذكر الله وإقام الصلاة وإيتاء الزكاة."], "k": "«رجال لا تلهيهم تجارة ولا بيع عن ذكر الله»… حين ينادي المؤذّن، ما الذي يؤخّرني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 251;
insert into public.tdb_cards(topic, i, body) select 251, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٢ – ٣٤", "q": "وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّـٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ﴿٣٢﴾ وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِيهِمۡ خَيۡرٗاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنٗا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورٞ رَّحِيمٞ ﴿٣٣﴾ وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ ءَايَٰتٖ مُّبَيِّنَٰتٖ وَمَثَلٗا مِّنَ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۡ وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ ﴿٣٤﴾", "w": [["وأنكحوا الأيامى منكم", "زوّجوا من لا زوجة له من رجالكم، ومن لا زوج لها من نسائكم."], ["والصالحين من عبادكم وإمائكم", "زوّجوا القادرين والقادرات على أعباء الزواج من عبيدكم وإمائكم."], ["إن يكونوا فقراء يغنهم الله من فضله", "إن يكن الأيامى فقراء فلا يمنعكم ذلك من تزويجهم، فإن الله يغنيهم."], ["إن الله واسع عليم", "واسع الفضل، عليم بحاجة العبد فيسدّها تكرّماً."], ["وليستعفف", "وليطلب عفّة نفسه بالصبر والصيام."], ["يبتغون الكتاب", "يطلبون المكاتبة من المماليك."], ["إن علمتم فيهم خيراً", "قدرة على السداد والاستقلال عنكم."], ["وآتوهم من مال الله", "أعينوهم بنجم من نجوم المكاتبة من الزكاة وغيرها."], ["على البغاء إن أردن تحصّناً", "على الزنا، إن أردن تعفّفاً وتحفّظاً من الفاحشة."], ["عرض الحياة الدنيا", "المال."], ["مبيّنات", "للأحكام، موضّحة لما يُطلب منكم فعله وتركه."], ["ومثلاً من الذين خلوا من قبلكم", "قصصاً من أخبار الأولين كقصة يوسف ومريم، وهما شبيهتان بحادثة الإفك."], ["وموعظة", "ما يتّعظ به العبد فيسلك سبيل النجاة."]], "m": "ما زال السياق في الأسباب الواقية من الفاحشة: أمر الله جماعة المسلمين أن يزوّجوا الأيامى من رجالهم ونسائهم بالمساعدة والإعانة، حتى لا يبقى في البلد عزب إلا نادراً، والبكر والثيب في ذلك سواء، وأن يزوّجوا القادرين على مؤونة الزواج من مماليكهم، ولا يمنعكم فقرهم، فقد تكفّل الله بغناهم بعد زواجهم، والله واسع الفضل عليم بحاجة المحتاجين. وأمر من لا يجد نكاحاً، لانعدام الزوج أو مؤونة الزواج من مهر ووليمة، أن يعفّ نفسه بالصبر والصيام والصلاة حتى لا يتطلّع إلى الحرام، حتى يغنيه الله من فضله. والمسألة الثالثة: إذا طلب العبد من مالكه أن يكاتبه، وكان قادراً على السداد مستطيعاً أن يستقل بنفسه، فعليه أن يكاتبه ويعينه بإسقاط نجم من نجوم الكتابة. والرابعة: كان لابن أُبيّ جاريتان أسلمتا فأمرهما بالزنا ليكسب بهما، فشكتا إلى رسول الله ﷺ، فنزل: ولا تكرهوا فتياتكم على البغاء إن أردن تعفّفاً لأجل مال قليل يزول بسرعة، ومن يكرههن فإن الله من بعد إكراههن غفور لهن رحيم بهن، إذ المكره لا إثم عليه. ولقد أنزلنا إليكم آيات مبيّنات للشرائع والأحكام، وقصصاً من أخبار الأولين، وموعظة ينتفع بها المتقون.", "h": ["انتداب المسلمين، حاكمين ومحكومين، للمساعدة على تزويج الأيامى من المسلمين.", "وجوب الاستعفاف على من لم يجد نكاحاً، والصبر حتى ييسّر الله أمره.", "عِدة الله للفقير إذا تزوّج بالغنى.", "تعيّن مكاتبة العبد إذا توفّرت فيه شروط المكاتبة.", "حرمة الزنا بالإكراه أو بالاختيار، ومنع ذلك بإقامة الحدود.", "صيغة الكتابة أن يقول السيد للعبد: قد كاتبتك على مال منجّم، أي مقسّط على أقساط تُدفع في آجالها، فإذا وفّيتها فأنت حر.", "بيان فضل سورة النور لما احتوته من أحكام في غاية الأهمية."], "k": "«إن يكونوا فقراء يغنهم الله من فضله»… هل أعين شاباً على الحلال، أم أعسّر عليه طريقه؟"}, {"lbl": "الآيات ٣٥ – ٣٨", "q": "۞ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةٖ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبٞ دُرِّيّٞ يُوقَدُ مِن شَجَرَةٖ مُّبَٰرَكَةٖ زَيۡتُونَةٖ لَّا شَرۡقِيَّةٖ وَلَا غَرۡبِيَّةٖ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارٞۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٣٥﴾ فِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ ﴿٣٦﴾ رِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ ﴿٣٧﴾ لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ ﴿٣٨﴾", "w": [["الله نور السماوات", "منوّرهما، فلولاه لما كان نور في السماوات ولا في الأرض."], ["مثل نوره", "في قلب عبده المؤمن."], ["كمشكاة", "كوّة."], ["كوكب درّي", "مضيء إضاءة الدرّ الوهّاج."], ["نور على نور", "نور النار على نور الزيت."], ["يهدي الله لنوره", "للإيمان به والعمل بطاعته من يشاء، لعلمه برغبته وصدق نيته."], ["ويضرب الله الأمثال", "يجعلها للناس من أجل أن يفهموا عنه ويعقلوا ما يدعوهم إليه."], ["في بيوت أذن الله أن تُرفع", "هي المساجد، ورفعها إعلاء شأنها من بناء وطهارة."], ["يوماً تتقلّب فيه القلوب والأبصار", "يوم القيامة."], ["يرزق من يشاء بغير حساب", "بلا عدّ ولا كيل ولا وزن."]], "m": "يخبر تعالى أنه لولاه لما كان في الكون نور ولا هداية، فهو منوّر السماوات والأرض، فكتابه نور ورسوله نور يُهتدى بهما في ظلمات الحياة، فكل نور حسّي أو معنوي الله خالقه وواهبه وهادٍ إليه. مثل نوره في قلب عبده المؤمن كمشكاة، كوّة في جدار، فيها مصباح، المصباح في زجاجة من بلّور، الزجاجة في صفائها كأنها كوكب مضيء كالدرّة، يوقد زيته من شجرة مباركة، زيتونة لا شرقية ولا غربية، بل في وسط البستان تصيبها الشمس كل النهار، فزيتها في غاية الجودة يكاد يشتعل لصفائه ولو لم تمسسه نار، نور النار على نور الزيت. يهدي الله لنوره، الإيمان والإسلام والإحسان، من يشاء ممن علم أنهم يرغبون في الهداية ويطلبونها، ويضرب الأمثال للناس، والله بكل شيء عليم. هذا المصباح في بيوت أمر الله أن تُرفع حساً ومعنى، وهي المساجد، تُطهّر من النجاسات واللغو وكلام الدنيا، ويُذكر فيها اسمه بالأذان والإقامة والصلاة والتسبيح وقراءة القرآن، يسبّح له فيها بالصباح والمساء رجال لا تلهيهم تجارة ولا بيع عن ذكر الله، فقلوبهم ذاكرة غير غافلة، وعن إقام الصلاة وإيتاء الزكاة، يخافون يوم القيامة الذي تتقلّب فيه القلوب والأبصار من شدة الفزع، ليجزيهم الله أحسن ما عملوا، ويزيدهم من فضله، والله يرزق من يشاء بغير حساب.", "h": ["كل خير وكل نور وكل هداية مصدرها الله تعالى، فهو الذي يُطلب منه ذلك.", "استحسان ضرب الأمثال لتقريب المعاني إلى الأذهان والفهوم.", "الإشارة إلى أن ملة الإسلام لا يهودية ولا نصرانية.", "وجوب تعظيم بيوت الله تعالى، المساجد، بتطهيرها ورفع بنيانها وإخلائها إلا من ذكر الله والصلاة وطلب العلم فيها.", "ثناء الله تعالى على من لا تلهيهم تجارة ولا بيع عن ذكر الله وإقام الصلاة وإيتاء الزكاة."], "k": "«رجال لا تلهيهم تجارة ولا بيع عن ذكر الله»… حين ينادي المؤذّن، ما الذي يؤخّرني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (252, 24, 39, 46, 'سورة النور ٣٩ – ٤٦', '«والذين كفروا أعمالهم كسراب بقيعة»، و«ومن لم يجعل الله له نوراً فما له من نور»، و«ألم تر أن الله يزجي سحاباً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 252) = $j$[{"lbl": "الآيات ٣٩ – ٤١", "q": "وَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۭ بِقِيعَةٖ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـٔٗا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥۗ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ ﴿٣٩﴾ أَوۡ كَظُلُمَٰتٖ فِي بَحۡرٖ لُّجِّيّٖ يَغۡشَىٰهُ مَوۡجٞ مِّن فَوۡقِهِۦ مَوۡجٞ مِّن فَوۡقِهِۦ سَحَابٞۚ ظُلُمَٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَآ أَخۡرَجَ يَدَهُۥ لَمۡ يَكَدۡ يَرَىٰهَاۗ وَمَن لَّمۡ يَجۡعَلِ ٱللَّهُ لَهُۥ نُورٗا فَمَا لَهُۥ مِن نُّورٍ ﴿٤٠﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَـٰٓفَّـٰتٖۖ كُلّٞ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ وَٱللَّهُ عَلِيمُۢ بِمَا يَفۡعَلُونَ ﴿٤١﴾", "w": [["كسراب بقيعة", "السراب: شعاع أبيض يُرى في نصف النهار كأنه ماء، والقيعة: جمع قاع، وهو ما انبسط من الأرض."], ["الظمآن", "العطشان."], ["بحر لجّيّ", "ذو لجج، واللجّة معظم الماء وغزيره، كما هي الحال في المحيطات."], ["يغشاه موج", "يعلوه ويغطيه موج آخر."], ["يسبّح له", "ينزّهه ويقدّسه بألفاظ التسبيح كسبحان الله ونحوه، والصلاة من التسبيح."], ["صافّات", "باسطات أجنحتها."], ["قد علم صلاته", "كل من في السماوات والأرض قد علم الله صلاته وتسبيحه، وكل مسبّح قد علم صلاة نفسه."]], "m": "لما بيّن حال المؤمنين وجزاءهم ذكر حال الكافرين: أعمالهم في خسرانها كسراب بأرض منبسطة يظنّه العطشان ماء، حتى إذا جاءه لم يجده شيئاً، فيا لخيبة ظمآن يقتله العطش جرى وراء سراب، ووجد الله عنده فحاسبه على أعماله وهي في جملتها إجرام وشر فوفّاه حسابه، والله سريع الحساب. ومثل آخر لضلال الكافر وحيرته في حياته، وما يعيش عليه من ظلمة الكفر والعمل السيئ والجهل بربه: كظلمات في بحر عميق، يعلوه موج، من فوقه موج، من فوقه سحاب مظلم، ظلمات بعضها فوق بعض، إذا أخرج يده لم يكد يراها، وهي ناتجة عن إعراضه عن ذكر ربه، ومن لم يجعل الله له نوراً فما له من نور، فالنور بيده فمن لم يطلبه منه حرمه. ألم تر أن الله يسبّح له من في السماوات والأرض بلسان القال والحال، والطير باسطات أجنحتها؟ فإن امتنع المشركون فالخلق كله يسبّح، والكافر وإن لم يسبّح بلسانه فحاله وخلقه وتركيبه تسبّح خالقه، كل قد علم الله صلاته وتسبيحه، والله عليم بما يفعلون، ولله ملك السماوات والأرض وإليه المصير.", "h": ["استحسان ضرب الأمثال لتقريب المعاني البعيدة إلى الأذهان.", "بيان خسران الكافرين في أعمالهم وحياتهم كلها.", "بيان حال الكافرين في هذه الدنيا، وأنهم يعيشون في ظلمات الجهل والكفر والظلم.", "تقرير حقيقة، وهي أن من لم يجعل الله له نوراً في قلبه لن يكون له نور في حياته كلها.", "بيان أن الكون كله يسبّح لله، كقوله تعالى: «وإن من شيء إلا يسبّح بحمده»."], "k": "«ومن لم يجعل الله له نوراً فما له من نور»… أطلب النور منه في دعائي: اللهم اجعل في قلبي نوراً."}, {"lbl": "الآيات ٤٢ – ٤٦", "q": "وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ ﴿٤٢﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُزۡجِي سَحَابٗا ثُمَّ يُؤَلِّفُ بَيۡنَهُۥ ثُمَّ يَجۡعَلُهُۥ رُكَامٗا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٖ فِيهَا مِنۢ بَرَدٖ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصۡرِفُهُۥ عَن مَّن يَشَآءُۖ يَكَادُ سَنَا بَرۡقِهِۦ يَذۡهَبُ بِٱلۡأَبۡصَٰرِ ﴿٤٣﴾ يُقَلِّبُ ٱللَّهُ ٱلَّيۡلَ وَٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ ﴿٤٤﴾ وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٖ مِّن مَّآءٖۖ فَمِنۡهُم مَّن يَمۡشِي عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰ رِجۡلَيۡنِ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰٓ أَرۡبَعٖۚ يَخۡلُقُ ٱللَّهُ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٤٥﴾ لَّقَدۡ أَنزَلۡنَآ ءَايَٰتٖ مُّبَيِّنَٰتٖۚ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٤٦﴾", "w": [["يزجي سحاباً", "يسوقه برفق ويسر."], ["ثم يؤلّف بينه", "يجمع بين أجزائه وقطعه."], ["ثم يجعله ركاماً", "متراكماً بعضه فوق بعض."], ["الودق", "المطر."], ["يخرج من خلاله", "من فرجه وشقوقه."], ["من جبال فيها من برد", "من جبال من برد في السماء، والبرد حجارة بيضاء كالثلج."], ["سنا برقه", "لمعانه."], ["يذهب بالأبصار", "الناظرة إليه."], ["لعبرة", "دلالة على وجود الله وقدرته وعلمه ووجوب توحيده."], ["كل دابة من ماء", "كل حيوان من نطفة."], ["على بطنه", "كالحيّات والهوام."], ["على رجلين", "كالإنسان والطير."], ["على أربع", "كالأنعام والبهائم."], ["إلى صراط مستقيم", "إلى الإسلام."]], "m": "ما زال السياق في عرض مظاهر القدرة والعلم والحكمة الموجبة لعبادة الله وحده: ألم تعلم أن الله يسوق سحاباً برفق، ثم يجمع بين أجزائه، ثم يجعله متراكماً، فترى المطر يخرج من فتوقه؟ وينزّل من السماء من جبال فيها من برد، فيصيب به من يشاء فيهلك زرعه أو ماشيته، ويصرفه عمن يشاء، يكاد لمعان برقه يخطف الأبصار. يقلّب الله الليل والنهار، إذا ظهر هذا اختفى ذاك، إن في ذلك لعظة لأولي البصائر تهديهم إلى الإيمان بالله فيعبدونه ويوحّدونه محبّين معظّمين. والله خلق كل دابة من نطفة، فمنهم من يمشي على بطنه كالحيّات والأسماك، ومنهم من يمشي على رجلين كالإنسان والطير، ومنهم من يمشي على أربع كالأنعام، يخلق الله ما يشاء، إن الله على كل شيء قدير، فأين الأصنام من الخالق العليم الحكيم؟ لقد أنزلنا آيات مبيّنات لهداية العباد، فمن آمن بها وأخذ بما تدعو إليه اهتدى، ومن أعرض ضلّ وشقي، والله يهدي من يشاء ممن رغب في الهداية وطلبها إلى صراط مستقيم، الإسلام.", "h": ["مظاهر قدرة الله وعلمه وحكمته، وهي موجبات الإيمان والتقوى.", "بيان كيفية نزول المطر والبرد.", "مظاهر لطف الله بعباده في صرف البرد عن الزرع والماشية وبعض عباده.", "مظاهر القدرة والعلم في تقليب الليل والنهار على بعضهما بعضاً.", "بيان أصناف المخلوقات في مشيها على الأرض بعد خلقها من ماء، وهو مظهر العلم والقدرة.", "امتنان الله تعالى على العباد بإنزاله الآيات المبيّنات للهدى وطريق السعادة والكمال."], "k": "«يقلّب الله الليل والنهار إن في ذلك لعبرة لأولي الأبصار»… الليلة حين يحلّ الظلام، أتفكّر فيمن قلّبه."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 252;
insert into public.tdb_cards(topic, i, body) select 252, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٩ – ٤١", "q": "وَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۭ بِقِيعَةٖ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـٔٗا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥۗ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ ﴿٣٩﴾ أَوۡ كَظُلُمَٰتٖ فِي بَحۡرٖ لُّجِّيّٖ يَغۡشَىٰهُ مَوۡجٞ مِّن فَوۡقِهِۦ مَوۡجٞ مِّن فَوۡقِهِۦ سَحَابٞۚ ظُلُمَٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَآ أَخۡرَجَ يَدَهُۥ لَمۡ يَكَدۡ يَرَىٰهَاۗ وَمَن لَّمۡ يَجۡعَلِ ٱللَّهُ لَهُۥ نُورٗا فَمَا لَهُۥ مِن نُّورٍ ﴿٤٠﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَـٰٓفَّـٰتٖۖ كُلّٞ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ وَٱللَّهُ عَلِيمُۢ بِمَا يَفۡعَلُونَ ﴿٤١﴾", "w": [["كسراب بقيعة", "السراب: شعاع أبيض يُرى في نصف النهار كأنه ماء، والقيعة: جمع قاع، وهو ما انبسط من الأرض."], ["الظمآن", "العطشان."], ["بحر لجّيّ", "ذو لجج، واللجّة معظم الماء وغزيره، كما هي الحال في المحيطات."], ["يغشاه موج", "يعلوه ويغطيه موج آخر."], ["يسبّح له", "ينزّهه ويقدّسه بألفاظ التسبيح كسبحان الله ونحوه، والصلاة من التسبيح."], ["صافّات", "باسطات أجنحتها."], ["قد علم صلاته", "كل من في السماوات والأرض قد علم الله صلاته وتسبيحه، وكل مسبّح قد علم صلاة نفسه."]], "m": "لما بيّن حال المؤمنين وجزاءهم ذكر حال الكافرين: أعمالهم في خسرانها كسراب بأرض منبسطة يظنّه العطشان ماء، حتى إذا جاءه لم يجده شيئاً، فيا لخيبة ظمآن يقتله العطش جرى وراء سراب، ووجد الله عنده فحاسبه على أعماله وهي في جملتها إجرام وشر فوفّاه حسابه، والله سريع الحساب. ومثل آخر لضلال الكافر وحيرته في حياته، وما يعيش عليه من ظلمة الكفر والعمل السيئ والجهل بربه: كظلمات في بحر عميق، يعلوه موج، من فوقه موج، من فوقه سحاب مظلم، ظلمات بعضها فوق بعض، إذا أخرج يده لم يكد يراها، وهي ناتجة عن إعراضه عن ذكر ربه، ومن لم يجعل الله له نوراً فما له من نور، فالنور بيده فمن لم يطلبه منه حرمه. ألم تر أن الله يسبّح له من في السماوات والأرض بلسان القال والحال، والطير باسطات أجنحتها؟ فإن امتنع المشركون فالخلق كله يسبّح، والكافر وإن لم يسبّح بلسانه فحاله وخلقه وتركيبه تسبّح خالقه، كل قد علم الله صلاته وتسبيحه، والله عليم بما يفعلون، ولله ملك السماوات والأرض وإليه المصير.", "h": ["استحسان ضرب الأمثال لتقريب المعاني البعيدة إلى الأذهان.", "بيان خسران الكافرين في أعمالهم وحياتهم كلها.", "بيان حال الكافرين في هذه الدنيا، وأنهم يعيشون في ظلمات الجهل والكفر والظلم.", "تقرير حقيقة، وهي أن من لم يجعل الله له نوراً في قلبه لن يكون له نور في حياته كلها.", "بيان أن الكون كله يسبّح لله، كقوله تعالى: «وإن من شيء إلا يسبّح بحمده»."], "k": "«ومن لم يجعل الله له نوراً فما له من نور»… أطلب النور منه في دعائي: اللهم اجعل في قلبي نوراً."}, {"lbl": "الآيات ٤٢ – ٤٦", "q": "وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ ﴿٤٢﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُزۡجِي سَحَابٗا ثُمَّ يُؤَلِّفُ بَيۡنَهُۥ ثُمَّ يَجۡعَلُهُۥ رُكَامٗا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٖ فِيهَا مِنۢ بَرَدٖ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصۡرِفُهُۥ عَن مَّن يَشَآءُۖ يَكَادُ سَنَا بَرۡقِهِۦ يَذۡهَبُ بِٱلۡأَبۡصَٰرِ ﴿٤٣﴾ يُقَلِّبُ ٱللَّهُ ٱلَّيۡلَ وَٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ ﴿٤٤﴾ وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٖ مِّن مَّآءٖۖ فَمِنۡهُم مَّن يَمۡشِي عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰ رِجۡلَيۡنِ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰٓ أَرۡبَعٖۚ يَخۡلُقُ ٱللَّهُ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٤٥﴾ لَّقَدۡ أَنزَلۡنَآ ءَايَٰتٖ مُّبَيِّنَٰتٖۚ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٤٦﴾", "w": [["يزجي سحاباً", "يسوقه برفق ويسر."], ["ثم يؤلّف بينه", "يجمع بين أجزائه وقطعه."], ["ثم يجعله ركاماً", "متراكماً بعضه فوق بعض."], ["الودق", "المطر."], ["يخرج من خلاله", "من فرجه وشقوقه."], ["من جبال فيها من برد", "من جبال من برد في السماء، والبرد حجارة بيضاء كالثلج."], ["سنا برقه", "لمعانه."], ["يذهب بالأبصار", "الناظرة إليه."], ["لعبرة", "دلالة على وجود الله وقدرته وعلمه ووجوب توحيده."], ["كل دابة من ماء", "كل حيوان من نطفة."], ["على بطنه", "كالحيّات والهوام."], ["على رجلين", "كالإنسان والطير."], ["على أربع", "كالأنعام والبهائم."], ["إلى صراط مستقيم", "إلى الإسلام."]], "m": "ما زال السياق في عرض مظاهر القدرة والعلم والحكمة الموجبة لعبادة الله وحده: ألم تعلم أن الله يسوق سحاباً برفق، ثم يجمع بين أجزائه، ثم يجعله متراكماً، فترى المطر يخرج من فتوقه؟ وينزّل من السماء من جبال فيها من برد، فيصيب به من يشاء فيهلك زرعه أو ماشيته، ويصرفه عمن يشاء، يكاد لمعان برقه يخطف الأبصار. يقلّب الله الليل والنهار، إذا ظهر هذا اختفى ذاك، إن في ذلك لعظة لأولي البصائر تهديهم إلى الإيمان بالله فيعبدونه ويوحّدونه محبّين معظّمين. والله خلق كل دابة من نطفة، فمنهم من يمشي على بطنه كالحيّات والأسماك، ومنهم من يمشي على رجلين كالإنسان والطير، ومنهم من يمشي على أربع كالأنعام، يخلق الله ما يشاء، إن الله على كل شيء قدير، فأين الأصنام من الخالق العليم الحكيم؟ لقد أنزلنا آيات مبيّنات لهداية العباد، فمن آمن بها وأخذ بما تدعو إليه اهتدى، ومن أعرض ضلّ وشقي، والله يهدي من يشاء ممن رغب في الهداية وطلبها إلى صراط مستقيم، الإسلام.", "h": ["مظاهر قدرة الله وعلمه وحكمته، وهي موجبات الإيمان والتقوى.", "بيان كيفية نزول المطر والبرد.", "مظاهر لطف الله بعباده في صرف البرد عن الزرع والماشية وبعض عباده.", "مظاهر القدرة والعلم في تقليب الليل والنهار على بعضهما بعضاً.", "بيان أصناف المخلوقات في مشيها على الأرض بعد خلقها من ماء، وهو مظهر العلم والقدرة.", "امتنان الله تعالى على العباد بإنزاله الآيات المبيّنات للهدى وطريق السعادة والكمال."], "k": "«يقلّب الله الليل والنهار إن في ذلك لعبرة لأولي الأبصار»… الليلة حين يحلّ الظلام، أتفكّر فيمن قلّبه."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (253, 24, 47, 57, 'سورة النور ٤٧ – ٥٧', '«إنما كان قول المؤمنين إذا دُعوا إلى الله ورسوله… سمعنا وأطعنا»، و«وإن تطيعوه تهتدوا»، و«وعد الله الذين آمنوا منكم… ليستخلفنّهم في الأرض»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 253) = $j$[{"lbl": "الآيات ٤٧ – ٥٢", "q": "وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُم مِّنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَـٰٓئِكَ بِٱلۡمُؤۡمِنِينَ ﴿٤٧﴾ وَإِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِيقٞ مِّنۡهُم مُّعۡرِضُونَ ﴿٤٨﴾ وَإِن يَكُن لَّهُمُ ٱلۡحَقُّ يَأۡتُوٓاْ إِلَيۡهِ مُذۡعِنِينَ ﴿٤٩﴾ أَفِي قُلُوبِهِم مَّرَضٌ أَمِ ٱرۡتَابُوٓاْ أَمۡ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيۡهِمۡ وَرَسُولُهُۥۚ بَلۡ أُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٥٠﴾ إِنَّمَا كَانَ قَوۡلَ ٱلۡمُؤۡمِنِينَ إِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ أَن يَقُولُواْ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٥١﴾ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ ﴿٥٢﴾", "w": [["ويقولون", "المنافقون."], ["آمنا بالله وبالرسول", "صدّقنا بتوحيد الله وبنبوة الرسول محمد ﷺ."], ["ثم يتولّى فريق منهم", "يعرض."], ["إذا فريق منهم معرضون", "عن المجيء إلى الرسول ﷺ."], ["مذعنين", "مسرعين منقادين مطيعين."], ["في قلوبهم مرض", "كفر ونفاق وشرك."], ["أم ارتابوا", "بل شكّوا في نبوة الرسول ﷺ."], ["أن يحيف الله عليهم ورسوله", "في الحكم فيظلموا فيه."], ["إنما كان قول المؤمنين", "هو قولهم: سمعنا وأطعنا."], ["المفلحون", "الفائزون بالنجاة من النار ودخول الجنة."]], "m": "بعد عرض مظاهر القدرة الموجبة للإيمان، اهتدى من شاء الله هدايته، وأعرض من كتب الله شقاوته من المنافقين: ويقولون آمنّا بالله وبالرسول وأطعنا، ثم يعرض فريق منهم بقلوبهم من بعد ذلك، وما أولئك بالمؤمنين. وإذا دُعوا إلى الله ورسوله ليحكم بينهم في قضية من قضايا دنياهم إذا فريق منهم معرضون عن التحاكم إليه، وإن يكن لهم الحق يأتوا إليه منقادين طائعين لعلمهم أنه يقضي بالحق. أفي قلوبهم مرض الكفر والنفاق، أم شكّوا في نبوته، أم يخافون أن يظلمهم الله ورسوله؟ لا، بل أولئك هم الظالمون، يخافون حكم الله العادل لأنه يأخذ منهم ما ليس لهم. إنما كان قول المؤمنين الصادقين إذا دُعوا إلى الله ورسوله ليحكم بينهم أن يقولوا: سمعنا وأطعنا، وأولئك هم المفلحون. ومن يطع الله ورسوله فيما يأمران وينهيان، ويخش الله في السر والعلن، ويتّقه فلا يقصّر في واجب ولا يغشى محرّماً، فأولئك هم الفائزون، الآمنون من العذاب المنعّمون في الجنات.", "h": ["وجوب التحاكم إلى الكتاب والسنة.", "من دُعي إلى الكتاب والسنة فأعرض فهو منافق معلوم النفاق.", "اتخاذ قوانين وضعية للتحاكم إليها دون كتاب الله وسنة رسوله آية الكفر والنفاق.", "فضل طاعة الله ورسوله وتقوى الله عز وجل، وأن أهلها هم الفائزون بالنجاة من النار."], "k": "«سمعنا وأطعنا»… حكم شرعي يخالف هواي؛ هل أقولها فيه كما أقولها فيما يوافقني؟"}, {"lbl": "الآيات ٥٣ – ٥٥", "q": "۞وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُنَّۖ قُل لَّا تُقۡسِمُواْۖ طَاعَةٞ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿٥٣﴾ قُلۡ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿٥٤﴾ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ لَهُمۡ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنٗاۚ يَعۡبُدُونَنِي لَا يُشۡرِكُونَ بِي شَيۡـٔٗاۚ وَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿٥٥﴾", "w": [["وأقسموا بالله جهد أيمانهم", "حلفوا بالله بالغين غاية الجهد في حلفهم."], ["لئن أمرتهم", "بالخروج إلى الجهاد."], ["طاعة معروفة", "طاعة معروفة للنبي فيما يأمركم وينهاكم خير من إقسامكم."], ["فإن تولّوا", "فإن تتولّوا، أي تعرضوا عن الطاعة."], ["عليه ما حُمّل", "من إبلاغ الرسالة وبيانها بالقول والعمل."], ["وعليكم ما حُمّلتم", "من وجوب قبول الشرع والعمل به عقيدة وعبادة وحكماً."], ["وإن تطيعوه تهتدوا", "إن تطيعوا الرسول في أمره ونهيه وإرشاده تهتدوا إلى كل خير."], ["ليستخلفنّهم", "يجعلهم خلفاء لغيرهم فيها فيسودون فيها ويحكمون."], ["وليمكّننّ لهم دينهم", "بأن يظهر الإسلام على سائر الأديان ويحفظه من الزوال."]], "m": "ما زال السياق في أحوال المنافقين: أقسموا للرسول ﷺ مبالغين: لئن أمرتنا بالخروج إلى الجهاد لنخرجنّ معك، فأمره أن يقول لهم: لا تقسموا، فما هناك حاجة إلى الحلف، إنما هي طاعة معروفة تغني عن الأيمان، إن الله خبير بما تعملون في الخفاء. قل: أطيعوا الله وأطيعوا الرسول، فإن أعرضتم فإنما عليه ما حُمّل من البلاغ والبيان، وعليكم ما حُمّلتم من وجوب الانقياد والطاعة، وإن تطيعوه تهتدوا، جملة عظيمة: من أطاع الرسول لن يضل أبداً ولن يشقى، وما على الرسول إلا البلاغ المبين، لا هداية القلوب. وعد الله الذين آمنوا منكم وعملوا الصالحات، فأقاموا الصلاة وآتوا الزكاة وأمروا بالمعروف ونهوا عن المنكر، ليستخلفنّهم في الأرض حاكمين سائدين كما استخلف بني إسرائيل في أرض القدس، وليمكّننّ لهم دينهم الإسلام فيظهره على الدين كله، وليبدّلنّهم من بعد خوفهم أمناً، إذ نزلت والمسلمون بالمدينة لا يقدر أحدهم أن ينام وسيفه بعيد عنه من شدة الخوف، وقد أنجز الله وعده. يعبدونني لا يشركون بي شيئاً، ثناء عليهم وتعليل لما أعطاهم، ومن كفر بعد ذلك الإنعام فأولئك هم الفاسقون.", "h": ["مشروعية الإقسام بالله تعالى، وحرمة الحلف بغيره تعالى.", "طاعة رسول الله ﷺ موجبة للهداية لما فيه سعادة الدارين، ومعصيته موجبة للضلال.", "صدق وعد الله تعالى لأهل الإيمان وصالح الأعمال من أصحاب رسول الله ﷺ.", "وجوب الشكر على النعم بعبادة الله تعالى وحده بما شرع من أنواع العبادات.", "الوعيد الشديد لمن أنعم الله عليه بنعمة أمن ورخاء وسيادة وكرامة فكفر تلك النعم ولم يشكرها فعرّضها للزوال."], "k": "«وإن تطيعوه تهتدوا»… سنّة تركتها اليوم؛ أعود إليها لأني أطلب الهداية."}, {"lbl": "الآيتان ٥٦ – ٥٧", "q": "وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٥٦﴾ لَا تَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِۚ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِيرُ ﴿٥٧﴾", "w": [["وأقيموا الصلاة", "أدّوها أداءً كاملاً مراعين شروطها وأركانها وواجباتها وسننها حتى تثمر الزكاة والطهر في نفوسكم."], ["وآتوا الزكاة", "المفروضة من المال الصامت كالذهب والفضة والحرث، والناطق كالأنعام."], ["وأطيعوا الرسول", "محمداً ﷺ في أمره ونهيه والأخذ بإرشاده وتوجيهه."], ["لعلكم ترحمون", "رجاء أن يرحمكم ربكم في دنياكم وآخرتكم."], ["معجزين في الأرض", "معجزين الله بحيث لا يدركهم ولا ينزل بهم نقمته."], ["ولبئس المصير", "النار."]], "m": "يأمر تعالى عباده المؤمنين من أصحاب الرسول ﷺ، والأمر عام بعدهم، بإقام الصلاة وإيتاء الزكاة وطاعة الرسول في أمره ونهيه وإرشاده، رجاء أن يُرحموا في الدارين فلا يُعذّبوا فيهما. ثم نهى رسوله أن يظن أن الذين كفروا مهما كانت قوتهم سيفوتون الله ويهربون مما أراد بهم من خزي وعذاب، بل سيخزيهم ويذلّهم، وقد فعل، ومأواهم يوم القيامة النار، ولبئس المصير.", "h": ["وجوب إقام الصلاة وإيتاء الزكاة وطاعة الرسول ﷺ للحصول على رحمة الله تعالى في الدنيا والآخرة: في الدنيا بالنصر والتمكين والأمن والسيادة، وفي الآخرة بدخول الجنة.", "تقرير عجز الكافرين، وأنهم لن يفوتوا الله تعالى مهما كانت قوتهم.", "بيان مصير أهل الكفر، وأنه النار والعياذ بالله تعالى."], "k": "«وأقيموا الصلاة وآتوا الزكاة وأطيعوا الرسول لعلكم ترحمون»… ثلاثة أبواب للرحمة؛ أيها يحتاج مني عناية الآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 253;
insert into public.tdb_cards(topic, i, body) select 253, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٧ – ٥٢", "q": "وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُم مِّنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَـٰٓئِكَ بِٱلۡمُؤۡمِنِينَ ﴿٤٧﴾ وَإِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِيقٞ مِّنۡهُم مُّعۡرِضُونَ ﴿٤٨﴾ وَإِن يَكُن لَّهُمُ ٱلۡحَقُّ يَأۡتُوٓاْ إِلَيۡهِ مُذۡعِنِينَ ﴿٤٩﴾ أَفِي قُلُوبِهِم مَّرَضٌ أَمِ ٱرۡتَابُوٓاْ أَمۡ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيۡهِمۡ وَرَسُولُهُۥۚ بَلۡ أُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٥٠﴾ إِنَّمَا كَانَ قَوۡلَ ٱلۡمُؤۡمِنِينَ إِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ أَن يَقُولُواْ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٥١﴾ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ ﴿٥٢﴾", "w": [["ويقولون", "المنافقون."], ["آمنا بالله وبالرسول", "صدّقنا بتوحيد الله وبنبوة الرسول محمد ﷺ."], ["ثم يتولّى فريق منهم", "يعرض."], ["إذا فريق منهم معرضون", "عن المجيء إلى الرسول ﷺ."], ["مذعنين", "مسرعين منقادين مطيعين."], ["في قلوبهم مرض", "كفر ونفاق وشرك."], ["أم ارتابوا", "بل شكّوا في نبوة الرسول ﷺ."], ["أن يحيف الله عليهم ورسوله", "في الحكم فيظلموا فيه."], ["إنما كان قول المؤمنين", "هو قولهم: سمعنا وأطعنا."], ["المفلحون", "الفائزون بالنجاة من النار ودخول الجنة."]], "m": "بعد عرض مظاهر القدرة الموجبة للإيمان، اهتدى من شاء الله هدايته، وأعرض من كتب الله شقاوته من المنافقين: ويقولون آمنّا بالله وبالرسول وأطعنا، ثم يعرض فريق منهم بقلوبهم من بعد ذلك، وما أولئك بالمؤمنين. وإذا دُعوا إلى الله ورسوله ليحكم بينهم في قضية من قضايا دنياهم إذا فريق منهم معرضون عن التحاكم إليه، وإن يكن لهم الحق يأتوا إليه منقادين طائعين لعلمهم أنه يقضي بالحق. أفي قلوبهم مرض الكفر والنفاق، أم شكّوا في نبوته، أم يخافون أن يظلمهم الله ورسوله؟ لا، بل أولئك هم الظالمون، يخافون حكم الله العادل لأنه يأخذ منهم ما ليس لهم. إنما كان قول المؤمنين الصادقين إذا دُعوا إلى الله ورسوله ليحكم بينهم أن يقولوا: سمعنا وأطعنا، وأولئك هم المفلحون. ومن يطع الله ورسوله فيما يأمران وينهيان، ويخش الله في السر والعلن، ويتّقه فلا يقصّر في واجب ولا يغشى محرّماً، فأولئك هم الفائزون، الآمنون من العذاب المنعّمون في الجنات.", "h": ["وجوب التحاكم إلى الكتاب والسنة.", "من دُعي إلى الكتاب والسنة فأعرض فهو منافق معلوم النفاق.", "اتخاذ قوانين وضعية للتحاكم إليها دون كتاب الله وسنة رسوله آية الكفر والنفاق.", "فضل طاعة الله ورسوله وتقوى الله عز وجل، وأن أهلها هم الفائزون بالنجاة من النار."], "k": "«سمعنا وأطعنا»… حكم شرعي يخالف هواي؛ هل أقولها فيه كما أقولها فيما يوافقني؟"}, {"lbl": "الآيات ٥٣ – ٥٥", "q": "۞وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُنَّۖ قُل لَّا تُقۡسِمُواْۖ طَاعَةٞ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿٥٣﴾ قُلۡ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿٥٤﴾ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ لَهُمۡ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنٗاۚ يَعۡبُدُونَنِي لَا يُشۡرِكُونَ بِي شَيۡـٔٗاۚ وَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿٥٥﴾", "w": [["وأقسموا بالله جهد أيمانهم", "حلفوا بالله بالغين غاية الجهد في حلفهم."], ["لئن أمرتهم", "بالخروج إلى الجهاد."], ["طاعة معروفة", "طاعة معروفة للنبي فيما يأمركم وينهاكم خير من إقسامكم."], ["فإن تولّوا", "فإن تتولّوا، أي تعرضوا عن الطاعة."], ["عليه ما حُمّل", "من إبلاغ الرسالة وبيانها بالقول والعمل."], ["وعليكم ما حُمّلتم", "من وجوب قبول الشرع والعمل به عقيدة وعبادة وحكماً."], ["وإن تطيعوه تهتدوا", "إن تطيعوا الرسول في أمره ونهيه وإرشاده تهتدوا إلى كل خير."], ["ليستخلفنّهم", "يجعلهم خلفاء لغيرهم فيها فيسودون فيها ويحكمون."], ["وليمكّننّ لهم دينهم", "بأن يظهر الإسلام على سائر الأديان ويحفظه من الزوال."]], "m": "ما زال السياق في أحوال المنافقين: أقسموا للرسول ﷺ مبالغين: لئن أمرتنا بالخروج إلى الجهاد لنخرجنّ معك، فأمره أن يقول لهم: لا تقسموا، فما هناك حاجة إلى الحلف، إنما هي طاعة معروفة تغني عن الأيمان، إن الله خبير بما تعملون في الخفاء. قل: أطيعوا الله وأطيعوا الرسول، فإن أعرضتم فإنما عليه ما حُمّل من البلاغ والبيان، وعليكم ما حُمّلتم من وجوب الانقياد والطاعة، وإن تطيعوه تهتدوا، جملة عظيمة: من أطاع الرسول لن يضل أبداً ولن يشقى، وما على الرسول إلا البلاغ المبين، لا هداية القلوب. وعد الله الذين آمنوا منكم وعملوا الصالحات، فأقاموا الصلاة وآتوا الزكاة وأمروا بالمعروف ونهوا عن المنكر، ليستخلفنّهم في الأرض حاكمين سائدين كما استخلف بني إسرائيل في أرض القدس، وليمكّننّ لهم دينهم الإسلام فيظهره على الدين كله، وليبدّلنّهم من بعد خوفهم أمناً، إذ نزلت والمسلمون بالمدينة لا يقدر أحدهم أن ينام وسيفه بعيد عنه من شدة الخوف، وقد أنجز الله وعده. يعبدونني لا يشركون بي شيئاً، ثناء عليهم وتعليل لما أعطاهم، ومن كفر بعد ذلك الإنعام فأولئك هم الفاسقون.", "h": ["مشروعية الإقسام بالله تعالى، وحرمة الحلف بغيره تعالى.", "طاعة رسول الله ﷺ موجبة للهداية لما فيه سعادة الدارين، ومعصيته موجبة للضلال.", "صدق وعد الله تعالى لأهل الإيمان وصالح الأعمال من أصحاب رسول الله ﷺ.", "وجوب الشكر على النعم بعبادة الله تعالى وحده بما شرع من أنواع العبادات.", "الوعيد الشديد لمن أنعم الله عليه بنعمة أمن ورخاء وسيادة وكرامة فكفر تلك النعم ولم يشكرها فعرّضها للزوال."], "k": "«وإن تطيعوه تهتدوا»… سنّة تركتها اليوم؛ أعود إليها لأني أطلب الهداية."}, {"lbl": "الآيتان ٥٦ – ٥٧", "q": "وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٥٦﴾ لَا تَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِۚ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِيرُ ﴿٥٧﴾", "w": [["وأقيموا الصلاة", "أدّوها أداءً كاملاً مراعين شروطها وأركانها وواجباتها وسننها حتى تثمر الزكاة والطهر في نفوسكم."], ["وآتوا الزكاة", "المفروضة من المال الصامت كالذهب والفضة والحرث، والناطق كالأنعام."], ["وأطيعوا الرسول", "محمداً ﷺ في أمره ونهيه والأخذ بإرشاده وتوجيهه."], ["لعلكم ترحمون", "رجاء أن يرحمكم ربكم في دنياكم وآخرتكم."], ["معجزين في الأرض", "معجزين الله بحيث لا يدركهم ولا ينزل بهم نقمته."], ["ولبئس المصير", "النار."]], "m": "يأمر تعالى عباده المؤمنين من أصحاب الرسول ﷺ، والأمر عام بعدهم، بإقام الصلاة وإيتاء الزكاة وطاعة الرسول في أمره ونهيه وإرشاده، رجاء أن يُرحموا في الدارين فلا يُعذّبوا فيهما. ثم نهى رسوله أن يظن أن الذين كفروا مهما كانت قوتهم سيفوتون الله ويهربون مما أراد بهم من خزي وعذاب، بل سيخزيهم ويذلّهم، وقد فعل، ومأواهم يوم القيامة النار، ولبئس المصير.", "h": ["وجوب إقام الصلاة وإيتاء الزكاة وطاعة الرسول ﷺ للحصول على رحمة الله تعالى في الدنيا والآخرة: في الدنيا بالنصر والتمكين والأمن والسيادة، وفي الآخرة بدخول الجنة.", "تقرير عجز الكافرين، وأنهم لن يفوتوا الله تعالى مهما كانت قوتهم.", "بيان مصير أهل الكفر، وأنه النار والعياذ بالله تعالى."], "k": "«وأقيموا الصلاة وآتوا الزكاة وأطيعوا الرسول لعلكم ترحمون»… ثلاثة أبواب للرحمة؛ أيها يحتاج مني عناية الآن؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (254, 24, 58, 64, 'سورة النور ٥٨ – ٦٤', 'استئذان الأطفال والخدم في العورات الثلاث، و«فإذا دخلتم بيوتاً فسلّموا على أنفسكم»، و«لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 254) = $j$[{"lbl": "الآيات ٥٨ – ٦٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِيَسۡتَـٔۡذِنكُمُ ٱلَّذِينَ مَلَكَتۡ أَيۡمَٰنُكُمۡ وَٱلَّذِينَ لَمۡ يَبۡلُغُواْ ٱلۡحُلُمَ مِنكُمۡ ثَلَٰثَ مَرَّـٰتٖۚ مِّن قَبۡلِ صَلَوٰةِ ٱلۡفَجۡرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعۡدِ صَلَوٰةِ ٱلۡعِشَآءِۚ ثَلَٰثُ عَوۡرَٰتٖ لَّكُمۡۚ لَيۡسَ عَلَيۡكُمۡ وَلَا عَلَيۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّـٰفُونَ عَلَيۡكُم بَعۡضُكُمۡ عَلَىٰ بَعۡضٖۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٥٨﴾ وَإِذَا بَلَغَ ٱلۡأَطۡفَٰلُ مِنكُمُ ٱلۡحُلُمَ فَلۡيَسۡتَـٔۡذِنُواْ كَمَا ٱسۡتَـٔۡذَنَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٥٩﴾ وَٱلۡقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّـٰتِي لَا يَرۡجُونَ نِكَاحٗا فَلَيۡسَ عَلَيۡهِنَّ جُنَاحٌ أَن يَضَعۡنَ ثِيَابَهُنَّ غَيۡرَ مُتَبَرِّجَٰتِۭ بِزِينَةٖۖ وَأَن يَسۡتَعۡفِفۡنَ خَيۡرٞ لَّهُنَّۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ﴿٦٠﴾", "w": [["ليستأذنكم", "ليطلب الإذن منكم في الدخول عليكم."], ["ملكت أيمانكم", "من عبيد وإماء."], ["لم يبلغوا الحلم منكم", "سن التكليف، وهو وقت الاحتلام، خمس عشرة سنة فما فوق."], ["تضعون ثيابكم", "وقت القيلولة للاستراحة والنوم."], ["ثلاث عورات لكم", "العورة ما يُستحيا من كشفه، وهذه الأوقات يتكشّف فيها الإنسان في فراشه."], ["بعدهن", "بعد الأوقات الثلاثة المذكورة."], ["طوّافون عليكم", "للخدمة."], ["فليستأذنوا", "في جميع الأوقات لأنهم أصبحوا رجالاً مكلّفين."], ["والقواعد من النساء", "اللاتي قعدن عن الحيض والولادة لكبر سنّهن."], ["أن يضعن ثيابهن", "كالجلباب والعباءة والقناع والخمار."], ["غير متبرّجات بزينة", "غير مظهرات زينة خفية كقلادة وسوار وخلخال."], ["وأن يستعففن", "بألا يضعن ثيابهن، خير لهن من الأخذ بالرخصة."]], "m": "روي أن النبي ﷺ بعث غلاماً من الأنصار إلى عمر بن الخطاب وقت الظهيرة، فوجده نائماً، فدقّ الباب ودخل، فاستيقظ عمر وانكشف منه شيء، فقال: وددت أن الله نهى أبناءنا ونساءنا وخدمنا أن يدخلوا علينا في هذه الساعة إلا بإذن، فانطلق إلى رسول الله ﷺ فوجد الآية قد نزلت، فخرّ ساجداً شكراً. يا أيها الذين آمنوا، في كل عصورهم وديارهم: علّموا خدمكم وأطفالكم الذين لم يبلغوا الحلم الاستئذان عليكم ثلاث مرات: من قبل صلاة الفجر وهي ساعات النوم، وحين تضعون ثيابكم من الظهيرة وهي القيلولة، ومن بعد صلاة العشاء وهي بداية نوم الليل، ثلاث عورات لكم، ليس عليكم ولا عليهم إثم بعدهن، لأنهم يدخلون ويخرجون للخدمة ولا غنى عنهم، كذلك يبيّن الله لكم الآيات، والله عليم حكيم. وإذا بلغ الأطفال الحلم، بالاحتلام أو بلوغ خمس عشرة سنة، فليستأذنوا في كل الأوقات كما يستأذن الرجال. والقواعد من النساء اللاتي لا يرجون نكاحاً لكبر سنّهن، ليس عليهن إثم أن يضعن خمرهن من فوق رءوسهن أو عباءاتهن، غير مظهرات زينة كخضاب اليدين والأساور والخلاخل، ومن لازمت خمارها ولم تظهر للأجانب كاشفة وجهها ومحاسنها فهو خير لها حالاً ومآلاً، والله سميع عليم.", "h": ["وجوب تعليم الآباء والسادة الأطفال والخدم الاستئذان عليهم في الأوقات الثلاثة المذكورة، والمعبّر عنها بالعورات.", "وجوب استئذان الأولاد إذا احتلموا على من يريدون الدخول عليه في بيته، لأنهم أصبحوا رجالاً مكلّفين.", "بيان رخصة كشف الوجه لمن بلغت سناً لا تحيض فيها ولا تلد للرجال الأجانب، ولو أبقت على سترها واحتجابها لكان خيراً لها، كما قال تعالى: «وأن يستعففن خير لهن»."], "k": "«ثلاث عورات لكم»… هل علّمت أبنائي أدب الاستئذان كما علّمه القرآن؟"}, {"lbl": "الآية ٦١", "q": "لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞ وَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّـٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتٗاۚ فَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ ﴿٦١﴾", "w": [["حرج", "الضيق، والمراد به هنا الإثم، أي لا إثم على المذكورين في مؤاكلة الأصحاء."], ["أو ما ملكتم مفاتحه", "ما هو تحت تصرّفكم بالأصالة أو بالوكالة كوكالة على بستان أو بيت."], ["أو صديقكم", "من صدقكم الودّ وصدقتموه."], ["جميعاً أو أشتاتاً", "مجتمعين على الطعام أو متفرّقين."], ["من عند الله", "لأنه هو الذي شرعها وأمر بها، وما كان من عند الله فهو خير."], ["طيبة", "تطيب بها نفس المسلّم عليه."]], "m": "ما زال السياق في هداية المؤمنين: رفع الله عنهم حرجاً كانوا قد شعروا به، إذ رأوا أن الأكل مع ذوي العاهات، العميان والعرجان والمرضى، قد يترتّب عليه أن يأكلوا ما لا يحل لهم لأن هؤلاء لا يأكلون كما يأكل الأصحاء، وتحرّج أصحاب العاهات من مؤاكلة الأصحاء خوفاً أن يتقذّروهم، فرفع الحرج عن الجميع، وأذن في الأكل من بيوتكم أو بيوت آبائكم وأمهاتكم وإخوانكم وأخواتكم وأعمامكم وعمّاتكم وأخوالكم وخالاتكم، أو ما ملكتم مفاتحه بوكالة ونحوها، أو صديقكم الصادق المودّة، ما دام الرضا حاصلاً. ورفع حرجاً آخر: منهم من كان يتحرّج أن يأكل وحده، ومنهم من يتحرّج من الأكل الجماعي خشية أن يؤذي غيره، فقال: ليس عليكم جناح أن تأكلوا مجتمعين أو متفرّقين. فإذا دخلتم بيوتاً، بيوتكم أو بيوت غيركم، فسلّموا على أهلها: السلام عليكم، وإن كان البيت خالياً أو مسجداً فقولوا: السلام علينا وعلى عباد الله الصالحين، تحية من عند الله مباركة طيبة، كذلك يبيّن الله لكم الآيات لعلكم تعقلون.", "h": ["الإذن العام في الأكل مع ذوي العاهات بلا تحرّج من الفريقين.", "الإذن في الأكل من بيوت من ذُكر في الآية من الأقارب والأصدقاء.", "جواز الأكل الجماعي والانفرادي بلا تحرّج.", "مشروعية التحية عند الدخول على البيوت، وأن فيها خيراً وفضلاً."], "k": "«فسلّموا على أنفسكم تحية من عند الله مباركة طيبة»… حين أدخل بيتي الليلة، أبدأ بالسلام."}, {"lbl": "الآيات ٦٢ – ٦٤", "q": "إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ عَلَىٰٓ أَمۡرٖ جَامِعٖ لَّمۡ يَذۡهَبُواْ حَتَّىٰ يَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ أُوْلَـٰٓئِكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ فَإِذَا ٱسۡتَـٔۡذَنُوكَ لِبَعۡضِ شَأۡنِهِمۡ فَأۡذَن لِّمَن شِئۡتَ مِنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٦٢﴾ لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمۡ لِوَاذٗاۚ فَلۡيَحۡذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنۡ أَمۡرِهِۦٓ أَن تُصِيبَهُمۡ فِتۡنَةٌ أَوۡ يُصِيبَهُمۡ عَذَابٌ أَلِيمٌ ﴿٦٣﴾ أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قَدۡ يَعۡلَمُ مَآ أَنتُمۡ عَلَيۡهِ وَيَوۡمَ يُرۡجَعُونَ إِلَيۡهِ فَيُنَبِّئُهُم بِمَا عَمِلُواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ ﴿٦٤﴾", "w": [["أمر جامع", "كخطبة الجمعة ونحوها مما يجب حضوره كاجتماع لأمر هام."], ["يستأذنوه", "يطلبوا منه ﷺ الإذن."], ["لبعض شأنهم", "لبعض أمورهم الخاصة بهم."], ["دعاء الرسول", "نداءه، فلا يُنادى: يا محمد، ولكن: يا نبي الله، يا رسول الله."], ["كدعاء بعضكم بعضاً", "كما ينادي بعضكم بعضاً: يا عمر، يا سعيد."], ["يتسلّلون منكم لواذاً", "ينسلّون واحداً بعد واحد، يستر بعضهم بعضاً حتى يخرجوا خفية."], ["أن تصيبهم فتنة", "زيغ في قلوبهم فيكفروا."], ["قد يعلم ما أنتم عليه", "من الإيمان والنفاق، وإرادة الخير أو الشر."]], "m": "يخبر تعالى أن المؤمنين الكاملين في إيمانهم هم الذين آمنوا بالله ورسوله، وإذا كانوا معه على أمر جامع يتطلّب حضورهم كالجمعة واجتماعات الحرب لم يذهبوا حتى يستأذنوه، إن الذين يستأذنونك أولئك الذين يؤمنون بالله ورسوله، ومقابله أن الذين يخرجون بدون إذن هم المنافقون، فإذا استأذنوك لبعض شأنهم فأذن لمن شئت ممن لا أهمية لحضوره، واستغفر لهم الله لما قد يكون من غير عذر شرعي، إن الله غفور رحيم. لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضاً، ويحتمل أموراً: أن يحذروا إغضابه فإن دعا عليهم هلكوا لأن دعاءه لا يُردّ، وألا ينادوه باسمه بل: يا نبي الله، يا رسول الله، وألا يغلظوا له في العبارة إكباراً وتعظيماً. قد يعلم الله المنافقين الذين يتسلّلون واحداً بعد آخر بلا إذن، يستر بعضهم بعضاً، فليحذر الذين يخالفون أمره، وهو عام إلى يوم القيامة، أن تصيبهم فتنة زيغ في قلوبهم فيموتوا كافرين، أو يصيبهم عذاب أليم. ألا إن لله ما في السماوات والأرض، قد يعلم ما أنتم عليه، ويوم يُرجعون إليه فينبّئهم بما عملوا، والله بكل شيء عليم.", "h": ["وجوب الاستئذان من إمام المسلمين إذا كان الأمر جامعاً، وللإمام أن يأذن لمن شاء ويترك من يشاء حسب المصلحة العامة.", "وجوب تعظيم رسول الله ﷺ، وحرمة إساءة الأدب معه حياً وميتاً.", "وجوب طاعة رسول الله ﷺ، وحرمة مخالفة أمره ونهيه.", "المتجرّئ على الاستهانة بسنة الرسول ﷺ يُخشى عليه أن يموت على سوء الخاتمة، والعياذ بالله."], "k": "«فليحذر الذين يخالفون عن أمره»… سنّة أستهين بها؛ أحذر أن يكون ذلك زيغاً في القلب."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 254;
insert into public.tdb_cards(topic, i, body) select 254, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٨ – ٦٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِيَسۡتَـٔۡذِنكُمُ ٱلَّذِينَ مَلَكَتۡ أَيۡمَٰنُكُمۡ وَٱلَّذِينَ لَمۡ يَبۡلُغُواْ ٱلۡحُلُمَ مِنكُمۡ ثَلَٰثَ مَرَّـٰتٖۚ مِّن قَبۡلِ صَلَوٰةِ ٱلۡفَجۡرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعۡدِ صَلَوٰةِ ٱلۡعِشَآءِۚ ثَلَٰثُ عَوۡرَٰتٖ لَّكُمۡۚ لَيۡسَ عَلَيۡكُمۡ وَلَا عَلَيۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّـٰفُونَ عَلَيۡكُم بَعۡضُكُمۡ عَلَىٰ بَعۡضٖۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٥٨﴾ وَإِذَا بَلَغَ ٱلۡأَطۡفَٰلُ مِنكُمُ ٱلۡحُلُمَ فَلۡيَسۡتَـٔۡذِنُواْ كَمَا ٱسۡتَـٔۡذَنَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٥٩﴾ وَٱلۡقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّـٰتِي لَا يَرۡجُونَ نِكَاحٗا فَلَيۡسَ عَلَيۡهِنَّ جُنَاحٌ أَن يَضَعۡنَ ثِيَابَهُنَّ غَيۡرَ مُتَبَرِّجَٰتِۭ بِزِينَةٖۖ وَأَن يَسۡتَعۡفِفۡنَ خَيۡرٞ لَّهُنَّۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ﴿٦٠﴾", "w": [["ليستأذنكم", "ليطلب الإذن منكم في الدخول عليكم."], ["ملكت أيمانكم", "من عبيد وإماء."], ["لم يبلغوا الحلم منكم", "سن التكليف، وهو وقت الاحتلام، خمس عشرة سنة فما فوق."], ["تضعون ثيابكم", "وقت القيلولة للاستراحة والنوم."], ["ثلاث عورات لكم", "العورة ما يُستحيا من كشفه، وهذه الأوقات يتكشّف فيها الإنسان في فراشه."], ["بعدهن", "بعد الأوقات الثلاثة المذكورة."], ["طوّافون عليكم", "للخدمة."], ["فليستأذنوا", "في جميع الأوقات لأنهم أصبحوا رجالاً مكلّفين."], ["والقواعد من النساء", "اللاتي قعدن عن الحيض والولادة لكبر سنّهن."], ["أن يضعن ثيابهن", "كالجلباب والعباءة والقناع والخمار."], ["غير متبرّجات بزينة", "غير مظهرات زينة خفية كقلادة وسوار وخلخال."], ["وأن يستعففن", "بألا يضعن ثيابهن، خير لهن من الأخذ بالرخصة."]], "m": "روي أن النبي ﷺ بعث غلاماً من الأنصار إلى عمر بن الخطاب وقت الظهيرة، فوجده نائماً، فدقّ الباب ودخل، فاستيقظ عمر وانكشف منه شيء، فقال: وددت أن الله نهى أبناءنا ونساءنا وخدمنا أن يدخلوا علينا في هذه الساعة إلا بإذن، فانطلق إلى رسول الله ﷺ فوجد الآية قد نزلت، فخرّ ساجداً شكراً. يا أيها الذين آمنوا، في كل عصورهم وديارهم: علّموا خدمكم وأطفالكم الذين لم يبلغوا الحلم الاستئذان عليكم ثلاث مرات: من قبل صلاة الفجر وهي ساعات النوم، وحين تضعون ثيابكم من الظهيرة وهي القيلولة، ومن بعد صلاة العشاء وهي بداية نوم الليل، ثلاث عورات لكم، ليس عليكم ولا عليهم إثم بعدهن، لأنهم يدخلون ويخرجون للخدمة ولا غنى عنهم، كذلك يبيّن الله لكم الآيات، والله عليم حكيم. وإذا بلغ الأطفال الحلم، بالاحتلام أو بلوغ خمس عشرة سنة، فليستأذنوا في كل الأوقات كما يستأذن الرجال. والقواعد من النساء اللاتي لا يرجون نكاحاً لكبر سنّهن، ليس عليهن إثم أن يضعن خمرهن من فوق رءوسهن أو عباءاتهن، غير مظهرات زينة كخضاب اليدين والأساور والخلاخل، ومن لازمت خمارها ولم تظهر للأجانب كاشفة وجهها ومحاسنها فهو خير لها حالاً ومآلاً، والله سميع عليم.", "h": ["وجوب تعليم الآباء والسادة الأطفال والخدم الاستئذان عليهم في الأوقات الثلاثة المذكورة، والمعبّر عنها بالعورات.", "وجوب استئذان الأولاد إذا احتلموا على من يريدون الدخول عليه في بيته، لأنهم أصبحوا رجالاً مكلّفين.", "بيان رخصة كشف الوجه لمن بلغت سناً لا تحيض فيها ولا تلد للرجال الأجانب، ولو أبقت على سترها واحتجابها لكان خيراً لها، كما قال تعالى: «وأن يستعففن خير لهن»."], "k": "«ثلاث عورات لكم»… هل علّمت أبنائي أدب الاستئذان كما علّمه القرآن؟"}, {"lbl": "الآية ٦١", "q": "لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞ وَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّـٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتٗاۚ فَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ ﴿٦١﴾", "w": [["حرج", "الضيق، والمراد به هنا الإثم، أي لا إثم على المذكورين في مؤاكلة الأصحاء."], ["أو ما ملكتم مفاتحه", "ما هو تحت تصرّفكم بالأصالة أو بالوكالة كوكالة على بستان أو بيت."], ["أو صديقكم", "من صدقكم الودّ وصدقتموه."], ["جميعاً أو أشتاتاً", "مجتمعين على الطعام أو متفرّقين."], ["من عند الله", "لأنه هو الذي شرعها وأمر بها، وما كان من عند الله فهو خير."], ["طيبة", "تطيب بها نفس المسلّم عليه."]], "m": "ما زال السياق في هداية المؤمنين: رفع الله عنهم حرجاً كانوا قد شعروا به، إذ رأوا أن الأكل مع ذوي العاهات، العميان والعرجان والمرضى، قد يترتّب عليه أن يأكلوا ما لا يحل لهم لأن هؤلاء لا يأكلون كما يأكل الأصحاء، وتحرّج أصحاب العاهات من مؤاكلة الأصحاء خوفاً أن يتقذّروهم، فرفع الحرج عن الجميع، وأذن في الأكل من بيوتكم أو بيوت آبائكم وأمهاتكم وإخوانكم وأخواتكم وأعمامكم وعمّاتكم وأخوالكم وخالاتكم، أو ما ملكتم مفاتحه بوكالة ونحوها، أو صديقكم الصادق المودّة، ما دام الرضا حاصلاً. ورفع حرجاً آخر: منهم من كان يتحرّج أن يأكل وحده، ومنهم من يتحرّج من الأكل الجماعي خشية أن يؤذي غيره، فقال: ليس عليكم جناح أن تأكلوا مجتمعين أو متفرّقين. فإذا دخلتم بيوتاً، بيوتكم أو بيوت غيركم، فسلّموا على أهلها: السلام عليكم، وإن كان البيت خالياً أو مسجداً فقولوا: السلام علينا وعلى عباد الله الصالحين، تحية من عند الله مباركة طيبة، كذلك يبيّن الله لكم الآيات لعلكم تعقلون.", "h": ["الإذن العام في الأكل مع ذوي العاهات بلا تحرّج من الفريقين.", "الإذن في الأكل من بيوت من ذُكر في الآية من الأقارب والأصدقاء.", "جواز الأكل الجماعي والانفرادي بلا تحرّج.", "مشروعية التحية عند الدخول على البيوت، وأن فيها خيراً وفضلاً."], "k": "«فسلّموا على أنفسكم تحية من عند الله مباركة طيبة»… حين أدخل بيتي الليلة، أبدأ بالسلام."}, {"lbl": "الآيات ٦٢ – ٦٤", "q": "إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ عَلَىٰٓ أَمۡرٖ جَامِعٖ لَّمۡ يَذۡهَبُواْ حَتَّىٰ يَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ أُوْلَـٰٓئِكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ فَإِذَا ٱسۡتَـٔۡذَنُوكَ لِبَعۡضِ شَأۡنِهِمۡ فَأۡذَن لِّمَن شِئۡتَ مِنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٦٢﴾ لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمۡ لِوَاذٗاۚ فَلۡيَحۡذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنۡ أَمۡرِهِۦٓ أَن تُصِيبَهُمۡ فِتۡنَةٌ أَوۡ يُصِيبَهُمۡ عَذَابٌ أَلِيمٌ ﴿٦٣﴾ أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قَدۡ يَعۡلَمُ مَآ أَنتُمۡ عَلَيۡهِ وَيَوۡمَ يُرۡجَعُونَ إِلَيۡهِ فَيُنَبِّئُهُم بِمَا عَمِلُواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ ﴿٦٤﴾", "w": [["أمر جامع", "كخطبة الجمعة ونحوها مما يجب حضوره كاجتماع لأمر هام."], ["يستأذنوه", "يطلبوا منه ﷺ الإذن."], ["لبعض شأنهم", "لبعض أمورهم الخاصة بهم."], ["دعاء الرسول", "نداءه، فلا يُنادى: يا محمد، ولكن: يا نبي الله، يا رسول الله."], ["كدعاء بعضكم بعضاً", "كما ينادي بعضكم بعضاً: يا عمر، يا سعيد."], ["يتسلّلون منكم لواذاً", "ينسلّون واحداً بعد واحد، يستر بعضهم بعضاً حتى يخرجوا خفية."], ["أن تصيبهم فتنة", "زيغ في قلوبهم فيكفروا."], ["قد يعلم ما أنتم عليه", "من الإيمان والنفاق، وإرادة الخير أو الشر."]], "m": "يخبر تعالى أن المؤمنين الكاملين في إيمانهم هم الذين آمنوا بالله ورسوله، وإذا كانوا معه على أمر جامع يتطلّب حضورهم كالجمعة واجتماعات الحرب لم يذهبوا حتى يستأذنوه، إن الذين يستأذنونك أولئك الذين يؤمنون بالله ورسوله، ومقابله أن الذين يخرجون بدون إذن هم المنافقون، فإذا استأذنوك لبعض شأنهم فأذن لمن شئت ممن لا أهمية لحضوره، واستغفر لهم الله لما قد يكون من غير عذر شرعي، إن الله غفور رحيم. لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضاً، ويحتمل أموراً: أن يحذروا إغضابه فإن دعا عليهم هلكوا لأن دعاءه لا يُردّ، وألا ينادوه باسمه بل: يا نبي الله، يا رسول الله، وألا يغلظوا له في العبارة إكباراً وتعظيماً. قد يعلم الله المنافقين الذين يتسلّلون واحداً بعد آخر بلا إذن، يستر بعضهم بعضاً، فليحذر الذين يخالفون أمره، وهو عام إلى يوم القيامة، أن تصيبهم فتنة زيغ في قلوبهم فيموتوا كافرين، أو يصيبهم عذاب أليم. ألا إن لله ما في السماوات والأرض، قد يعلم ما أنتم عليه، ويوم يُرجعون إليه فينبّئهم بما عملوا، والله بكل شيء عليم.", "h": ["وجوب الاستئذان من إمام المسلمين إذا كان الأمر جامعاً، وللإمام أن يأذن لمن شاء ويترك من يشاء حسب المصلحة العامة.", "وجوب تعظيم رسول الله ﷺ، وحرمة إساءة الأدب معه حياً وميتاً.", "وجوب طاعة رسول الله ﷺ، وحرمة مخالفة أمره ونهيه.", "المتجرّئ على الاستهانة بسنة الرسول ﷺ يُخشى عليه أن يموت على سوء الخاتمة، والعياذ بالله."], "k": "«فليحذر الذين يخالفون عن أمره»… سنّة أستهين بها؛ أحذر أن يكون ذلك زيغاً في القلب."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (255, 25, 1, 20, 'سورة الفرقان ١ – ٢٠', '«تبارك الذي نزّل الفرقان على عبده ليكون للعالمين نذيراً»، و«وقالوا ما لهذا الرسول يأكل الطعام»، و«قل أذلك خير أم جنة الخلد»، و«وجعلنا بعضكم لبعض فتنة أتصبرون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 255) = $j$[{"lbl": "الآيات ١ – ٣", "q": "تَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا ﴿١﴾ ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَيۡءٖ فَقَدَّرَهُۥ تَقۡدِيرٗا ﴿٢﴾ وَٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗ لَّا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ وَلَا يَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرّٗا وَلَا نَفۡعٗا وَلَا يَمۡلِكُونَ مَوۡتٗا وَلَا حَيَوٰةٗ وَلَا نُشُورٗا ﴿٣﴾", "w": [["تبارك", "تكاثرت بركته وعمّت الخلائق كلها."], ["الذي نزّل الفرقان", "الله الذي نزّل القرآن فارقاً بين الحق والباطل."], ["على عبده", "محمد ﷺ."], ["ليكون للعالمين نذيراً", "ليكون محمد ﷺ نذيراً للعالمين من الإنس والجن، مخوّفاً لهم من عقاب الله إن كفروا."], ["فقدّره تقديراً", "سوّاه تسوية لا اعوجاج فيها ولا زيادة ولا نقص عما تقتضيه الحكمة."], ["ضراً ولا نفعاً", "لا دفع ضر ولا جلب نفع."], ["موتاً ولا حياة ولا نشوراً", "لا يقدرون على إماتة أحد ولا إحيائه ولا بعث الأموات."]], "m": "يثني الرب تبارك وتعالى على نفسه بأنه عظم خيره وعمّت بركته المخلوقات، الذي نزّل الفرقان، الكتاب الذي فرّق به بين الحق والباطل والتوحيد والشرك والعدل والظلم، على عبده ورسوله محمد ﷺ، ليكون للإنس والجن نذيراً عواقب الكفر والشرك والفساد في الدنيا والآخرة. الذي له ملك السماوات والأرض خلقاً وملكاً، ولم يتخذ ولداً، ولم يكن له شريك في الملك، وخلق كل شيء فقدّره تقديراً، ثناء بعد ثناء بالملك والقدرة والخلق والعلم والحكمة. واتخذوا من دونه أصناماً لا يخلقون شيئاً وهم يُخلقون، ولا يملكون لأنفسهم فضلاً عن عابديهم دفع ضر ولا جلب نفع، ولا يملكون موتاً ولا حياة ولا بعثاً، أليس هذا موضع تعجّب؟ مع الله الذي عمّت بركته الأكوان يتخذون آلهة لا تدفع عن نفسها ضراً، فسبحان الله أين يُذهب بعقول الناس!", "h": ["بيان صفات الله تعالى الموجبة لألوهيته، وهي إفاضة الخير على الخلق، والملك، والقدرة، والعلم، والحكمة.", "التنديد بالشرك والمشركين.", "تقرير التوحيد والنبوة والبعث والجزاء."], "k": "«تبارك الذي نزّل الفرقان»… أي بركة نالتني من هذا الفرقان، وكيف أستزيد منها؟"}, {"lbl": "الآيات ٤ – ٩", "q": "وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ إِفۡكٌ ٱفۡتَرَىٰهُ وَأَعَانَهُۥ عَلَيۡهِ قَوۡمٌ ءَاخَرُونَۖ فَقَدۡ جَآءُو ظُلۡمٗا وَزُورٗا ﴿٤﴾ وَقَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ٱكۡتَتَبَهَا فَهِيَ تُمۡلَىٰ عَلَيۡهِ بُكۡرَةٗ وَأَصِيلٗا ﴿٥﴾ قُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا ﴿٦﴾ وَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ لَوۡلَآ أُنزِلَ إِلَيۡهِ مَلَكٞ فَيَكُونَ مَعَهُۥ نَذِيرًا ﴿٧﴾ أَوۡ يُلۡقَىٰٓ إِلَيۡهِ كَنزٌ أَوۡ تَكُونُ لَهُۥ جَنَّةٞ يَأۡكُلُ مِنۡهَاۚ وَقَالَ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا ﴿٨﴾ ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَٰلَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا ﴿٩﴾", "w": [["إفك افتراه", "ما القرآن إلا كذب افتراه محمد، وليس هو بكلام الله."], ["ظلماً وزوراً", "ردّ الله عليهم: جاءوا ظلماً حيث جعلوا الكلام المعجز الهادي إفكاً، وزوراً بنسبة ما هو بريء منه إليه."], ["أساطير الأولين", "حكايات الأولين المسطّرة في كتبهم."], ["يعلم السر", "ما يسرّه أهل السماء والأرض وما يخفونه في نفوسهم."], ["أو يُلقى إليه كنز", "من السماء فينفق منه ولا يحتاج معه إلى الضرب في الأسواق."], ["جنة يأكل منها", "بستان فيه ما يغنيه من أنواع الحبوب والثمار."], ["رجلاً مسحوراً", "مخدوعاً مغلوباً على عقله."], ["ضربوا لك الأمثال", "بالسحر والجنون والشعر والكهانة والكذب."], ["فلا يستطيعون سبيلاً", "ضلّوا الطريق الحق فلا يهتدون."]], "m": "يخبر تعالى عن أولئك المشركين أنهم زيادة على سفههم في اتخاذ الأحجار آلهة قالوا في القرآن: ما هو إلا كذب اختلقه محمد وأعانه عليه قوم آخرون، يعنون اليهود، فقد جاءوا ظلماً بجعل القرآن الحامل للهدى كذباً، وزوراً بجعل من لم يكذب قط كاذباً. وقالوا: أساطير الأولين اكتتبها فهي تُملى عليه صباحاً ومساءً، نزلت في النضر بن الحارث، كان يأتي الحيرة ويتعلّم أخبار ملوك فارس، فإذا قام النبي ﷺ من مجلس يحذّر قومه ما أصاب الأمم قبلهم، جلس مكانه يحدّثهم ويقول: إن ما يقوله محمد من أساطير الأولين. فردّ الله: قل أنزله الذي يعلم السر في السماوات والأرض، ولولا أن رحمته سبقت غضبه لأهلك من كفر به، إنه كان غفوراً رحيماً. وقالوا، لما عرضوا عليه ملكاً أو مالاً أو جاهاً ليترك دعوته فرفض: ما لهذا الرسول يأكل الطعام ويمشي في الأسواق يطلب العيش مثلنا؟ هلّا أُنزل إليه ملك فيكون معه نذيراً، أو يُلقى إليه كنز، أو تكون له جنة يأكل منها؟ وقال الظالمون للمؤمنين: إن تتبعون إلا رجلاً مسحوراً. انظر كيف ضربوا لك الأمثال: ساحر وشاعر وكاهن ومجنون، فضلّوا طريق الحق فلا يستطيعون الرجوع إليه لبعد ضلالهم.", "h": ["بيان ما قابل به المشركون دعوة التوحيد من جلب كل قول باطل ليصدّوا عن سبيل الله، وما زال هذا دأب المشركين إزاء دعوة التوحيد إلى يوم القيامة.", "تقرير الوحي الإلهي والنبوة المحمدية.", "بيان حيرة المشركين إزاء دعوة الحق، وضربهم الأمثال الواهية للصدّ عن سبيل الله، وقد باءت كل محاولاتهم بالفشل."], "k": "«إنه كان غفوراً رحيماً»… ختم الآية بالرحمة بعد ذكر افترائهم؛ فما أوسع بابه للتائبين."}, {"lbl": "الآيات ١٠ – ١٦", "q": "تَبَارَكَ ٱلَّذِيٓ إِن شَآءَ جَعَلَ لَكَ خَيۡرٗا مِّن ذَٰلِكَ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَيَجۡعَل لَّكَ قُصُورَۢا ﴿١٠﴾ بَلۡ كَذَّبُواْ بِٱلسَّاعَةِۖ وَأَعۡتَدۡنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا ﴿١١﴾ إِذَا رَأَتۡهُم مِّن مَّكَانِۭ بَعِيدٖ سَمِعُواْ لَهَا تَغَيُّظٗا وَزَفِيرٗا ﴿١٢﴾ وَإِذَآ أُلۡقُواْ مِنۡهَا مَكَانٗا ضَيِّقٗا مُّقَرَّنِينَ دَعَوۡاْ هُنَالِكَ ثُبُورٗا ﴿١٣﴾ لَّا تَدۡعُواْ ٱلۡيَوۡمَ ثُبُورٗا وَٰحِدٗا وَٱدۡعُواْ ثُبُورٗا كَثِيرٗا ﴿١٤﴾ قُلۡ أَذَٰلِكَ خَيۡرٌ أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ لَهُمۡ جَزَآءٗ وَمَصِيرٗا ﴿١٥﴾ لَّهُمۡ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَۚ كَانَ عَلَىٰ رَبِّكَ وَعۡدٗا مَّسۡـُٔولٗا ﴿١٦﴾", "w": [["تبارك", "تقدّس وكثر خيره وعمّت بركته."], ["خيراً من ذلك", "الذي اقترحه المشركون عليك."], ["ويجعل لك قصوراً", "كثيرة لا قصراً واحداً كما قال المشركون."], ["بل كذّبوا بالساعة", "لم يكن المانع لهم من الإيمان كونك تأكل الطعام وتمشي في الأسواق، بل تكذيبهم بالبعث."], ["تغيّظاً وزفيراً", "صوتاً مزعجاً من تغيّظها على أصحابها المشركين."], ["مقرّنين", "مقرونة أيديهم مع أعناقهم في الأصفاد."], ["دعوا هنالك ثبوراً", "نادوا: يا ثبوراه، أي يا هلاكاه."], ["كانت لهم جزاءً ومصيراً", "ثواباً على إيمانهم وتقواهم، ومصيراً لا يفارقونه."], ["وعداً مسئولاً", "مطالباً به، إذ المؤمنون يقولون: «ربنا وآتنا ما وعدتنا على رسلك»."]], "m": "ما زال السياق في الرد على مقترحات المشركين: تبارك الذي إن شاء جعل لك خيراً مما اقترحوه، جنات تجري من تحتها الأنهار، ويجعل لك قصوراً كثيرة، ولكنه لم يشأ ذلك لك في هذه الدار لأنها دار عمل لا دار جزاء. فاصبر، فإن المانع لهم من الإيمان ليس كونك بشراً تأكل الطعام، بل تكذيبهم بالساعة، فلو آمنوا بالحياة الثانية لطلبوا كل سبب ينجي من عذابها، وأعتدنا لمن كذّب بالساعة سعيراً. إذا رأتهم من مكان بعيد سمعوا لها تغيّظاً عليهم وزفيراً مزعجاً، وإذا أُلقوا منها مكاناً ضيقاً مشدودة أيديهم إلى أعناقهم نادوا بأعلى أصواتهم: يا هلاكاه احضر، فيقال لهم خزياً وتبكيتاً: لا تدعوا اليوم ثبوراً واحداً وادعوا ثبوراً كثيراً. قل: أذلك خير أم جنة الخلد التي وُعد المتقون، كانت لهم جزاءً ومصيراً، لهم فيها ما يشاءون من المطاعم والمشارب والمساكن خالدين، كان على ربك وعداً يسألونه إياه فينجزه لهم.", "h": ["بيان أن مردّ كفر الكافرين وظلم الظالمين وفساد المفسدين إلى تكذيبهم بالبعث والجزاء في الدار الآخرة، فإن من آمن بالبعث الآخر سارع إلى الطاعة والاستقامة.", "تقرير عقيدة البعث الآخر بوصف بعض ما يتم فيه من الجزاء بالنار والجنة.", "فضل التقوى، وأنها ملاك الأمر، فمن آمن واتقى فقد استوجب الدرجات العلى."], "k": "«قل أذلك خير أم جنة الخلد التي وُعد المتقون»… أضع الاختيار أمامي في كل قرار اليوم."}, {"lbl": "الآيات ١٧ – ٢٠", "q": "وَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَـٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ ﴿١٧﴾ قَالُواْ سُبۡحَٰنَكَ مَا كَانَ يَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ وَلَٰكِن مَّتَّعۡتَهُمۡ وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا ﴿١٨﴾ فَقَدۡ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسۡتَطِيعُونَ صَرۡفٗا وَلَا نَصۡرٗاۚ وَمَن يَظۡلِم مِّنكُمۡ نُذِقۡهُ عَذَابٗا كَبِيرٗا ﴿١٩﴾ وَمَآ أَرۡسَلۡنَا قَبۡلَكَ مِنَ ٱلۡمُرۡسَلِينَ إِلَّآ إِنَّهُمۡ لَيَأۡكُلُونَ ٱلطَّعَامَ وَيَمۡشُونَ فِي ٱلۡأَسۡوَاقِۗ وَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضٖ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِيرٗا ﴿٢٠﴾", "w": [["يحشرهم", "يجمعهم."], ["وما يعبدون من دون الله", "من الملائكة والأنبياء والأولياء والجن."], ["أم هم ضلّوا السبيل", "طريق الحق بأنفسهم بدون دعوتكم إياهم إلى ذلك."], ["سبحانك", "تنزيهاً لك عما لا يليق بجلالك وكمالك."], ["ولكن متّعتهم", "بأن أطلت أعمارهم ووسّعت عليهم أرزاقهم."], ["وكانوا قوماً بوراً", "هلكى، إذ البوار الهلاك."], ["ومن يظلم منكم", "ومن يشرك منكم أيها الناس."], ["وجعلنا بعضكم لبعض فتنة", "بليّة، فالغني مبتلى بالفقير، والصحيح بالمريض، والشريف بالوضيع."], ["أتصبرون", "اصبروا على ما تسمعون ممن ابتُليتم بهم، فالاستفهام هنا للأمر."], ["وكان ربك بصيراً", "بمن يصبر وبمن يجزع ولا يصبر."]], "m": "ما زال السياق في تقرير البعث، إذ إنكاره سبب كل شر: واذكر يوم يحشر الله المشركين وما يعبدونهم من دونه كالملائكة والمسيح والأولياء والجن، فيقول للمعبودين: أأنتم أضللتم عبادي هؤلاء، أم هم ضلّوا السبيل بأنفسهم؟ فيقولون: سبحانك، ما كان ينبغي لنا أن نتخذ من دونك من أولياء فندعو عبادك إلى عبادتنا، ولكن متّعتهم وآباءهم بطول الأعمار وسعة الأرزاق فانغمسوا في الشهوات حتى نسوا ذكرك وما جاءتهم به رسلك، وكانوا قوماً هلكى خاسرين. فقد كذّبكم من كنتم تشركون به، فقامت الحجة عليكم، فما تستطيعون صرف العذاب ولا نصراً، ومن يشرك منكم نذقه عذاباً كبيراً. وما أرسلنا قبلك من المرسلين إلا إنهم ليأكلون الطعام ويمشون في الأسواق، فلا تهتم بقول المشركين، فإنهم يعرفون ذلك ولكنهم يكابرون. وجعلنا بعضكم لبعض فتنة، هذه سنّتنا: نبتلي المؤمن بالكافر، والغني بالفقير، والصحيح بالمريض، وننظر من يصبر ومن يجزع، أتصبرون؟ أي اصبروا ولا تجزعوا من أذى المشركين، وكان ربك بصيراً بمن يصبر وبمن يجزع، وإنما يوفّى الصابرون أجرهم بغير حساب.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان هول الموقف إذا سُئل المعبودون عمن عبدوهم، والمظلومون عمن ظلموهم.", "براءة الملائكة والأنبياء والأولياء من عبادة من عبدوهم.", "خطورة طول العمر وسعة الرزق، إذ غالباً ما ينسى العبد بهما ربه ولقاءه."], "k": "«وجعلنا بعضكم لبعض فتنة أتصبرون»… من الشخص الذي ابتُليت به؟ وهل أصبر عليه احتساباً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 255;
insert into public.tdb_cards(topic, i, body) select 255, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "تَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا ﴿١﴾ ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَيۡءٖ فَقَدَّرَهُۥ تَقۡدِيرٗا ﴿٢﴾ وَٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗ لَّا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ وَلَا يَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرّٗا وَلَا نَفۡعٗا وَلَا يَمۡلِكُونَ مَوۡتٗا وَلَا حَيَوٰةٗ وَلَا نُشُورٗا ﴿٣﴾", "w": [["تبارك", "تكاثرت بركته وعمّت الخلائق كلها."], ["الذي نزّل الفرقان", "الله الذي نزّل القرآن فارقاً بين الحق والباطل."], ["على عبده", "محمد ﷺ."], ["ليكون للعالمين نذيراً", "ليكون محمد ﷺ نذيراً للعالمين من الإنس والجن، مخوّفاً لهم من عقاب الله إن كفروا."], ["فقدّره تقديراً", "سوّاه تسوية لا اعوجاج فيها ولا زيادة ولا نقص عما تقتضيه الحكمة."], ["ضراً ولا نفعاً", "لا دفع ضر ولا جلب نفع."], ["موتاً ولا حياة ولا نشوراً", "لا يقدرون على إماتة أحد ولا إحيائه ولا بعث الأموات."]], "m": "يثني الرب تبارك وتعالى على نفسه بأنه عظم خيره وعمّت بركته المخلوقات، الذي نزّل الفرقان، الكتاب الذي فرّق به بين الحق والباطل والتوحيد والشرك والعدل والظلم، على عبده ورسوله محمد ﷺ، ليكون للإنس والجن نذيراً عواقب الكفر والشرك والفساد في الدنيا والآخرة. الذي له ملك السماوات والأرض خلقاً وملكاً، ولم يتخذ ولداً، ولم يكن له شريك في الملك، وخلق كل شيء فقدّره تقديراً، ثناء بعد ثناء بالملك والقدرة والخلق والعلم والحكمة. واتخذوا من دونه أصناماً لا يخلقون شيئاً وهم يُخلقون، ولا يملكون لأنفسهم فضلاً عن عابديهم دفع ضر ولا جلب نفع، ولا يملكون موتاً ولا حياة ولا بعثاً، أليس هذا موضع تعجّب؟ مع الله الذي عمّت بركته الأكوان يتخذون آلهة لا تدفع عن نفسها ضراً، فسبحان الله أين يُذهب بعقول الناس!", "h": ["بيان صفات الله تعالى الموجبة لألوهيته، وهي إفاضة الخير على الخلق، والملك، والقدرة، والعلم، والحكمة.", "التنديد بالشرك والمشركين.", "تقرير التوحيد والنبوة والبعث والجزاء."], "k": "«تبارك الذي نزّل الفرقان»… أي بركة نالتني من هذا الفرقان، وكيف أستزيد منها؟"}, {"lbl": "الآيات ٤ – ٩", "q": "وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ إِفۡكٌ ٱفۡتَرَىٰهُ وَأَعَانَهُۥ عَلَيۡهِ قَوۡمٌ ءَاخَرُونَۖ فَقَدۡ جَآءُو ظُلۡمٗا وَزُورٗا ﴿٤﴾ وَقَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ٱكۡتَتَبَهَا فَهِيَ تُمۡلَىٰ عَلَيۡهِ بُكۡرَةٗ وَأَصِيلٗا ﴿٥﴾ قُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا ﴿٦﴾ وَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ لَوۡلَآ أُنزِلَ إِلَيۡهِ مَلَكٞ فَيَكُونَ مَعَهُۥ نَذِيرًا ﴿٧﴾ أَوۡ يُلۡقَىٰٓ إِلَيۡهِ كَنزٌ أَوۡ تَكُونُ لَهُۥ جَنَّةٞ يَأۡكُلُ مِنۡهَاۚ وَقَالَ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا ﴿٨﴾ ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَٰلَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا ﴿٩﴾", "w": [["إفك افتراه", "ما القرآن إلا كذب افتراه محمد، وليس هو بكلام الله."], ["ظلماً وزوراً", "ردّ الله عليهم: جاءوا ظلماً حيث جعلوا الكلام المعجز الهادي إفكاً، وزوراً بنسبة ما هو بريء منه إليه."], ["أساطير الأولين", "حكايات الأولين المسطّرة في كتبهم."], ["يعلم السر", "ما يسرّه أهل السماء والأرض وما يخفونه في نفوسهم."], ["أو يُلقى إليه كنز", "من السماء فينفق منه ولا يحتاج معه إلى الضرب في الأسواق."], ["جنة يأكل منها", "بستان فيه ما يغنيه من أنواع الحبوب والثمار."], ["رجلاً مسحوراً", "مخدوعاً مغلوباً على عقله."], ["ضربوا لك الأمثال", "بالسحر والجنون والشعر والكهانة والكذب."], ["فلا يستطيعون سبيلاً", "ضلّوا الطريق الحق فلا يهتدون."]], "m": "يخبر تعالى عن أولئك المشركين أنهم زيادة على سفههم في اتخاذ الأحجار آلهة قالوا في القرآن: ما هو إلا كذب اختلقه محمد وأعانه عليه قوم آخرون، يعنون اليهود، فقد جاءوا ظلماً بجعل القرآن الحامل للهدى كذباً، وزوراً بجعل من لم يكذب قط كاذباً. وقالوا: أساطير الأولين اكتتبها فهي تُملى عليه صباحاً ومساءً، نزلت في النضر بن الحارث، كان يأتي الحيرة ويتعلّم أخبار ملوك فارس، فإذا قام النبي ﷺ من مجلس يحذّر قومه ما أصاب الأمم قبلهم، جلس مكانه يحدّثهم ويقول: إن ما يقوله محمد من أساطير الأولين. فردّ الله: قل أنزله الذي يعلم السر في السماوات والأرض، ولولا أن رحمته سبقت غضبه لأهلك من كفر به، إنه كان غفوراً رحيماً. وقالوا، لما عرضوا عليه ملكاً أو مالاً أو جاهاً ليترك دعوته فرفض: ما لهذا الرسول يأكل الطعام ويمشي في الأسواق يطلب العيش مثلنا؟ هلّا أُنزل إليه ملك فيكون معه نذيراً، أو يُلقى إليه كنز، أو تكون له جنة يأكل منها؟ وقال الظالمون للمؤمنين: إن تتبعون إلا رجلاً مسحوراً. انظر كيف ضربوا لك الأمثال: ساحر وشاعر وكاهن ومجنون، فضلّوا طريق الحق فلا يستطيعون الرجوع إليه لبعد ضلالهم.", "h": ["بيان ما قابل به المشركون دعوة التوحيد من جلب كل قول باطل ليصدّوا عن سبيل الله، وما زال هذا دأب المشركين إزاء دعوة التوحيد إلى يوم القيامة.", "تقرير الوحي الإلهي والنبوة المحمدية.", "بيان حيرة المشركين إزاء دعوة الحق، وضربهم الأمثال الواهية للصدّ عن سبيل الله، وقد باءت كل محاولاتهم بالفشل."], "k": "«إنه كان غفوراً رحيماً»… ختم الآية بالرحمة بعد ذكر افترائهم؛ فما أوسع بابه للتائبين."}, {"lbl": "الآيات ١٠ – ١٦", "q": "تَبَارَكَ ٱلَّذِيٓ إِن شَآءَ جَعَلَ لَكَ خَيۡرٗا مِّن ذَٰلِكَ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَيَجۡعَل لَّكَ قُصُورَۢا ﴿١٠﴾ بَلۡ كَذَّبُواْ بِٱلسَّاعَةِۖ وَأَعۡتَدۡنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا ﴿١١﴾ إِذَا رَأَتۡهُم مِّن مَّكَانِۭ بَعِيدٖ سَمِعُواْ لَهَا تَغَيُّظٗا وَزَفِيرٗا ﴿١٢﴾ وَإِذَآ أُلۡقُواْ مِنۡهَا مَكَانٗا ضَيِّقٗا مُّقَرَّنِينَ دَعَوۡاْ هُنَالِكَ ثُبُورٗا ﴿١٣﴾ لَّا تَدۡعُواْ ٱلۡيَوۡمَ ثُبُورٗا وَٰحِدٗا وَٱدۡعُواْ ثُبُورٗا كَثِيرٗا ﴿١٤﴾ قُلۡ أَذَٰلِكَ خَيۡرٌ أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ لَهُمۡ جَزَآءٗ وَمَصِيرٗا ﴿١٥﴾ لَّهُمۡ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَۚ كَانَ عَلَىٰ رَبِّكَ وَعۡدٗا مَّسۡـُٔولٗا ﴿١٦﴾", "w": [["تبارك", "تقدّس وكثر خيره وعمّت بركته."], ["خيراً من ذلك", "الذي اقترحه المشركون عليك."], ["ويجعل لك قصوراً", "كثيرة لا قصراً واحداً كما قال المشركون."], ["بل كذّبوا بالساعة", "لم يكن المانع لهم من الإيمان كونك تأكل الطعام وتمشي في الأسواق، بل تكذيبهم بالبعث."], ["تغيّظاً وزفيراً", "صوتاً مزعجاً من تغيّظها على أصحابها المشركين."], ["مقرّنين", "مقرونة أيديهم مع أعناقهم في الأصفاد."], ["دعوا هنالك ثبوراً", "نادوا: يا ثبوراه، أي يا هلاكاه."], ["كانت لهم جزاءً ومصيراً", "ثواباً على إيمانهم وتقواهم، ومصيراً لا يفارقونه."], ["وعداً مسئولاً", "مطالباً به، إذ المؤمنون يقولون: «ربنا وآتنا ما وعدتنا على رسلك»."]], "m": "ما زال السياق في الرد على مقترحات المشركين: تبارك الذي إن شاء جعل لك خيراً مما اقترحوه، جنات تجري من تحتها الأنهار، ويجعل لك قصوراً كثيرة، ولكنه لم يشأ ذلك لك في هذه الدار لأنها دار عمل لا دار جزاء. فاصبر، فإن المانع لهم من الإيمان ليس كونك بشراً تأكل الطعام، بل تكذيبهم بالساعة، فلو آمنوا بالحياة الثانية لطلبوا كل سبب ينجي من عذابها، وأعتدنا لمن كذّب بالساعة سعيراً. إذا رأتهم من مكان بعيد سمعوا لها تغيّظاً عليهم وزفيراً مزعجاً، وإذا أُلقوا منها مكاناً ضيقاً مشدودة أيديهم إلى أعناقهم نادوا بأعلى أصواتهم: يا هلاكاه احضر، فيقال لهم خزياً وتبكيتاً: لا تدعوا اليوم ثبوراً واحداً وادعوا ثبوراً كثيراً. قل: أذلك خير أم جنة الخلد التي وُعد المتقون، كانت لهم جزاءً ومصيراً، لهم فيها ما يشاءون من المطاعم والمشارب والمساكن خالدين، كان على ربك وعداً يسألونه إياه فينجزه لهم.", "h": ["بيان أن مردّ كفر الكافرين وظلم الظالمين وفساد المفسدين إلى تكذيبهم بالبعث والجزاء في الدار الآخرة، فإن من آمن بالبعث الآخر سارع إلى الطاعة والاستقامة.", "تقرير عقيدة البعث الآخر بوصف بعض ما يتم فيه من الجزاء بالنار والجنة.", "فضل التقوى، وأنها ملاك الأمر، فمن آمن واتقى فقد استوجب الدرجات العلى."], "k": "«قل أذلك خير أم جنة الخلد التي وُعد المتقون»… أضع الاختيار أمامي في كل قرار اليوم."}, {"lbl": "الآيات ١٧ – ٢٠", "q": "وَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَـٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ ﴿١٧﴾ قَالُواْ سُبۡحَٰنَكَ مَا كَانَ يَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ وَلَٰكِن مَّتَّعۡتَهُمۡ وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا ﴿١٨﴾ فَقَدۡ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسۡتَطِيعُونَ صَرۡفٗا وَلَا نَصۡرٗاۚ وَمَن يَظۡلِم مِّنكُمۡ نُذِقۡهُ عَذَابٗا كَبِيرٗا ﴿١٩﴾ وَمَآ أَرۡسَلۡنَا قَبۡلَكَ مِنَ ٱلۡمُرۡسَلِينَ إِلَّآ إِنَّهُمۡ لَيَأۡكُلُونَ ٱلطَّعَامَ وَيَمۡشُونَ فِي ٱلۡأَسۡوَاقِۗ وَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضٖ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِيرٗا ﴿٢٠﴾", "w": [["يحشرهم", "يجمعهم."], ["وما يعبدون من دون الله", "من الملائكة والأنبياء والأولياء والجن."], ["أم هم ضلّوا السبيل", "طريق الحق بأنفسهم بدون دعوتكم إياهم إلى ذلك."], ["سبحانك", "تنزيهاً لك عما لا يليق بجلالك وكمالك."], ["ولكن متّعتهم", "بأن أطلت أعمارهم ووسّعت عليهم أرزاقهم."], ["وكانوا قوماً بوراً", "هلكى، إذ البوار الهلاك."], ["ومن يظلم منكم", "ومن يشرك منكم أيها الناس."], ["وجعلنا بعضكم لبعض فتنة", "بليّة، فالغني مبتلى بالفقير، والصحيح بالمريض، والشريف بالوضيع."], ["أتصبرون", "اصبروا على ما تسمعون ممن ابتُليتم بهم، فالاستفهام هنا للأمر."], ["وكان ربك بصيراً", "بمن يصبر وبمن يجزع ولا يصبر."]], "m": "ما زال السياق في تقرير البعث، إذ إنكاره سبب كل شر: واذكر يوم يحشر الله المشركين وما يعبدونهم من دونه كالملائكة والمسيح والأولياء والجن، فيقول للمعبودين: أأنتم أضللتم عبادي هؤلاء، أم هم ضلّوا السبيل بأنفسهم؟ فيقولون: سبحانك، ما كان ينبغي لنا أن نتخذ من دونك من أولياء فندعو عبادك إلى عبادتنا، ولكن متّعتهم وآباءهم بطول الأعمار وسعة الأرزاق فانغمسوا في الشهوات حتى نسوا ذكرك وما جاءتهم به رسلك، وكانوا قوماً هلكى خاسرين. فقد كذّبكم من كنتم تشركون به، فقامت الحجة عليكم، فما تستطيعون صرف العذاب ولا نصراً، ومن يشرك منكم نذقه عذاباً كبيراً. وما أرسلنا قبلك من المرسلين إلا إنهم ليأكلون الطعام ويمشون في الأسواق، فلا تهتم بقول المشركين، فإنهم يعرفون ذلك ولكنهم يكابرون. وجعلنا بعضكم لبعض فتنة، هذه سنّتنا: نبتلي المؤمن بالكافر، والغني بالفقير، والصحيح بالمريض، وننظر من يصبر ومن يجزع، أتصبرون؟ أي اصبروا ولا تجزعوا من أذى المشركين، وكان ربك بصيراً بمن يصبر وبمن يجزع، وإنما يوفّى الصابرون أجرهم بغير حساب.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان هول الموقف إذا سُئل المعبودون عمن عبدوهم، والمظلومون عمن ظلموهم.", "براءة الملائكة والأنبياء والأولياء من عبادة من عبدوهم.", "خطورة طول العمر وسعة الرزق، إذ غالباً ما ينسى العبد بهما ربه ولقاءه."], "k": "«وجعلنا بعضكم لبعض فتنة أتصبرون»… من الشخص الذي ابتُليت به؟ وهل أصبر عليه احتساباً؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;